WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[55837] = { title = "Bounty: Dangerous Creatures", description = "There are creatures in Nazjatar that are far more dangerous than their peers. I leave it to you to find them and defeat them.\n\nWhen you've done your part, report to the quartermaster to claim your reward.", objectives = "" }
WordHunterWoW_QuestEN[55838] = { title = "Bounty: Lots of Hydras", description = "The hydra population is disrupting endeavors within Nazjatar. Kill on sight.\n\nReport to the quartermaster to claim your reward.", objectives = "" }
WordHunterWoW_QuestEN[55839] = { title = "Bounty: Lots of Coral Ancients", description = "Coral ancients are beginning to awaken from their long slumber. I warn you, these are very dangerous creatures of immense size and power. If more of them begin to awaken, our forces will be in great danger.\n\nOnce you have defeated some of these ancients, report to the quartermaster to claim your reward.", objectives = "" }
WordHunterWoW_QuestEN[55840] = { title = "Bounty: Lots of Makrura", description = "The makrura have been a thorn in our side for too long. They are aggressive towards almost all species in Nazjatar and are very dangerous is groups. Less of them in our waters would certainly benefit our cause.\n\nOnce you are done, report to the quartermaster to claim your reward.", objectives = "" }
WordHunterWoW_QuestEN[55841] = { title = "Bounty: Lots of Crabs", description = "The crab population is expanding too quickly within Nazjatar, endangering local plant life. Cull their numbers in our conservation effort.\n\nReport to the quartermaster to claim your reward.", objectives = "" }
WordHunterWoW_QuestEN[55842] = { title = "Bounty: Lots of Snapdragons", description = "Snapdragons are one of the most dangerous species on Nazjatar. The naga breed them for the viciousness and their ability as trackers.\n\nIf we hope to keep our positions hidden from the naga, we must take out these groups of snapdragons immediately.\n\nAfter you are done, report to the quartermaster to claim your reward.", objectives = "" }
WordHunterWoW_QuestEN[55843] = { title = "Bounty: Lots of Fathom Rays", description = "The fathom ray population is eating all of the coral buds to the east. If we do not cull their numbers, we may have an environmental catastrophe on our hands.\n\nOnce you have finished, report to the quartermaster to claim your reward.", objectives = "" }
WordHunterWoW_QuestEN[55844] = { title = "Bounty: Lots of Elementals", description = "The elemental population is disrupting endeavors within Nazjatar. Kill on sight.\n\nReport to the quartermaster to claim your reward.", objectives = "" }
WordHunterWoW_QuestEN[55845] = { title = "Plans of Attack", description = "<The attack plans are written on the parchment in fluorescent squid-ink and bound together with Azshara's seal.>\n\nOrders from our queen:\n\nQueen Azshara has commanded that all naga forces prepare for a full assault upon the Alliance invaders in our land. Details for the attack have been distributed to your various unit commanders.\n\nThe Alliance shall tremble at the might of our queen!", objectives = "" }
WordHunterWoW_QuestEN[55846] = { title = "Forbidden Rituals", description = "The naga use dark, forbidden rituals to subjugate the elements to their will.\n\nBut such rituals threaten to destroy the elemental balance that binds this world together. The rituals must be stopped. \n\nFortunately, the rituals the naga use are too elaborate to commit to memory. The ritual instructions are contained within ancient texts.\n\nIf we destroy the ancient tomes that contain the rituals, the knowledge will be lost to the naga forever.\n\nRetrieve the tomes and I will see that they are destroyed", objectives = "" }
WordHunterWoW_QuestEN[55851] = { title = "Essential Empowerment", description = "Champion, excitin' news!\n\nI know yer busy dealin' with the naga threat right now, but we need ye to come back tae the Chamber of Heart! MOTHER's finally finished her calculations and she's got an idea of what tae do next!\n\nHurry back tae Silithus as quick as ye can. Azeroth needs ye!", objectives = "" }
WordHunterWoW_QuestEN[55860] = { title = "Sea Slug Liquidation", description = "My brief studies have shown that the refinement process creates a byproduct that is invisible to the naked eye, but is easily seen with refracted bioluminescent light. \n\nThe sea floor is littered with creatures that produce just what we need to track down this weapons cache.", objectives = "" }
WordHunterWoW_QuestEN[55861] = { title = "Let the Residue Lead You", description = "I have fashioned a device that will emit bioluminescent light when toggled on, allowing you to see any Azerite residue that lingers. \n\nIt should give you a clear trail to the weapons cache. \n\nGood luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[55862] = { title = "Insight into Our Enemies", description = "There's no telling what awaits us within this land. We cannot press forward without first knowing exactly what we're up against. \n\nAlthough our new allies have suffered greatly at the hands of the naga, their hardships will not be in vain. \n\nThe kelfin should have invaluable knowledge of Azshara's forces. \n\nWith their help, we might be able to learn more about how our enemies operate.\n\nSpeak with Neri and see what insight she can provide.", objectives = "" }
WordHunterWoW_QuestEN[55863] = { title = "Deteriorating Knowledge", description = "The kelfin are no strangers to Azshara's cruelty. \n\nShe commands creatures of darkness that entrap my kind and warp their minds. They eat away at their memories until nothing's left but an empty husk. \n\nIf you can get to them soon, perhaps they'll still be in a state worth saving.", objectives = "" }
WordHunterWoW_QuestEN[55864] = { title = "The Price is Death", description = "We've long believed that the ocean is big enough for all that wish to call it home. \n\nUnfortunately, the naga don't see it that way. \n\nThey kill and capture our kind without remorse, and it's about time they paid the price.", objectives = "" }
WordHunterWoW_QuestEN[55865] = { title = "What We Know of the Naga", description = "It feels good to be me again. I have you to thank for that.\n\nMy head still hurts from the zoatroid's influence, but I think the others are worse off.\n\nPut some of this salve on their wounds, and I'll do my best to tell you what I know about the naga.", objectives = "" }
WordHunterWoW_QuestEN[55866] = { title = "Scouting Undercover", description = "Entering the stronghold alone would be a death wish.\n\nThe Zanj'ir slaughter outsiders on sight. \n\nThe only way to get in without being killed is to appear to be under the effects of a zoatroid. \n\nEven then, the mind-shackled are put to work. \n\nYou must obey all commands, or they will know your mind is still your own. \n\nOnce the Zanj'ir believe you are mind-shackled, it should be easier to navigate their domain and uncover their secret.", objectives = "" }
WordHunterWoW_QuestEN[55867] = { title = "Coveted Crystals", description = "Locating the weapons cache shouldn't be a problem once we have the proper tools. A little light and a lot of bioluminescent fluid is all we need!\n\nIt all seems rather simple, doesn't it? But the key is in the Deepsea Crystal used to refract the light. \n\nI am told that the Bloodfin tribe covets these crystals, so it shouldn't be too much trouble to get your hands on one.", objectives = "" }
WordHunterWoW_QuestEN[55868] = { title = "Let the Residue Lead You", description = "I've fashioned a device that will emit bioluminescent light when toggled on, allowing you to see any Azerite residue that lingers. \n\nIt should give you a clear trail to the weapons cache. \n\nGood luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[55869] = { title = "Clearing Out the Cache", description = "<While inspecting the crate, a commotion can be heard within the cavern. A familiar voice, shouting orders.>", objectives = "" }
WordHunterWoW_QuestEN[55870] = { title = "Sea Slug Liquidation", description = "The Azerite refinement process creates a byproduct that is invisible to the naked eye, but is easily seen with refracted bioluminescent light. \n\nThe sea floor is littered with creatures that produce just what we need to track down this weapons cache.", objectives = "" }
WordHunterWoW_QuestEN[55871] = { title = "Gather Friends", description = "Outside is dangerous.\n\nIt is safe in the Kelfin Pocket. \n\nWe find the lost crabs, and slugs, and other friends.\n\nHere they get a new name and a new home. \n\nFind friends like these, and bring them home.", objectives = "" }
WordHunterWoW_QuestEN[55872] = { title = "Where They Hide", description = "Those sneaky snakes have started to send assassins.\n\nThey hide nearby and kill those they cannot take away to the slave pens.\n\nEven the sponges want to be rid of them! \n\nThe spores will reveal the naga treachery... and then you can go ahead and kill them. \n\nWe must keep our people safe!", objectives = "" }
WordHunterWoW_QuestEN[55873] = { title = "Kill the Kritch", description = "Mrgglrr! Mrlg rmglr grlmrrgrr, grmm mrgl grrmrrgllrr. \n\n<Rlgmrr jumps around anxiously and points toward the cave.>\n\nGrrmrlgr mrg lrglgllmrrglm mlr mrlglmrgm mrl Kriiitchrglgr.\n\n<He makes a scary face and pinching motions with his hands.>\n\nMrglrmgr lrg, mrgglmmmr! Mrlg grrrrml lrg.", objectives = "" }
WordHunterWoW_QuestEN[55874] = { title = "Plug the Geysers", description = "We're getting a geyser hit any minute now.\n\nThe effects of the Tidestone are far-reaching.\n\nWe have to do what we can to prevent any further destruction.\n\nUse this sealant to stall off the next round of eruptions!", objectives = "" }
WordHunterWoW_QuestEN[55875] = { title = "Plug the Geysers", description = "Just keep watching this spot... any second now...\n\nOnce those geysers start firing, get in there and seal them up.\n\nThe more they shake, the more everything breaks apart!\n\nWe have to keep these things under control.", objectives = "" }
WordHunterWoW_QuestEN[55876] = { title = "Plug the Geysers", description = "Earthquakes! Snakes! Water coming from every direction.\n\nWhat is going on around here?\n\nNeri said to plug some holes in the defenses - didn't think she'd mean it literally.\n\nTake some of this goo, next eruption, stick it in the hole.", objectives = "" }
WordHunterWoW_QuestEN[55877] = { title = "Plug the Geysers", description = "We have been keeping an eye out for these unstable geysers.\n\nSince the water went away, the ocean has been trying to find a way back in.\n\nIf we let it burst up just anywhere, we could all be doomed!\n\nHelp me plug these up!\n\nBe careful, though, I found out the hard way they have a bit of a kick.", objectives = "" }
WordHunterWoW_QuestEN[55878] = { title = "Plug the Geysers", description = "Have you heard about the geysers? \n\nAll over the newly exposed areas, water trying to fill where it was pulled away.\n\nThe ocean, she is angry. I don't think she likes Azshara either.\n\nWe will keep filling this in until we can find a permanent fix.", objectives = "" }
WordHunterWoW_QuestEN[55879] = { title = "Ride of the Scientifically Enhanced Boar", description = "We don't know how long the re-sizing will last, so let's get moving.\n\nYou're going to ride this giant boar and mow down the army of undead between us and Wrathion.\n\nThe large ones are pulsing with shadow magic. If you kill them, I bet it they'll take out any enemies near them.\n\nLet's hope Wrathion is willing to help us find Kalecgos.", objectives = "" }
WordHunterWoW_QuestEN[55880] = { title = "Redistribution of Power", description = "Welcome back, dear test subject.\n\nToday's experiment is...\n\n<Pristy flips through some papers and smiles.>\n\n...My pet project, the NRG-100!\n\nI am quite pleased with the potential improvements I've made to efficiency, potency, and destructivity.\n\nAnd the only thing I had to sacrifice was stability!\n\nWhen you're ready to proceed, strap on the NRG-100.", objectives = "" }
WordHunterWoW_QuestEN[55881] = { title = "Purge the Totems", description = "The harpies' totems are scattered throughout the area.\n\nHarpies are known for using their magic to corrupt those nearby. Even now, I can hear foul whispers in the air...\n\nWe must destroy these totems before any of us are tainted by their dark magic!", objectives = "" }
WordHunterWoW_QuestEN[55882] = { title = "Message to Base", description = "We did it! We're one step closer to getting off this island.\n\nLet's get back to camp and inform the captain of our success.", objectives = "" }
WordHunterWoW_QuestEN[55883] = { title = "To Soar Like a Ray", description = "I like to find the eggs of the fathom rays before they hatch so we can form a bond with them.\n\nAt least, when we can't swim, we can fly!\n\nBring me a few more eggs to start a new thing - we'll call them Rayriders!", objectives = "" }
WordHunterWoW_QuestEN[55885] = { title = "Rico's Rescue", description = "Some of our Roughriders are missing, I tried to find them, but got pinned down here by the bugs! \n\nI could really use your help, {name}. See if you can save my missing troopers.", objectives = "" }
WordHunterWoW_QuestEN[55905] = { title = "Abduction Reduction", description = "We got actual ABDUCTIONS happenin' here, {name}!\n\nHonest to gold, flying robots are swoopin' into town and snatchin' up people like it's closin' time at Gallywix's buffet!\n\nLucky for the Rustbolt Resistance, Gazlowe called in me and my explosives to save the day.\n\nYou wanna pitch in? Take one of my rocket launchers and blast those containment crates outta the sky.\n\nWhatever they've got trapped inside will come tumblin' down real fast, so you gotta run underneath and catch 'em.", objectives = "" }
WordHunterWoW_QuestEN[55937] = { title = "Clearing Out the Cache", description = "<While inspecting the crate, a commotion can be heard within the cavern. A familiar voice, shouting orders.>", objectives = "" }
WordHunterWoW_QuestEN[55965] = { title = "Westward Bound", description = "Captain Garrick wants us tae search west o' camp fer any other members of the expedition.\n\nAlaria and I will go on ahead. Meet us tae the west and we'll see what we can find.", objectives = "" }
WordHunterWoW_QuestEN[55967] = { title = "Sating Snapdragons", description = "It's time for the snapdragons to feed, but it's a job best left to someone a little more expendable. \n\nThe beasts will eat anything, including your arm if you don't move it away quickly enough. \n\nLuckily for you, they've developed a taste for Chitterspine Roe.", objectives = "" }
WordHunterWoW_QuestEN[55979] = { title = "Iteration is Key", description = "You've been holding out on me!\n\nHere I was, thinking that we're friends now and yet you neglected to tell me about your magnificient wrench!\n\n<Christy inspects it closely.>\n\nWell, not too magnificient... I recognize the Ub3r-Spanner from its blueprints, but whoever built this lacks a certain level of craftsmanship.\n\nI will upgrade it for you. Bring me the Overcharged Mecha-core from a mechanocrawler.\n\nNo excuses. I will fix your mistakes.", objectives = "" }
WordHunterWoW_QuestEN[55980] = { title = "Turn the Scale", description = "I have been trying to gather some of the scales from the young hydra nearby. \n\nTheir flexibility and strength makes them incredibly versatile.\n\nWith all the cranky old hydra tromping around, I don't stand much of a chance. \n\nCan you gather some up for me?", objectives = "" }
WordHunterWoW_QuestEN[55981] = { title = "Right Beneath Their Eyes", description = "We need to get inside Darkmaul Citadel, rescue the captain of the expedition, and stop the ogre behind all of this.\n\nMeredy is going to cast an illusion to make you look like an ogre, and you're going to take us all in as \"prisoners.\"\n\nI'll be hiding my efforts to suppress the shadow magic in the meantime.\n\nSpeak with Meredy when you're ready for her to cast the spell.\n\nHer illusion spell should be temporary, as long as she casts it in the proper way.", objectives = "" }
WordHunterWoW_QuestEN[55983] = { title = "A Safer Place", description = "<The murloc seems to be in rough shape. Perhaps it would be safer with your allies in Mezzamere.>", objectives = "" }
WordHunterWoW_QuestEN[55984] = { title = "A Good Offense", description = "Korl was told to watch the naga, so watching the naga I am.\n\nThey're bad, friend, you know... just... terrible, horrible, bad monsters. \n\nI don't think I can just watch any more.\n\nThey say the best defense is.. something...\n\nHelp me teach them being being bad gets you smashed!", objectives = "" }
WordHunterWoW_QuestEN[55985] = { title = "Extra Shiny", description = "In the pools below are some small, lovely pearls. \n\nThey were tossed in during some Azsh'ari ritual. \n\nDo they mean something? I have no idea. But I would like to have some of them. \n\nBe a lovely heavyfoot and go grab some for me, please!", objectives = "" }
WordHunterWoW_QuestEN[55986] = { title = "Break a Few Eggs", description = "This chamber is lovely and terrifying. \n\nWhat is born here will ruin the lives of so many. \n\nWe cannot hurt the pods, but we can destroy the eggs of the serpents that guard them.\n\nTake out the eggs, every little bit helps.\n\nPoor eggs...", objectives = "" }
WordHunterWoW_QuestEN[55988] = { title = "Like Ogres to the Slaughter", description = "This is bad, {name}. Captain Kelra is bound by magic, the ogres are preparing to attack our friends, and the ritual is almost complete!\n\nI have to stay calm. We can't give up now, right?\n\nThis may sound risky, but we need to take the fight to the ogres.\n\nWe're behind enemy lines, so we'll be able to get the jump on them and draw their focus away from the camp.\n\nTake down any ogres that you can. That should keep them away from our friends.", objectives = "" }
WordHunterWoW_QuestEN[55989] = { title = "Catapult Destruction", description = "Did you notice the catapults on our way up? It appears the ogres plan to attack our allies below.\n\nLindie anticipated something like this and provided several bombs to handle siege weapons.\n\nJust don't shake them too hard.", objectives = "" }
WordHunterWoW_QuestEN[55990] = { title = "Controlling their Stones", description = "Captain Kelra won't last much longer. We need to acquire the ward stones to break the ritual before it kills her.\n\nI'll continue weakening the main ritual. Get those ward stones from the ogre lieutenants nearby.", objectives = "" }
WordHunterWoW_QuestEN[55991] = { title = "An End to Beginnings", description = "You've done fine work within Exile's Reach, recruit. You should continue on to the Dragon Isles.\n\nI'm afraid I must change my plans and go back to Stormwind. I need to find out how the ogres found such powerful shadow magic.\n\nI'm sure we'll meet again. I can tell you've got many adventures ahead of you.", objectives = "" }
WordHunterWoW_QuestEN[55992] = { title = "Dungeon: Darkmaul Citadel", description = "You've slown down Gor'groth's efforts to control Kalecgos atop the citadel, but the ritual itself needs to be thwarted.\n\nYou must storm the citadel and stop him from completing the ritual. His dark magic is an affront to the Light.\n\nWe will need all the help we can get. Gor'groth's most elite lieutenants await within the citadel.", objectives = "" }
WordHunterWoW_QuestEN[55993] = { title = "A Little Edge", description = "In the darkest cavern. Below the naga city. You will find them.\n\nCreepy little crabs with sharp and pointy spines. \n\nI think we can find a way to use them. Projectiles didn't work so well in water, but now...\n\nHarvest some for us!\n\nBe careful, some of them are much sneakier than they have any right to be.", objectives = "" }
WordHunterWoW_QuestEN[55994] = { title = "Do Not Drink", description = "These troggs watch everything we do.  \n\nThey see us pouring oil into various machines, so now they're stealing the oil and drinking it. I think they believe it's going to turn them into machines!\n\nWe need that oil back, before they drink it all!", objectives = "" }
WordHunterWoW_QuestEN[55995] = { title = "We Can Fix It", description = "<This drill rig looks capable of breaking through the nearby debris, but is clearly broken.\n\nIf you can collect the parts required, Prince Erazmin should be able to show you how to repair it.>", objectives = "" }
WordHunterWoW_QuestEN[56000] = { title = "We've Got Crabs!", description = "{name}, you're just in time. Everything's ready for the crab hunt!\n\nOkay, okay... I know what you're thinking. A founding member of D.E.H.T.A. that condones hunting?\n\nI'm going to level with you, {name}. I've got a bar full of hungry murlocs that only eat three things: crabs, fish, and people.\n\nIf that's not reason enough, crabs are overpopulated in this region and they're decimating the local grub worm population!\n\nHow many innocent grub worms need to die before we do something, {name}?", objectives = "" }
WordHunterWoW_QuestEN[56001] = { title = "Drunk Angry Murlocs", description = "Those no-good Bloodfins ran off with all of the beer!\n\nI've been experimenting with brews that only use ingredients native to Nazjatar, but it's still a work in progress. For now, I must rely on whatever I can scrounge up from the shipwreck.\n\nMy supply of beer was already limited, but now it's all gone thanks to those thieving Bloodfin murlocs! We're going to have some very angry customers here if we don't get it back.\n\nPlease recover the stolen lager from Bloodfin Village before it's too late!", objectives = "" }
WordHunterWoW_QuestEN[56002] = { title = "Mgglurky's Mugglrgl", description = "My cook, Mgglurky, lost his mugglrgl and he's refusing to work until he gets it back.\n\nI've got a bar full of hungry murlocs and nothing to feed them until Mgglurky starts cooking. If Mgglurky doesn't find his mugglrgl soon, we're going to have a riot on our hands!\n\nI don't know about you, but I definitely don't want to be the main course tonight.\n\nThere were some Bloodfins lurking around earlier. Search Bloodfin Village for the mugglrgl and bring it back to me once you find it.", objectives = "" }
WordHunterWoW_QuestEN[56030] = { title = "The Warchief's Order", description = "Champion, the Dark Lady summons you. The time has come to set her plan into motion.\n\nOur warships are ready to embark. The key to victory over the Alliance is within our grasp.\n\nMeet me in Zuldazar, aboard the Banshee's Wail. What we do next... we do for the Horde.", objectives = "" }
WordHunterWoW_QuestEN[56031] = { title = "The Wolf's Offensive", description = "Champion, Spymaster Shaw reports that the remains of the Horde fleet is preparing to depart.\n\nThey will be easy pickings for our superior forces. Let us seize this opportunity to eliminate their threat once and for all!\n\nPreparations are underway to set sail. Come to Boralus Harbor and meet with me upon the Wind's Redemption with all haste!", objectives = "" }
WordHunterWoW_QuestEN[56034] = { title = "Re-sizing the Situation", description = "The Re-Sizer v9.0.1 barely works on inanimate objects. I have no idea what it will do to organic matter!\n\nBut if we do nothing, Wrathion will die!\n\nDesperate times call for massively experimental science, {name}.\n\nTake the Re-Sizer v9.0.1. I'll follow you around and calibrate it.\n\nWe're going to whip up a giant boar!", objectives = "" }
WordHunterWoW_QuestEN[56035] = { title = "Most Delicious Clams", description = "This pool is filled with creepy fish. \n\nIt is also the home of some of the most delicious clams you will ever eat. Fresh water somehow mixes into the ocean water in this one part of Nazjatar, and that gives the meat a totally new flavor.\n\nEvery now and then, we come down here and collect them for our friends in Newhome.\n\nWe could sure use some help with all these extra mouths to feed!", objectives = "" }
WordHunterWoW_QuestEN[56037] = { title = "Stealing the Naga's Secrets", description = "<Upon closer inspection, it becomes clear that the blades have been forged from Azerite. \n\nWeapons of this power should never be in the hands of the naga.>", objectives = "" }
WordHunterWoW_QuestEN[56038] = { title = "Working with Purpose", description = "It seems the Shirakess are never satisfied with the number of pearls we source for them. They're always demanding more. \n\nBefore you came along, it was my job to crawl around the cavern, cracking open clams. \n\nSo you see, you have some purpose, other than being a mindless sack of flesh.", objectives = "" }
WordHunterWoW_QuestEN[56039] = { title = "We Can't Have Dull Weapons", description = "For a squid head, you sure are making my life easier. \n\nI guess you get to live long enough to complete another task. \n\nOur new weapons are forged from some foreign material that I don't quite trust. \n\nYou won't catch me sharpening any blades, but the work still needs to get done. \n\nGet to it!", objectives = "" }
WordHunterWoW_QuestEN[56042] = { title = "Blingtron 7000", description = "", objectives = "" }
WordHunterWoW_QuestEN[56043] = { title = "Send the Fleet", description = "This war has cost us dearly, but victory will soon be in our grasp.\n\nWhat remains of the Horde fleet has departed Zuldazar and our spies say that the Banshee Queen's hand sails at their helm.\n\nThis is our chance, {name}! With one strike we can eliminate what remains of their fleet and rid Azeroth of Blightcaller's filth once and for all!\n\nThe fleet is preparing to depart, report to the Harbormaster when you are ready to set sail.", objectives = "" }
WordHunterWoW_QuestEN[56044] = { title = "Send the Fleet", description = "The Warchief has entrusted me with a mission of the highest priority, {name}.\n\nThe mission will succeed, of this there is no question, but to ensure that any obstacles I encounter are dealt with swiftly I once again have need of your particular skills.\n\nThe Zandalari have offered us use of their ships for this endeavor. Clear out whatever affairs you have remaining and report to Captain Rez'okun when you are ready to set sail.", objectives = "" }
WordHunterWoW_QuestEN[56045] = { title = "Stealing the Naga's Secrets", description = "<Upon closer inspection, it becomes clear that the blades have been forged from Azerite. \n\nWeapons of this power should never be in the hands of the naga.>", objectives = "" }
WordHunterWoW_QuestEN[56046] = { title = "Working with Purpose", description = "It seems the Shirakess are never satisfied with the number of pearls we source for them. They're always demanding more. \n\nBefore you came along, it was my job to crawl around the cavern, cracking open clams. \n\nSo you see, you have some purpose, other than being a mindless sack of flesh.", objectives = "" }
WordHunterWoW_QuestEN[56047] = { title = "We Can't Have Dull Weapons", description = "For a squid head, you sure are making my life easier. \n\nI guess you get to live long enough to complete another task. \n\nOur new weapons are forged from some foreign material that I don't quite trust. \n\nYou won't catch me sharpening any blades, but the work still needs to get done. \n\nGet to it!", objectives = "" }
WordHunterWoW_QuestEN[56049] = { title = "Deck 'Em", description = "That ooze seems really hungry!\n\nHe ate my backpack, compass, pickaxe, and my hearthstone cards.\n\nGet my cards back!", objectives = "" }
WordHunterWoW_QuestEN[56053] = { title = "The Final Act", description = "Those of us with enough mechanization survived, but it didn't matter. Bondo Bigblock sold us out. In exchange for full mechanization, he built giant bots and attacked Rustbolt. \n\nHe will continue to act against us, till those few of us left are dead. \n\nWe must remove this threat immediately.", objectives = "" }
WordHunterWoW_QuestEN[56063] = { title = "Dark Tides", description = "A Tidemistress leads the naga in this area.\n\nShe is performing some damnable ritual outside, demanding sacrifices of our soldiers.\n\nStop her before more of our own meet a cruel fate.", objectives = "" }
WordHunterWoW_QuestEN[56070] = { title = "Vengeance for the Venthyr", description = "Lord Denathrius has fallen under the sway of the Jailer. His betrayal of our people shall not stand.\n\nWe will show the Jailer that the venthyr are not to be underestimated... nor are you, Maw Walker. Slay his sub-lords. Let him know that he is now being hunted.", objectives = "" }
WordHunterWoW_QuestEN[56071] = { title = "De-Synced Vibro Blade", description = "The wildly shaking blade reminds you of the blades the Rustbolt defenders use. No doubt someone will be able to fix it up.", objectives = "" }
WordHunterWoW_QuestEN[56072] = { title = "De-Synced Vibro Blade", description = "The wildly shaking blade reminds you of the blades the Rustbolt defenders use. No doubt someone will be able to fix it up.", objectives = "" }
WordHunterWoW_QuestEN[56075] = { title = "Stolen Power", description = "From the void these naga pull their strength. \n\nEach scroll they record, shared knowledge -- that knowledge is power.\n\nIt stands to reason, if we take away their knowledge, we steal their power.\n\nMy logic may be flawed, but let's do it anyway!", objectives = "" }
WordHunterWoW_QuestEN[56080] = { title = "March of the Murlocs", description = "", objectives = "" }
WordHunterWoW_QuestEN[56081] = { title = "Octo-Grab", description = "", objectives = "" }
WordHunterWoW_QuestEN[56082] = { title = "Bot Rampage", description = "Those bots have been attacking us from the moment we landed. We've got to hold this beach!\n\nMy expedition guards could use your help, {name}. Lend a hand, destroy bots on the beach and in the nearby woodlands.", objectives = "" }
WordHunterWoW_QuestEN[56083] = { title = "Unsafe Work Conditions", description = "Those rampaging bots ain't lettin' up!\n\nWe're payin' good money for the best and brightest goblins on the planet, and I ain't gonna let some malfunctionin' machinery take 'em outta the shift schedule.\n\nThis is textbook unsafe working conditions, and the Greasemonkey Union reps are givin' me an earful for it. Protect the workers!", objectives = "" }
WordHunterWoW_QuestEN[56086] = { title = "Blueprint: Holographic Digitalization Relay", description = "<This blueprint details how to build what appears to be some form of holographic teleporter.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[56087] = { title = "Blueprint: Experimental Adventurer Augment", description = "<This blueprint details how to build what appears to be some form of ring... or maybe it's a trinket?\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[56091] = { title = "Usurper's Scent Gland", description = "When a new queen is born and old enough to start proliferating her own hive, she will leave the nest. Her scent will attract some of the hive to fly with her to their new home. This one likely never got the chance to do so, thanks to you.\n\nThe Hivemother will be interested in this item.", objectives = "" }
WordHunterWoW_QuestEN[56092] = { title = "Hivethief's Jelly Stash", description = "This ettin was a well known and oft dreaded face among the bees of the Honeyback hive. Their jelly stores will benefit from his demise.\n\nThe Hivemother will be interested in this item.", objectives = "" }
WordHunterWoW_QuestEN[56095] = { title = "Legacy of Nar'anan", description = "Hey there, {race}. Mind helping me out?\n\nYou see, I found these pylons here and it seems they contain memories from a notable Highborne who lived here long ago.\n\nI can't get any closer to the rest of em' because of the snapdragons. Especially the terrormaws...\n\nCan you go and activate the pylons for me? We Tortollans love old things, and this is a potential goldmine!\n\nOh, and be sure to write down what you see!", objectives = "" }
WordHunterWoW_QuestEN[56097] = { title = "Grime-Coated Disc", description = "<Look for someone that can help recover the data trapped on this grime-coated disc.>", objectives = "" }
WordHunterWoW_QuestEN[56098] = { title = "Defensive in Death", description = "<Having handled zin'anthid for a while now, you pluck one of its tentacles from the main body. As you do, the tentacle retracts, spiraling in on itself preventing you from getting to the blooms that reside along it. Perhaps Instructor Ulooaka will have more insight on how to keep this herb from defending itself.>", objectives = "" }
WordHunterWoW_QuestEN[56103] = { title = "Ounces of Osmenite", description = "<Picking away at the ore, you pick up some shards that have fallen to the ground. There ought to be a way to mine these deposits without wasting any of it. Perhaps Instructor Ulooaka knows of still a better way to mine this ore.>", objectives = "" }
WordHunterWoW_QuestEN[56108] = { title = "Leaving the Hive", description = "<The enormous bee twitches its antennae toward you. It swings its abdomen toward the cave exit.>\n\nBarry might know what's going on.", objectives = "" }
WordHunterWoW_QuestEN[56117] = { title = "Recyclable Parts", description = "<This bundle of recycling could be valuable. The gnomes in the area appear to be dropping their scrap into some nearby contraptions.>", objectives = "" }
WordHunterWoW_QuestEN[56118] = { title = "Snap Back", description = "I have a favor to ask of you, if you would be so kind.\n\nScrollsage Nola gave me this scroll to protect me on my adventures here in Nazjatar. She is a kind soul, but her scroll-work isn't always the most...accurate.\n\nYou look like a brave adventurer who's seen a thing or two. Could you test out the scroll for me? While you're there you may as well cull their numbers a tad.", objectives = "" }
WordHunterWoW_QuestEN[56126] = { title = "Seams to be a Problem", description = "<Picking away at the ore, you notice that much of it seems to turn to dust and fall to the floor at your feet. Enough even, that had it held its shape, would be enough to craft something with.\n\nIt may be worth talking to Instructor Ulooaka to see if there's a way to prevent this loss from happening.>", objectives = "" }
WordHunterWoW_QuestEN[56128] = { title = "Drowning the Horde", description = "We must strike now before the Horde have a chance to gain a secure foothold. Attack their champions and knock them on their heels.", objectives = "" }
WordHunterWoW_QuestEN[56136] = { title = "Heroic Warfront: The Battle for Stromgarde", description = "If the Horde thinks it can assault Stromgarde, it is sorely mistaken! We will not let Arathi fall!\n\nPrepare yourself for battle.", objectives = "" }
WordHunterWoW_QuestEN[56137] = { title = "Heroic Warfront: The Battle for Stromgarde", description = "Our enemies are relentless in their quest to seize Arathi for themselves. We will never allow it to fall into their hands! We must stop them before the keep is rebuilt!\n\nTake up arms. The Alliance is upon us.", objectives = "" }
WordHunterWoW_QuestEN[56138] = { title = "Holographic Entity Materalizer", description = "Alright! Let's try this puppy out. Just insert that cleaned up data disc I gave ya into my Experimental Holographic Entity Materializer over there and we'll fire 'er up!", objectives = "" }
WordHunterWoW_QuestEN[56142] = { title = "Adapt, Improve, Overcome!", description = "Izira Gearsworn is still alive, she is Rustbolt's strongest fighter, but her legs are broken. If we're going to survive I need parts to repair and upgrade her.\n\nThere are machines all over with parts we can salvage. With some perseverance we should be able to fix Izira's legs.\n\nHelp me obtain the following parts.", objectives = "" }
WordHunterWoW_QuestEN[56143] = { title = "The Fate of Professor Elryna", description = "From the looks of it, Elryna's story should have a very interesting end. This pylon here has been acting up, but I think I know why!\n\nThese things use memory cores, little crystals found within the center of the orb. I bet there's one in that old magi tower. \n\nThere's a snapdragon that's bigger than the terrormaws in there so here, keep the scroll for now. It should help in your fight. She's a big one!", objectives = "" }
WordHunterWoW_QuestEN[56144] = { title = "Old Nasha's Paw", description = "The old bear's paw is sticky with honey. She likely ransacked a number of hives before you stopped her.\n\nThe Hivemother will be interested in this item.", objectives = "" }
WordHunterWoW_QuestEN[56145] = { title = "Blueprint: Advanced Adventurer Augment", description = "<This blueprint details how to condense even more power into a ring or trinket!\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[56146] = { title = "Making Kelpberry Wine", description = "<This is an empty kelpberry juice cask.\n\nThere is someone nearby that may appreciate a refill.>", objectives = "" }
WordHunterWoW_QuestEN[56148] = { title = "Call to Arms: Nazjatar", description = "Our objectives in Nazjatar are being interrupted by the influx of Alliance scum.\n\nClear as many of them out of the area that you find, then report back.", objectives = "" }
WordHunterWoW_QuestEN[56149] = { title = "Feed Them All", description = "I am grateful for the help that your Alliance has given my people, but we are desperately short on food and supplies.\n\nIf we do not gather enough supplies to take care of both the Alliance and my clan, we will run out of food within the week.\n\nThankfully, there appears to be an abundance of fathom rays in the area, but I will need help hunting them in order to gather enough food for our camp.\n\nTake this fathom hook and use it to pull down the fathom rays from above.", objectives = "" }
WordHunterWoW_QuestEN[56150] = { title = "Kill the Kritch", description = "Mrgglrr! Mrlg rmglr grlmrrgrr, grmm mrgl grrmrrgllrr. \n\n<Rlgmrr jumps around anxiously and points toward the cave.>\n\nGrrmrlgr mrg lrglgllmrrglm mlr mrlglmrgm mrl Kriiitchrglgr.\n\n<He makes a scary face and pinching motions with his hands.>\n\nMrglrmgr lrg, mrgglmmmr! Mrlg grrrrml lrg.", objectives = "" }
WordHunterWoW_QuestEN[56151] = { title = "Poen's Favorite Dish", description = "Poen is always helping us take care of every rescue we find.\n\nCan you collect some meat from the eels south of here?\n\nI like to make his favorite dish every now and then, to repay him.\n\nIt also has a great effect on the ones recovering. \n\nThe power of deliciousness, I tell you!", objectives = "" }
WordHunterWoW_QuestEN[56152] = { title = "Turn the Scale", description = "I am in need of your help, {class}. I have been hunting the nearby hydras for their scales, but my weapon was broken in the melee.\n\nThe scales of the hydra make durable and resilient armor for our warriors. Our clan requires the scales to craft and repair our armor.\n\nIf we do not resupply soon, we will be ill-equipped in our fight against the naga.", objectives = "" }
WordHunterWoW_QuestEN[56153] = { title = "Most Delicious Clams", description = "Neptulian clams are an important part of the ankoan diet.\n\nMany forget how important proper nutrition is during a time of war. A warrior can be armed with the finest weapons and training, but if she is not healthy and well-nourished she will be ineffective in battle.\n\nNow that Mezzamere is home to your Alliance, we must work hard to gather enough food to feed our soldiers.\n\nGather as many Neptulian clams as you can find and I will see that they make it back to camp safely.", objectives = "" }
WordHunterWoW_QuestEN[56154] = { title = "Where They Hide", description = "The naga are sending assassins to eliminate our forces.\n\nThey hide nearby and murder those they cannot steal away to the slave pens.\n\nTake this special sea sponge with you. The spores will reveal the naga in all their treachery.\n\nOnce revealed, slay the assassins before they can flee for reinforcements.\n\nAzshara will fall!", objectives = "" }
WordHunterWoW_QuestEN[56155] = { title = "Plug the Geysers", description = "The geysers are dangerously unstable and will be erupting any moment now.\n\nI fear that Azshara's misuse of the Tidestone is causing irreparable damage to the elements within Nazjatar.\n\nWe have to do what we can to prevent any further destruction.\n\nTake this sealant and use it to stave off the next round of eruptions. In the meantime, I will do what I can to stabilize the elements.", objectives = "" }
WordHunterWoW_QuestEN[56156] = { title = "A Tempered Blade", description = "These blades that I wield are newly forged. The time has come to temper them in the blood of my enemies.\n\nI have heard that you are skilled in the ways of battle. I too am proficient in the business of death and I would be honored to fight at your side.\n\nAccompany me, {class}, and together we will spill the blood of our enemies.", objectives = "" }
WordHunterWoW_QuestEN[56157] = { title = "Plug the Geysers", description = "There are several geysers nearby that will be erupting soon.\n\nUnfortunately, the elements in this area are not stable enough to handle the force of the eruptions.\n\nI need someone to plug the geysers while I use the elements to redirect the pressure to a safer area of Nazjatar.\n\nTake this sealant and use it to plug the geysers while I work to restore the elemental balance.", objectives = "" }
WordHunterWoW_QuestEN[56158] = { title = "Plug the Geysers", description = "The elements are becoming increasingly unstable due to Azshara's abuse of the Tidestone.\n\nGeysers will be erupting nearby at any moment. Each eruption threatens to destroy the delicate balance of life on the surface.\n\nTake this sealant and use it to plug the geysers while I work to restore the elemental balance and redistribute the explosive underground pressure to a safer location.", objectives = "" }
WordHunterWoW_QuestEN[56159] = { title = "Plug the Geysers", description = "The geysers are dangerously unstable and will be erupting any moment now.\n\nI fear that Azshara's misuse of the Tidestone is causing irreparable damage to the elements within Nazjatar.\n\nWe have to do what we can to prevent any further destruction.\n\nTake this sealant and use it to stave off the next round of eruptions. In the meantime, I will do what I can to stabilize the elements.", objectives = "" }
WordHunterWoW_QuestEN[56160] = { title = "Plug the Geysers", description = "There are several geysers nearby that will be erupting soon.\n\nUnfortunately, the elements in this area are not stable enough to handle the force of the eruptions.\n\nI need someone to plug the geysers while I use the elements to redirect the pressure to a safer area of Nazjatar.\n\nTake this sealant and use it to plug the geysers while I work to restore the elemental balance.", objectives = "" }
WordHunterWoW_QuestEN[56161] = { title = "Back Out to Sea", description = "Now that things're under control here, I'm sure they could use your help back in Nazjatar!\n\nWhy don't ye head back out tae sea, err, or under the sea, tae lend a hand with the new folk there?", objectives = "" }
WordHunterWoW_QuestEN[56162] = { title = "Back Out to Sea", description = "Now that things're under control here, I'm sure they could use your help back in Nazjatar!\n\nWhy don't ye head back out tae sea, err, or under the sea, tae lend a hand with the new folk there?", objectives = "" }
WordHunterWoW_QuestEN[56164] = { title = "Desperate Need", description = "Our injured are in desperate need of bandages and medicines. Ask Speaker Utia for more medical supplies. \n\nUtia is our quartermaster and will certainly have the items we need.", objectives = "" }
WordHunterWoW_QuestEN[56165] = { title = "Blueprint: Extraordinary Adventurer Augment", description = "<This blueprint details how to condense an extraordinary amount of power into a ring or trinket!\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[56166] = { title = "The Needs of the People", description = "There are others in the camp that may be in need of aid. Ask around and see if there are any duties that you could take up.\n\nBe sure to report what you find to Speaker Utia.", objectives = "" }
WordHunterWoW_QuestEN[56167] = { title = "Investigating the Highlands", description = "When I first sensed these essences, I did not anticipate the importance of the role they would play. It is only a matter of time before all of the dragonflights are brought into the fold.\n\nThough I have reached out to the other Aspects, I have yet to hear from Alexstrasza. It is odd that she would be silent while these powers manifest.\n\nShe was last seen in the Vermillion Redoubt in Twilight Highlands.\n\nI fear she may be in trouble. We must hurry.", objectives = "" }
WordHunterWoW_QuestEN[56168] = { title = "Factory Refurbished", description = "I need you to get us a Recycled Crawler Manifold.\n\nYou should be able to get one up at Junkwatt Depot if you recycle parts found there.", objectives = "" }
WordHunterWoW_QuestEN[56172] = { title = "Other Interests", description = "Madam Goya is interested in many unusual items other than just rare metals.\n\nKeep your eyes out for these particular items during your travels in Nazjatar.\n\nDeliver them to me and Madam Goya will consider you for special access.", objectives = "" }
WordHunterWoW_QuestEN[56173] = { title = "Other Interests", description = "Madam Goya is interested in many unusual items other than just rare metals.\n\nKeep your eyes out for these particular items during your travels in Nazjatar. \n\nDeliver them to me and Madam Goya will consider you for special access.", objectives = "" }
WordHunterWoW_QuestEN[56174] = { title = "Other Interests", description = "Madam Goya is interested in many unusual items other than just rare metals.\n\nKeep your eyes out for these particular items during your travels in Nazjatar. \n\nDeliver them to me and Madam Goya will consider you for special access.", objectives = "" }
WordHunterWoW_QuestEN[56175] = { title = "Emission Free", description = "We're going to need a few Empty Energy Cells to fill out the battery pack on the mount control assembly. \n\nSee if you can find me these.", objectives = "" }
WordHunterWoW_QuestEN[56176] = { title = "Desperate Need", description = "Our injured are in desperate need of bandages and medicines. Ask Atolia Seapearl for more medical supplies. \n\nAtolia is our quartermaster and will certainly have the items we need.", objectives = "" }
WordHunterWoW_QuestEN[56179] = { title = "The Needs of the People", description = "There are others in the camp that may be in need of aid. Ask around and see if there are any duties that you could take up.\n\nBe sure to report what you find to Atolia.", objectives = "" }
WordHunterWoW_QuestEN[56181] = { title = "This One's on Me", description = "I'm sure you agree that Pascal-K1N6 is the greatest invention you've ever seen!\n\nIf you're not convinced yet, try to push him to his limits. I don't mind!\n\nBring him more resources and blueprints -- he'll craft anything you need!", objectives = "" }
WordHunterWoW_QuestEN[56184] = { title = "Pirates, Sea Monsters, Robots", description = "I finally found it! This is the resting place of my father, after his crew mutinied and left him here to die.\n\nI've scouted the island, and found the locations of three chests that contain mementoes of my father. \n\nDo this for me and my family. Recover my father's sword, clothing, and bones from the three chests I've marked.", objectives = "" }
WordHunterWoW_QuestEN[56185] = { title = "Whispers of N'Zoth", description = "Are you curious how I came to be here, in the Chamber of Heart? \n\nOf course I arrived of my own volition, but there was quite a search for me, for a time.\n\nKalecgos remembers how it went. Speak to him, if you wish to relive the details of how I thwarted discovery by both Speaker and Old God.", objectives = "" }
WordHunterWoW_QuestEN[56186] = { title = "Spies to the Left and Right", description = "Ebonhorn cannot resist the whispers for long. The dark forces that once corrupted the black dragonflight seek to overwhelm the world once again.\n\nWe need a way to fight back. While I am loathe to mention him, I do know of someone who has been studying the Old Gods in order to better combat their insidious power: Wrathion.\n\nThe Black Prince has associates in Pandaria, in the Tavern of the Mists at the Veiled Stair. I suggest you begin your search there.\n\nPlease hurry, {name}.", objectives = "" }
WordHunterWoW_QuestEN[56187] = { title = "Black Winged Shadow", description = "Obviously, the Black Prince isn't here. Trust me when I say he's not an easy one to find.\n\nIf I were you, I'd make my way to Blackrock Mountain. There's a terrace carved into its slopes, where Nefarian once made his lair.\n\nWrathion has been monitoring that place for a long time. Even if he's not there himself, you might find someone who knows where to look.\n\nAnd {class}... it's clear you're not the only one searching for him. Watch your back.", objectives = "" }
WordHunterWoW_QuestEN[56188] = { title = "To the Catacombs!", description = "I held out as long as I could, but... the whispers were too strong.\n\nYou must hurry to Karazhan. The Black Prince said he intended to study the artifacts stored within its catacombs.\n\nPlease, do not allow my failure to bring about his doom!", objectives = "" }
WordHunterWoW_QuestEN[56189] = { title = "On the Trail of the Black Prince", description = "<It looks like a fight took place here. N'Zoth's agents must have already entered the catacombs beneath Karazhan.\n\nThe dead lookout still has a set of keys on him. Perhaps they will unlock the door.\n\nWith any luck, you can find Wrathion before N'Zoth's agents and gain something that can help Ebonhorn.>", objectives = "" }
WordHunterWoW_QuestEN[56190] = { title = "Save Ebonhorn", description = "<The potion appears to be powerful and chaotic. It changes color seemingly at random.\n\nThis must be the concoction Wrathion wrote about in his journal. Just standing near it grants you a sense of peace and clarity.\n\nYou may not have found the Black Prince himself, but perhaps what he left behind for you can help Ebonhorn.>", objectives = "" }
WordHunterWoW_QuestEN[56205] = { title = "Just Ptrust Me On This", description = "Ahhh, it is good to see you, {name}.\n\nHow is de defective one? Still pleased to be at your side?\n\nI have given this some thought. Fear may still be what holds your not-so-little one back, but your love is what enables him to thrive without his wings. Perhaps that love will be what restores him to de skies.\n\nI am asking you to trust me. I wish to try something.\n\nIf I am correct then de two of you will find yourselves airborne as nature intended!", objectives = "" }
WordHunterWoW_QuestEN[56209] = { title = "The Halls of Origination", description = "It looks like the Halls of Origination have been claimed by a group o' tol'vir calling themselves the Amathet. I don't know much about them other than they're new in town and not the friendliest of types.\n\nWe'll need tae get in there and re-activate the forge, or else Azeroth will be done for!", objectives = "" }
WordHunterWoW_QuestEN[56210] = { title = "Scrying Stones", description = "I have a gift for you, {name}. \n\nIt's a stone unlike anything you've seen before. To the uninformed, it may seem to be a simple rock, but it's far more precious than that. \n\nThis is a scrying stone. It reveals objects that have been hidden by magic. When near an anomaly, the runes etched within will begin to glow. \n\nUse the stone to reveal treasure hidden away by ancient magic.", objectives = "" }
WordHunterWoW_QuestEN[56211] = { title = "Scrying Stones", description = "I have a gift for you, {name}. \n\nThis stone is unlike anything you may have seen before. To the uninformed, it appears to be a simple rock, but it is far more precious than that.\n\nThis is a scrying stone. It reveals objects that have been hidden by magic. When near an anomaly, the runes etched within will begin to glow. \n\nUse the stone to reveal treasure hidden away by ancient magic.", objectives = "" }
WordHunterWoW_QuestEN[56214] = { title = "Good Girl", description = "I have learned so much by your side, I can't believe how many naga we've taken down!\n\nWhen you first arrived, I was skeptical that you'd make a difference. We've been down here, fighting, for so long. I had almost lost hope.\n\nBut now, we see a way out of the darkness of the depths, finally!\n \nI took in a snapdragon pup when we formed Newhome, been training her ever since. I think... I think I'd like you to have her.\n\nShe'll make a great mount... and loyal friend.", objectives = "" }
WordHunterWoW_QuestEN[56215] = { title = "Glittering Shell", description = "Hi, friend. I just wanted you to know that traveling with you has been the best ever!\n\nI never thought I could learn so much about fighting, but now I feel like I can actually hold my own.\n\nI will protect all of the wee ones that can't protect themselves!\n\n<Poen produces a crab from somewhere, it has a bright shell.>\n\nLike this little one. I found him a while back, while we were out. He looked so scared.\n\nHey, why don't you take him?", objectives = "" }
WordHunterWoW_QuestEN[56216] = { title = "Last Heirloom", description = "We have encountered many foes together, and emerged victorious every time. I have you to thank for our safety this day, and my prowess in combat.\n\nI will be honest with you, friend. I did not think I would live this long.\n\nMy people had families, once. Traditions. We would carve symbols into our talismans and pass them down from generation to generation of deep sea hunters. Charms for luck, or prowess, each family had their own.\n\nThis is mine. I have none to pass it on to. I would like you to have it", objectives = "" }
WordHunterWoW_QuestEN[56217] = { title = "Wild Tame", description = "In our time together, I have learned much. Both about my own abilities, and about your people. \n\nYou are selfless in the face of challenge, much like our own. I consider us kin.\n\nFor some time, I have been training a snapdragon I found as a pup. He is a worthy mount, and I have been waiting for a worthy hunter to ride him. I believe I have found that hunter.\n\nHere, he is yours.", objectives = "" }
WordHunterWoW_QuestEN[56218] = { title = "Beauty in the Deeps", description = "We have slain many enemies, spilled much blood on the sand. My skills have improved tenfold fighting at your side.\n\nYet let us not forget that once, this was a place of peace. Once, my people walked amongst the caverns and reefs undisturbed.\n\nThere is beauty, here, in the depths, all around us. Take a moment, sit, and enjoy your serene surroundings. Look here, a crab with a shell of brilliant colors.\n\nYou see? There is beauty here, even now.", objectives = "" }
WordHunterWoW_QuestEN[56219] = { title = "Tome of Tears", description = "We've been fighting side by side for a while now. I didn't think an old salt like me could get any better at killing naga, but here we are.\n\nI have something to show you...\n\n<Vim produces a book from his pack.>\n\nWorst thing we can do is forget.\n\nSo many names I've written in this book, each and every one of them an Unshackled. All of them gone, now.\n\nI will never forget their names.\n\nI want you to have it. Tell people. Tell them who they were, and what we have done here.", objectives = "" }
WordHunterWoW_QuestEN[56222] = { title = "WANTED: Lady Naz'jess", description = "Wanted for attacks against the people of Nazjatar. \n\nLady Naz'jess has been driving the weapon masters to create crueler devices.\n\nLast seen skulking about Zanj'ir Terrace. She is vicious, proceed with caution.\n\nUpon completion of the mission, report to Seacaller Unow for commendation.", objectives = "" }
WordHunterWoW_QuestEN[56223] = { title = "WANTED: Commander Sarj'eth", description = "Wanted for attacks against the people of Nazjatar. \n\nCommander Sarj'eth has attempted to enslave many Horde survivors.\n\nHe commands slavers in Zanj'ir Terrace. Extreme caution advised!\n\nUpon completion of the mission, report to Seacaller Unow for commendation.", objectives = "" }
WordHunterWoW_QuestEN[56224] = { title = "WANTED: Lord Ha'kass", description = "Wanted for attacks against the people of Nazjatar. \n\nLord Ha'kass has attempted to enslave many Horde survivors.\n\nHe commands slavers in Zanj'ir Wash. Extreme caution advised!\n\nUpon completion of the mission, report to Seacaller Unow for commendation.", objectives = "" }
WordHunterWoW_QuestEN[56225] = { title = "WANTED: Lady Narjiss", description = "Wanted for attacks against the Horde!\n\nLady Narjiss is responsible for leading several raids and ambushes against our soldiers.\n\nLast seen on the outskirts of Zanj'ir Terrace. Extreme caution advised!\n\nUpon completion of the mission, report to Seacaller Unow for commendation.", objectives = "" }
WordHunterWoW_QuestEN[56226] = { title = "WANTED: Gler'thogg", description = "Gler'thogg is responsible for the death and torture of many of the Unshackled. \n\nThey have shared with us their pain. Bring back his eye.\n\nHe dwells in the Deepcoil Tunnels. Extreme caution advised!\n\nUpon completion of the mission, report to Seacaller Unow for commendation.", objectives = "" }
WordHunterWoW_QuestEN[56227] = { title = "WANTED: Inquisitor Ithriza", description = "Wanted for attacks against the Horde!\n\nInquisitor Ithriza is responsible for leading several raids and ambushes against our soldiers.\n\nLast seen in the vicinity of Dragon's Teeth Basin. Extreme caution advised!\n\nUpon completion of the mission, report to Seacaller Unow for commendation.", objectives = "" }
WordHunterWoW_QuestEN[56231] = { title = "Reinforced Cache", description = "The heavily reinforced chest is of naga construction and appears to be reinforced with a heavy-duty lock of some kind.\n\nReinforcement aside, the cache still requires a key to unlock.\n\nThe key is most likely being held by one of the nearby naga commanders.", objectives = "" }
WordHunterWoW_QuestEN[56232] = { title = "Void Cache", description = "The heavily reinforced chest is of naga construction and appears to be reinforced with a magical lock of some kind.\n\nMagical reinforcement aside, the cache still requires a key to unlock.\n\nThe key is most likely being held by one of the nearby naga commanders.", objectives = "" }
WordHunterWoW_QuestEN[56233] = { title = "Arcane Cache", description = "The heavily reinforced chest is of naga construction and appears to be reinforced with a magical lock of some kind.\n\nMagical reinforcement aside, the cache still requires a key to unlock.\n\nThe key is most likely being held by one of the nearby naga commanders.", objectives = "" }
WordHunterWoW_QuestEN[56234] = { title = "Friends In Need", description = "I doubt that will be the last we've seen of Priscilla, but at least she is no longer one of our immediate concerns.\n\nWe must think carefully before making our next move. In the meantime we should continue to build upon our relationship with our new allies, the Ankoan. Work with them to secure the area and hone their skills, we're not out of the woods yet.\n\nI fear the biggest battle is still to come. Let's show them that together we can take on Azshara's forces and succeed!", objectives = "" }
WordHunterWoW_QuestEN[56235] = { title = "Down Into Nazjatar", description = "We have much to do {name}. However our troops are weary and need rest. Decisions made when tired are often the wrong ones.\n\nThese \"Unshackled\" have offered to aid us with what forces they have. If we hope to survive down here against Azshara's forces, we will need to support our new allies.\n\nJoin one of their hunters and aid them in their tasks, we will remain here and discuss our next move.", objectives = "" }
WordHunterWoW_QuestEN[56236] = { title = "Down But Not Out", description = "Ashvane won't trouble us for now, but our situation remains perilous.\n\nI must consider our next move, {name}. In the meantime we should continue to build upon our relationship with our new allies, the Unshackled. Test them in combat, train them while you can, we will need their aid in the battles to come.\n\nWe will show them that through unity there are no obstacles that can stand in our way.", objectives = "" }
WordHunterWoW_QuestEN[56239] = { title = "Strange Silver Knife", description = "<This silver knife is small and lightly decorated, you found it inside of a chest. \n\nIt was more likely used for eating or preparing food than combat. What would the naga need with such a thing?\n\nOne of the Ankoan may know more...>", objectives = "" }
WordHunterWoW_QuestEN[56240] = { title = "Strange Silver Knife", description = "<This silver knife is small and lightly decorated, you found it inside of a chest. \n\nIt was more likely used for eating or preparing food than combat. What would the naga need with such a thing?\n\nOne of the Unshackled may know more...>", objectives = "" }
WordHunterWoW_QuestEN[56241] = { title = "Preserved Clues", description = "We have found similar chests, as you describe. We believe they were left behind by one that came before the naga.\n\nSome are even locked by odd arcane runes, the naga seem most interested in those.\n\nI know little about them, save that we find them most often in the city ruins.\n\nIf you seek to decipher their history, I would begin there.", objectives = "" }
WordHunterWoW_QuestEN[56242] = { title = "Preserved Clues", description = "If you find anything else in those chests that you don't need, you feel free to bring it on over my way.\n\nFound a few of them myself. Don't look like they belong to the naga, probably someone that lived in the city.\n\nSome are locked tight by arcane magic, seen the naga taking those back with them. Probably got the good stuff in there.\n\nI don't know much more than that. If you want a history lesson, I'd snoop around the city ruins.", objectives = "" }
WordHunterWoW_QuestEN[56243] = { title = "Diaries of the Dead", description = "<The enchantments preserving this journal are intact, but fading. It appears to be the diary of a citizen of the city. You turn to a random page...>\n\nThen he had the audacity to enter our summoning circle and demand we evict his study space at once. Who willingly steps into the chaos of a summoning ritual? He is mad. We call him that now -- Mad Mardivas.\n\nOf course, he was bitten on the leg by a lesser summon, and...\n\n<It continues -- not useful, but you surmise there may be more such tomes.>", objectives = "" }
WordHunterWoW_QuestEN[56244] = { title = "Diaries of the Dead", description = "<The enchantments preserving this journal are intact, but fading. It appears to be the diary of a citizen of the city. You turn to a random page...>\n\nThen he had the audacity to enter our summoning circle and demand we evict his study space at once. Who willingly steps into the chaos of a summoning ritual? He is mad. We call him that now -- Mad Mardivas.\n\nOf course, he was bitten on the leg by a lesser summon, and...\n\n<It continues -- not useful, but you surmise there may be more such tomes.>", objectives = "" }
WordHunterWoW_QuestEN[56245] = { title = "Enchanted Lock", description = "<The lock appears to be secured by a magical mechanism.\n\nIt is clearly one of Mardivas', and from what you can surmise from reading the journals, it is likely locked via an arcane puzzle.\n\nYou look around the room, and see something odd in the water.>", objectives = "" }
WordHunterWoW_QuestEN[56246] = { title = "Enchanted Lock", description = "<The lock appears to be secured by a magical mechanism.\n\nIt is clearly one of Mardivas', and from what you can surmise from reading the journals, it is likely locked via an arcane puzzle.\n\nYou look around the room, and see something odd in the water.>", objectives = "" }
WordHunterWoW_QuestEN[56247] = { title = "Treasure Tale", description = "<You discovered the history of Mardivas, a sorcerer that once lived in the city and the crafter of the arcane chests scattered around Nazjatar.\n\nFrom the sounds of it, he was not well-liked, which worked out for him, as he did not much like others.\n\nYou also found and unlocked one of his \"unsolvable\" arcane locks. This knowledge may prove useful on your journey.\n\nArtisan Itanu will surely enjoy hearing the end of this tale.>", objectives = "" }
WordHunterWoW_QuestEN[56248] = { title = "Treasure Tale", description = "<You discovered the history of Mardivas, a sorcerer that once lived in the city and the crafter of the arcane chests scattered around Nazjatar.\n\nFrom the sounds of it, he was not well-liked, which worked out for him, as he did not much like others.\n\nYou also found and unlocked one of his \"unsolvable\" arcane locks. This knowledge may prove useful on your journey.\n\nFinder Palta will surely enjoy hearing the end of this tale.>", objectives = "" }
WordHunterWoW_QuestEN[56249] = { title = "I Am the Trashmaster", description = "Whatcha got there, richmon? \n\nHa! You think you be de Trashmasta? You be talkin' to de God of Garbage! De Ruler of Rubbish! Master of all things Discarded an' Unwanted!\n\nSo you not be wantin' that ol' trashy cloak, eh? Jani got somethin' better. \n\nYou just give dat ol' thing to me, an Jani will be takin' care o' you...", objectives = "" }
WordHunterWoW_QuestEN[56250] = { title = "I Am the Trashmaster", description = "Whatcha got there, richmon? \n\nHa! You think you be de Trashmasta? You be talkin' to de God of Garbage! De Ruler of Rubbish! Master of all things Discarded an' Unwanted!\n\nSo you not be wantin' that ol' trashy cloak, eh? Jani got somethin' better. \n\nYou just give dat ol' thing to me, an Jani will be takin' care o' you...", objectives = "" }
WordHunterWoW_QuestEN[56256] = { title = "The Battle of Alterac", description = "The Explorers' League believes there are artifacts in Alterac Valley, but the Frostwolf orcs won't let us explore.  We can't allow the Horde to stop our scholarly pursuits!  Defeat the Frostwolf general, Drek'Thar.  With him dead, the orcs will lose their edge.\n\nDrek'Thar is in Frostwolf Keep, in the south of Alterac Valley.  Vanquish him, and then return to me.", objectives = "" }
WordHunterWoW_QuestEN[56257] = { title = "The Battle for Alterac", description = "The Stormpike dwarves and their allies have invaded Alterac Valley, and we must drive them out!  To win the battle for Alterac, we must defeat their general, Vanndar Stormpike!\n\nYou will find Vanndar in Dun Baldar, in the north of Alterac Valley.\n\nDestroy him, {name}, and then return to me.", objectives = "" }
WordHunterWoW_QuestEN[56258] = { title = "Ivus the Forest Lord", description = "The Frostwolf Clan is protected by a taint of elemental energy. Their shaman meddle in powers that will surely destroy us all if left unchecked.\n\nThe damage has grown too great for the Circle to control! Ivus must be called to our aid.\n\nThe Frostwolf soldiers carry elemental charms called storm crystals. We can use the charms to conjure Ivus. Venture forth and claim the crystals, {name}!", objectives = "" }
WordHunterWoW_QuestEN[56259] = { title = "Lokholar the Ice Lord", description = "I come from Thunder Bluff, {race}. Cairne himself has seen to it that I assist the Frostwolf Clan in these dire times.\n\nBut let us not waste any more time. You must strike down our enemies and bring to me their blood. Once enough blood has been gathered, the ritual of summoning may begin.\n\nVictory will be assured when the elemental lord is loosed upon the Stormpike army.", objectives = "" }
WordHunterWoW_QuestEN[56260] = { title = "Unlocking the Power", description = "There's somethin' special waitin' fer ye back in the Chamber of Heart, champion.\n\nI won't spoil it, but ye best get back there as quick as ye can.", objectives = "" }
WordHunterWoW_QuestEN[56261] = { title = "Return to the Heart", description = "Greetings, Champion of Azeroth.\n\nMOTHER's been monitorin' yer progress with the Heart of Azeroth, and is mighty pleased with the work you've done tae make it stronger.\n\nAt least, we think she's pleased. It's difficult tae tell at times.\n\nRegardless, come back tae the Chamber of Heart when ye've got a chance. There's more that needs doin'.", objectives = "" }
WordHunterWoW_QuestEN[56262] = { title = "Back to the Chamber", description = "The Heart o' Azeroth is gettin' stronger every day, and it's makin' a difference.\n\nMake yer way tae the Chamber o' Heart, champion. Yer talents are needed.", objectives = "" }
WordHunterWoW_QuestEN[56263] = { title = "Unlocking the Power", description = "There's somethin' special waitin' fer ye back in the Chamber of Heart, champion.\n\nI won't spoil it, but ye best get back there as quick as ye can.", objectives = "" }
WordHunterWoW_QuestEN[56264] = { title = "We've Got Crabs!", description = "{name}, you're just in time. Everything's ready for the crab hunt!\n\nOkay, okay... I know what you're thinking. A founding member of D.E.H.T.A. that condones hunting?\n\nI'm going to level with you, {name}. I've got a bar full of hungry murlocs that only eat three things: crabs, fish, and people.\n\nIf that's not reason enough, crabs are overpopulated in this region and they're decimating the local grub worm population!\n\nHow many innocent grub worms need to die before we do something, {name}?", objectives = "" }
WordHunterWoW_QuestEN[56265] = { title = "Drunk Angry Murlocs", description = "Those no-good Bloodfins ran off with all of the beer!\n\nI've been experimenting with brews that only use ingredients native to Nazjatar, but it's still a work in progress. For now, I must rely on whatever I can scrounge up from the shipwreck.\n\nMy supply of beer was already limited, but now it's all gone thanks to those thieving Bloodfin murlocs! We're going to have some very angry customers here if we don't get it back.\n\nPlease recover the stolen lager from Bloodfin Village before it's too late!", objectives = "" }
WordHunterWoW_QuestEN[56266] = { title = "Mgglurky's Mugglrgl", description = "My cook, Mgglurky, lost his mugglrgl and he's refusing to work until he gets it back.\n\nI've got a bar full of hungry murlocs and nothing to feed them until Mgglurky starts cooking. If Mgglurky doesn't find his mugglrgl soon, we're going to have a riot on our hands!\n\nI don't know about you, but I definitely don't want to be the main course tonight.\n\nThere were some Bloodfins lurking around earlier. Search Bloodfin Village for the mugglrgl and bring it back to me once you find it.", objectives = "" }
WordHunterWoW_QuestEN[56267] = { title = "Whispers of N'Zoth", description = "Are you curious how I came to be here, in the Chamber of Heart? \n\nOf course I arrived of my own volition, but there was quite a search for me, for a time.\n\nKalecgos remembers how it went. Speak to him, if you wish to relive the details of how I thwarted discovery by both Speaker and Old God.", objectives = "" }
WordHunterWoW_QuestEN[56301] = { title = "Go For The Gold", description = "I've heard lot's of stories about dead fathers, mothers, and family treasures. Don't believe any of it. We're all here to get any pirate gold, before these mecha-fools get it first! \n\nIf there's gold to be had here, it's in that fat chest the murlocs are guarding.\n\nKill their chief, empty out the chest, and we'll split it fifty-fifty, since I'm telling ya about it.", objectives = "" }
WordHunterWoW_QuestEN[56304] = { title = "The High Life", description = "You there, I require some help.\n\nEveryone where I once called home lost their lives to the flood. I still don't know what became of my father, Corin. \n\nIt pains me to return to the estates, and there are vengeful spirits who haunt the once pristine grounds. Will you help me find out what happened to my father?", objectives = "" }
WordHunterWoW_QuestEN[56305] = { title = "Let's Fish!", description = "We may need the help of some friends to land this fish!\n\nUse the Hundred-Fathom Lure when you're ready to start.", objectives = "" }
WordHunterWoW_QuestEN[56306] = { title = "The Family Jewels", description = "Darn pirates stole my jewels... err, I mean my sister's... uh, mom's jewelry. Yeah, that's the story!\n\nPoint is, they stole it, and it's all out there strewn around in the mud, and treasure chests. Maybe on a few of the robots and murlocs.\n\nMy mom's not greedy, she just wants a few of the necklaces with gold and lots of diamonds. I'd pay ya for those.", objectives = "" }
WordHunterWoW_QuestEN[56309] = { title = "City of Drowned Friends", description = "Champion, I have a personal favor to ask of you that I do not feel I can ask of any of my sentinels.\n\nThis... this is not on behalf of the Alliance, or the war, or even our battle against Azshara. This is a favor for me.\n\nWhen I was a little girl, my city was attacked by the Legion. Many of the survivors fled here only to drown or worse. I must know their fate.\n\nWill you help me search for signs?", objectives = "" }
WordHunterWoW_QuestEN[56310] = { title = "City of Drowned Friends", description = "Champion, I have a personal favor to ask of you. This is not on behalf of the Horde or the war effort.\n\nIt has been over ten thousand years since I last walked these streets. I knew many of these people, even trained some of them.\n\nWill you walk with me as I learn their fates? The road is dangerous, and I do not trust myself to maintain calm as I try to resurface old grief.", objectives = "" }
WordHunterWoW_QuestEN[56311] = { title = "The Ever Drowning", description = "Stay close, Champion. I have some magical items that might help us defend briefly against magic attacks, but Azshara was the greatest mage our kind has ever known.\n\nI do not feel confident that these trinkets will hold back her power for long, or even be usable afterward.\n\nSpeak with me when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[56312] = { title = "The Ever Drowning", description = "Queen Azshara has her eye on us now. We must proceed with caution.\n\nI do not know what she may try but stay close to me. Whatever this threat is we must pass through it if we are to find Sivara.\n\nSpeak with me when you are ready to proceed.", objectives = "" }
WordHunterWoW_QuestEN[56313] = { title = "The Warbringer", description = "We are standing in the center of some very powerful magics. An echo of something Azshara did long ago.\n\nIf you are feeling brave enough to commune with this echo, I will stand guard as you do.", objectives = "" }
WordHunterWoW_QuestEN[56314] = { title = "The Warbringer", description = "We are standing in the center of some very powerful magics. An echo of something Azshara did long ago.\n\nIf you are feeling brave enough to commune with this echo, I will stand guard as you do.", objectives = "" }
WordHunterWoW_QuestEN[56315] = { title = "They Made Their Choice", description = "It wasn't enough for Azshara to break the world. She had to doom the rest of our people here as well!\n\nThose who didn't choose to become naga were stuck in this horrifying half death, left to haunt these drowned ruins. \n\nI am almost afraid of what we will find if we do find my friend.\n\nWait, did you hear something?", objectives = "" }
WordHunterWoW_QuestEN[56316] = { title = "They Made Their Choice", description = "It wasn't enough for Azshara to break the world. She had to doom the rest of our people here as well!\n\nThose who didn't choose to become naga were stuck in this horrifying half death, left to haunt these drowned ruins. \n\nI am almost afraid to find Sivara.\n\nWait, did you hear something?", objectives = "" }
WordHunterWoW_QuestEN[56319] = { title = "The Quickcharge Contract", description = "Wondrous news, dear test subject!\n\nMy dear brother and I have restored 65% of the functionality of our research laboratory.\n\nWe are hoping to resume our regular research schedule shortly, but require a fresh batch of brave test subjects to help us push the laws of nature and science to their limits!\n\nIf you're interested, you'll just need to agree to our standard verbal contract first...", objectives = "" }
WordHunterWoW_QuestEN[56320] = { title = "Your First Charge is Free!", description = "Do you feel the energy rippling through the ground here, my dear test subject?\n\n<Flip inhales deeply.>\n\nWithout that constant bristle of electricity, nothing of any meaning would exist.\n\nMy dear sister and I have tapped into a high-voltage power line buried here, but the real juice is over in Bondo's Yard. He selfishly hoards access to the heftiest power line in Mechagon!\n\nIf you want to recharge your empty energy cells, you're going to have to get access to the Charging Station from Flux.", objectives = "" }
WordHunterWoW_QuestEN[56321] = { title = "Saving Corin", description = "My father is being tortured by that naga!\n\n{name}, I need you to help me save him. We can't let his spirit be a slave to the naga. \n\nHurry, if we don't act now he will end up like the rest of them!", objectives = "" }
WordHunterWoW_QuestEN[56325] = { title = "Changing Tides", description = "We are out of time. We must gain control the Tidestone of Golganneth and the Javelin is our best shot at piercing the barrier surrounding it.\n\nThe guardian is formidable, but must be defeated if we are to take the fight to Azshara. What forces we have will be arrayed below, just outside their encampment.\n\nI would trust you with the Javelin of Suramar, {name}. We will need your strength in the coming battle.", objectives = "" }
WordHunterWoW_QuestEN[56326] = { title = "Ravenous Rescue", description = "A conspiracy of ravens is preying on citizens of Rustbolt! It's most unacceptable! \n\nPrince Erazmin has asked me to rescue as many citizens as I can, but I could use your help. I've tracked the ravens to this hill. We blast the ravens out of the sky, and you rescue the mechagnomes.\n\nUse my marker gun if you need help bringing the ravens down.", objectives = "" }
WordHunterWoW_QuestEN[56327] = { title = "Chopped Bots", description = "Chopping up bots is my business. Any bots you bring to my scrapper will be broken up into useful parts. It's a win for both of us!\n\nUse the Bot-Energizer to bring me dead bots, and we'll break them into spare parts.", objectives = "" }
WordHunterWoW_QuestEN[56328] = { title = "Do Not Drink", description = "These troggs watch everything we do.  \n\nThey see us pouring oil into various machines, so now they're stealing the oil and drinking it. I think they believe it's going to turn them into machines!\n\nWe need that oil back, before they drink it all!", objectives = "" }
WordHunterWoW_QuestEN[56334] = { title = "Bots Gone Wild", description = "It's loose up there!\n\nI told them not to do it, but they didn't listen. Now it's gone out of control and killed everyone up there. It's an experimental Whirlbot. They never should have built it!\n\nYou need to stop it before it comes down here looking for more victims!\n\nKill the Whirling Zap-O-Matic.", objectives = "" }
WordHunterWoW_QuestEN[56336] = { title = "Uncovering the Artifact Fragments", description = "The Artifact Fragments seem to come from any creature we've found in the outskirts of Ashran. Go out and kill any you find and bring at least fifty to Ecilam the Mage near the campfire in Stormshield Stronghold.", objectives = "" }
WordHunterWoW_QuestEN[56337] = { title = "Uncovering the Artifact Fragments", description = "The Artifact Fragments seem to come from any creature we've found in the outskirts of Ashran.\n\nGo out and kill any you find and bring at least fifty Artifact Fragments to Fura the Mage in Warspear Outpost.", objectives = "" }
WordHunterWoW_QuestEN[56338] = { title = "Volrath Must Die", description = "The Horde are getting in our way of completing our mission here in Ashran. Their leader is High Warlord Volrath. He must be put down.\n\nPush forth through the center road, enter Warspear and slay Volrath.", objectives = "" }
WordHunterWoW_QuestEN[56339] = { title = "Tremblade Must Die", description = "This battle in Ashran has waged on long enough. It appears they're being led by Grand Marshal Tremblade. If she falls, the Alliance will crumble.\n\nPush forward through the center road, make your way into their keep and take down Tremblade.\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[56341] = { title = "Direbrew Cog", description = "<Direbrew's Dark Iron have fled, leaving behind a small piece of one of their mole machines.\n\nPerhaps your Dark Iron allies would be interested in hearing of your victory.>", objectives = "" }
WordHunterWoW_QuestEN[56344] = { title = "To Darkmaul Citadel", description = "We've rescued everyone except for the expedition's captain. Lindie's Scout-o-Matic spotted her just outside Darkmaul Citadel.\n\nMeredy has come up with an... interesting plan to rescue the captain. It may be our only chance.\n\nCome. We'll convene in the shadow of Darkmaul Citadel, and there we will begin our rescue mission.", objectives = "" }
WordHunterWoW_QuestEN[56346] = { title = "Ancient Technology", description = "<Given the experience you've had with the naga and the power they wield, you wonder if using their own power against them might not garner you a powerful advantage.\n\nPerhaps Instructor Ulooaka back at Mezzamere could help you repair this core and put it to use against the naga invasion.>", objectives = "" }
WordHunterWoW_QuestEN[56347] = { title = "An Abyssal Opportunity", description = "I believe, {name}, we can use this thing to make our armor stronger. By redirecting its power, we can take the strength of our crafts to a new level.\n\nBut we're getting ahead of ourselves. The first thing we need to do is repair this device.\n\nIt'll require some powerful materials to fix it, and those are usually carried by the stronger creatures of this region.\n\nHowever, Artisan Okata is great at collecting materials like the ones we need. I'd check with him to see what he's got.", objectives = "" }
WordHunterWoW_QuestEN[56348] = { title = "The Eternal Palace: We Can Make It Stronger...", description = "Now that it's functioning, it occurred to me while repairing it that it has the capability to output even more energy.\n\nOf course that will require stronger materials to upgrade and the only place I can think of is in the Eternal Palace.\n\nAzshara's army and even herself carry items of extraordinary power. If you could bring some of those back, I could at the very least test my theory and see if it's viable.", objectives = "" }
WordHunterWoW_QuestEN[56349] = { title = "The Eternal Palace: Pushing the Limits", description = "Now that we know how to increase the potency of this tool, I think we can push its capabilities even further.\n\nBring me back more of those ornaments. LOTS of them.\n\nLet's see just how far we can make this go.", objectives = "" }
WordHunterWoW_QuestEN[56350] = { title = "Scouting the Palace", description = "We cannot hide here forever, {name}. Azshara must be dealt with.\n\nIt would be an act of folly to assault her palace without knowing what defenses she has in place. I dispatched a scouting team while you were gone, but they have not reported back.\n\nI'm getting concerned, {name}. Let me know when you're ready and I'll perform a ritual to see what has happened to our scouts.", objectives = "" }
WordHunterWoW_QuestEN[56351] = { title = "The Eternal Palace: Pushing the Limits", description = "Now that we know how to increase the potency of this thing, I think we can push its capabilities even further.\n\nBring me back more of those ornaments. LOTS of them.\n\nLet's see just how far we can make this go.", objectives = "" }
WordHunterWoW_QuestEN[56352] = { title = "The Eternal Palace: We Can Make It Stronger...", description = "Now that it's functioning, it occurred to me while repairing it that it has the capability to output even more energy.\n\nOf course that'll require stronger materials to upgrade and the only place I can think of is in the Eternal Palace.\n\nAzshara's army and even herself carry items of extraordinary power. If you could bring some of those back, I could at the very least test my theory and see if it's viable.", objectives = "" }
WordHunterWoW_QuestEN[56353] = { title = "An Abyssal Opportunity", description = "I believe, {name}, we can use this thing to make our armor stronger. By redirecting its power, we can take the strength of our crafts to a new level.\n\nBut we're getting ahead of ourselves. The first thing we need to do is repair this device.\n\nIt'll require some powerful materials to fix it, and those are usually carried by the stronger creatures of this region.\n\nHowever, Finder Pruc is great at collecting materials like the ones we need. I'd check with him to see what he's got.", objectives = "" }
WordHunterWoW_QuestEN[56354] = { title = "Ancient Technology", description = "<Given the experience you've had with the naga and the power they wield, you wonder if using their own power against them might not garner you a powerful advantage.\n\nPerhaps Rolm back at Newhome could help you repair this core and put it to use against the naga invasion.>", objectives = "" }
WordHunterWoW_QuestEN[56355] = { title = "Battle Tested", description = "A weapon like this could really turn the tide against King Mechagons Troops. Let's go see how their gear matches up against our new toy.\n\nTake out King Mechagon's Sentries wherever you can find them", objectives = "" }
WordHunterWoW_QuestEN[56356] = { title = "The Eternal Palace: Queen's Gambit", description = "The way is clear. The palace awaits, {name}.\n\nWithin the Vainglorious holds court with an old god. Defeating her will be no small feat. \n\nMake no mistake, Azshara is one of the most powerful sorceresses alive. We cannot underestimate her power or her planning, for she has had thousands of years to prepare for us. Nevertheless, she must be defeated.\n\nWe are ready when you are. Shall we finally accept her invitation?", objectives = "" }
WordHunterWoW_QuestEN[56358] = { title = "The Eternal Palace: Queen's Gambit", description = "We have opened the way to the palace. We must end this.\n\nQueen Azshara is the most powerful sorceress in existence. She mastered magics thousands of years before our archmagi were even born.\n\nStill, we must prevail. If not, she and her dark patron will remake all of Azeroth to their desires.\n\nChampion, we must defeat Azshara. Are you with us?", objectives = "" }
WordHunterWoW_QuestEN[56361] = { title = "Rustbolt Requisitions: Tidespray Linen", description = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", objectives = "" }
WordHunterWoW_QuestEN[56362] = { title = "Rustbolt Requisitions: Tidespray Linen", description = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", objectives = "" }
WordHunterWoW_QuestEN[56363] = { title = "Rustbolt Requisitions: Frenzied Fangtooth", description = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", objectives = "" }
WordHunterWoW_QuestEN[56364] = { title = "Rustbolt Requisitions: Frenzied Fangtooth", description = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", objectives = "" }
WordHunterWoW_QuestEN[56365] = { title = "Be Kind, Rewind", description = "You exist here due to a time anomaly, but you must return to your own time and help us there.\n\nThe Visual Holo Sphere from the Vaultbot nearby contains the data necessary to defeat King Mechagon before he can use the Mechoriginator.\n\nDeliver the Visual Holo Sphere to me in your reality. With luck I will be able to rewind history and prevent this existence from ever happening.", objectives = "" }
WordHunterWoW_QuestEN[56370] = { title = "Break a Few Eggs", description = "The naga are using these caverns as a hatchery for their deadly deepcoil serpents.\n\nThese deepcoil serpents are especially dangerous because they have been infused with dark void magic.\n\nWe must put a stop to this operation before it is too late. The naga forces are already quite powerful. I do not wish to imagine what would happen if Azshara also had an army of these deepcoil serpents as well.\n\nOur only hope is to destroy the deepcoil eggs before they hatch.", objectives = "" }
WordHunterWoW_QuestEN[56371] = { title = "Young Twilight Scale", description = "<A partially-grown scale from a young twilight whelp.\n\nMore and more twilight dragons are appearing once again. This seems suspicious.\n\nYou should show the scale to Eryna above Grim Batol in the Wetlands, perhaps she has seen something recently.>", objectives = "" }
WordHunterWoW_QuestEN[56372] = { title = "Hozen Totem", description = "<The hozen have been successfully chased away, and Brewfest saved once again.\n\nThe question asks itself, though: How did hozen get to Dun Morogh? Perhaps you should ask somebody who has experience in navigation and travel.>", objectives = "" }
WordHunterWoW_QuestEN[56373] = { title = "A Gulper Ate the Rolly", description = "The bubble-eyed rolly used to be plentiful in the nearby pond. Last week they all started to vanish!\n\nA large water elemental has been swallowing all the fish! They are still alive, just swimming around inside the elemental now.\n\nI need you to kill that elemental, and catch three bubbly-eyed rollies so I can examine their condition.", objectives = "" }
WordHunterWoW_QuestEN[56374] = { title = "A Titanic Problem", description = "We've no time tae waste. \n\nWithout the Forge of Origination, Azeroth is left vulnerable tae N'Zoth's corruption. Not tae mention it holds a weapon capable of wipin' out all life on Azeroth!\n\nWe'll need tae head over tae the forge right away. MOTHER can hold down the fort here.\n\nHurry on, I'll meet ye there.", objectives = "" }
WordHunterWoW_QuestEN[56375] = { title = "To Ramkahen", description = "It looks like we're gonna have tae wait a spell while MOTHER figures out what tae do with the forge.  In the meantime we'll want tae try to make sure nobody tries tae do any more damage here.\n\nYe should check in on the tol'vir in Ramkahen. I know ye've helped them in the past, so they might be able tae help us keep the forge out o' the wrong hands.", objectives = "" }
WordHunterWoW_QuestEN[56376] = { title = "Surfacing Threats", description = "The tol'vir take the protection of the titans' constructs here in Uldum as a sacred duty. However, our numbers have dwindled, and we face greater threats with each day.\n\nEven with the strength of our new allies, we will only be able to hold these enemies back for so long.  Should any of them surge in power, they may still be able to overwhelm us and endanger the forge. This is where your assistance is needed.\n\nSpeak to High Commander Kamses to assess our current situation.", objectives = "" }
WordHunterWoW_QuestEN[56377] = { title = "Forging Onward", description = "Thanks fer helpin' me back there at the forge. It's vexin' that N'Zoth was able to infiltrate it so quickly, but at least we arrived in time tae keep it from bein' completely wrecked!\n\nNow comes the task of gettin' her back tae a hundred percent. MOTHER has been workin' on a solution, and we think we've got a plan.", objectives = "" }
WordHunterWoW_QuestEN[56378] = { title = "The Missing Crew", description = "I can't believe it. Almost the entire fleet.. lost! \n\nWe need to have ships out there on missions supporting our efforts, but how am I supposed to do that now?\n\nIf we are going to recover from this, I'm going to need my top people. I know the chances are low, but I need you to get out there and try to find them. Alive if possible.", objectives = "" }
WordHunterWoW_QuestEN[56379] = { title = "The Missing Crew", description = "I can't believe it. Almost the entire fleet... lost! \n\nWe need to have ships out there on missions supporting our efforts, but how am I supposed to do that now?\n\nIf we are going to recover from this, I'm going to need my top people. I know the chances are low, but I need you to get out there and try to find them. Alive if possible.", objectives = "" }
WordHunterWoW_QuestEN[56380] = { title = "Grounded", description = "One of King Mechagon's older Aerial units is having mechanical problems and is grounded nearby. \n\nThey're trying to get it repaired, so we need to act fast while it's vulnerable.\n\nDestroy the Aerial Patroller XZ-2 before they can get it repaired.", objectives = "" }
WordHunterWoW_QuestEN[56401] = { title = "A Bolt from the Blue", description = "You have done much to empower the Heart of Azeroth, and I am proud that the dragonflights have lent their strength to your cause.\n\nIt is now time for the blue dragonflight to do the same.\n\nWhen I first learned of the essences, I knew that some remnant of my dragonflight's power must be out there, coalescing where we were once strong.\n\nThat is exactly what I have found. The Kirin Tor have isolated its signature at the Nexus, but only the wielder of the Heart of Azeroth can claim it.", objectives = "" }
WordHunterWoW_QuestEN[56402] = { title = "Wastewander Coins", description = "It may be too late for some of our fallen brothers and sisters, but it is not too late to give solace to their families.\n\nEvery Wastewander carries with them a unique coin, signifying their status as a member of our group.\n\nIf you find any of these coins, please bring them to me and I will make sure they are properly returned to their next of kin.", objectives = "" }
WordHunterWoW_QuestEN[56405] = { title = "Cogfrenzy's Construction Frenzy", description = "You Rustbolt resisters inspire me. Tinkering, building, exploring.\n\nLetting your imagination run wild and then chasing after it, wherever it leads, with reckless abandon!\n\n<Walton releases a deep sigh.>\n\nI miss those days. I hope, someday, my conscience will allow me to stay on the surface with you all permanently...\n\nBefore I return to Mechagon, we must build something incredible.\n\nWaren and I have identified a large number of extra construction project sites for today. \n\nBuild with boldness!", objectives = "" }
WordHunterWoW_QuestEN[56410] = { title = "Discs of Norgannon", description = "King Mechagon unit in possession of Norgannon disk. Data is corrupted, possession of such data is dangerous.\n\nPlease aid in the recovery of Corrupted Disk Fragments that have been discarded via Mechagon waste systems. \n\nDeliver recovered Corrupted Disc Fragment to Data Analyzer R33-DR for purging.", objectives = "" }
WordHunterWoW_QuestEN[56422] = { title = "On Ghostly Wings", description = "We will meet you back where our journey began, {name}. \n\nCorin and I have been separated for many years. We have so much to catch up on. \n\nAs a token of our gratitude we will remain in the area to help you in your travels through this cursed land.", objectives = "" }
WordHunterWoW_QuestEN[56429] = { title = "Up Against It", description = "I don't like the sound of that... It sounds like an army!\n\nWe need to investigate.\n\nTry not to draw too much attention as we take a look. If there's an army down there, we'll need to move quickly to find refuge.", objectives = "" }
WordHunterWoW_QuestEN[56430] = { title = "Defensive in Death", description = "<Having handled zin'anthid for a while now, you pluck one of its tentacles from the main body. As you do, the tentacle retracts, spiraling in on itself preventing you from getting to the blooms that reside along it. Perhaps Rolm will have more insight on how to keep this herb from defending itself.>", objectives = "" }
WordHunterWoW_QuestEN[56431] = { title = "Ounces of Osmenite", description = "<Picking away at the ore, you pick up some shards that have fallen to the ground. There ought to be a way to mine these deposits without wasting any of it. Perhaps Rolm knows of still a better way to mine this ore.>", objectives = "" }
WordHunterWoW_QuestEN[56432] = { title = "Seams to be a Problem", description = "<Picking away at the ore, you notice that much of it seems to turn to dust and fall to the floor at your feet. Enough even, that had it held its shape, would be enough to craft something with.\n\nIt may be worth talking to Rolm to see if there's a way to prevent this loss from happening.>", objectives = "" }
WordHunterWoW_QuestEN[56433] = { title = "Drowning the Alliance", description = "The Alliance continue to pursue us, they will not disrupt our plans any further. Drive their champions into a watery grave.", objectives = "" }
WordHunterWoW_QuestEN[56434] = { title = "WANTED: Junkbrat and Roadtrogg", description = "Responsible for a spree of mayhem and chaos throughout the Heaps, resulting in the theft of energy cells, spare parts, and the consumption of Improbable Mechano-Chicken Wings without payment.\n\nSpecial caution around Roadtrogg, who has demonstrated a violent attitude towards living things.\n\nElimination of these two felons is of the highest priority.", objectives = "" }
WordHunterWoW_QuestEN[56436] = { title = "Small Skull", description = "<Inside of the gelatinous remains of the slime you find a small skeleton.\n\nSomeone in Rustbolt might be missing. \n\nYou pick up the skull, it might still be able to be identified.>", objectives = "" }
WordHunterWoW_QuestEN[56437] = { title = "Rusty Tube", description = "<The malfunctioning junkbot is now a mere heap of metal, its signature tube poking out of the remains.\n\nYou remove the tube. The citizens of Rustbolt seem to trade in junk, maybe someone will want it.>", objectives = "" }
WordHunterWoW_QuestEN[56438] = { title = "Flashing Siren", description = "<Despite the robot being destroyed, the siren continues flashing.\n\nClearly this was a key sentry of King Mechagon. The citizens of Rustbolt will want to know of its demise.>", objectives = "" }
WordHunterWoW_QuestEN[56439] = { title = "Mechanical Egg Sac", description = "<You find a mechanical egg sac inside of the defunct spiderbot.\n\nThis doesn't make any sense, robots don't reproduce this way.\n\nOr do they?\n\nSomeone in Rustbolt might have the answers.>", objectives = "" }
WordHunterWoW_QuestEN[56440] = { title = "Can of Critter Spray", description = "<Inside the wreckage of the robot, you find a sealed can of anti-critter spray.\n\nDestroying all life, down to the rats, seems cruel but on par for King Mechagon.\n\nSomeone in Rustbolt might be able to provide additional insight.>", objectives = "" }
WordHunterWoW_QuestEN[56441] = { title = "Cluckbox", description = "<In the sparking, smoldering wreckage of Unit 35, you find a small, black cube.\n\nIt looks to be made of a metallic substance and appears unharmed.\n\nLooking closely, you see a single word imprinted in the metal -- \"Cluckbox.\"\n\nThis particular mechanical fowl was operating quite strangely. Someone in Rustbolt will probably want to investigate.>", objectives = "" }
WordHunterWoW_QuestEN[56442] = { title = "Broken Unit 6", description = "<Unit 6 sits here, nonfunctional following your attack.\n\nThere is something different and unsettling about this mechanical frog. It appeared to be mimicking frog behavior, but in a way that seemed wrong somehow.\n\nNone of the other mechanical frogs in the area behave similarly.\n\nInstead of taking back only part of the unit for inspection, you pocket the entire frog. It's pretty small, after all.>", objectives = "" }
WordHunterWoW_QuestEN[56443] = { title = "Mechanical Eye", description = "<As the mechanical body of Unit 17 crumples into a heap, one eye lights up.\n\nYou hear a popping noise, and the eye flies from the head, aided by a small explosion.\n\nYou pick up the eye and notice it twitch a few times, then power down.\n\nThe citizens of Rustbolt seem to like junk, maybe they'll be interested in this.>", objectives = "" }
WordHunterWoW_QuestEN[56444] = { title = "Wiggletail's Poking Fork", description = "<The tenacious tine of the vanquished prince.\n\nIt does not thrum with any power whatsoever. In fact, it appears quite plain, and a bit rusted.\n\nYou pocket it anyway. Perhaps Artisan Itanu would be interested?>", objectives = "" }
WordHunterWoW_QuestEN[56445] = { title = "Wiggletail's Poking Fork", description = "<The tenacious tine of the vanquished prince.\n\nIt does not thrum with any power whatsoever. In fact, it appears quite plain, and a bit rusted.\n\nYou pocket it anyway. Perhaps Finder Palta would be interested?>", objectives = "" }
WordHunterWoW_QuestEN[56446] = { title = "Leathery Venom Gland", description = "<You pry a leathery gland from the snapdragon corpse. Drops of venom spill from an opening on one end and sizzle as they touch the ground, leaving small holes behind.\n\nThis toxin appears to be very potent. It would be best to bring it back to Mezzamere.>", objectives = "" }
WordHunterWoW_QuestEN[56447] = { title = "Half-Digested Deepcoral Pod", description = "<Upon inspection of this oddly-aggressive fathom ray, you find several halfway-digested pods.\n\nYou've seen similar pods on the coral of this region, it appears to be one of the foods of the fathom rays.\n\nThis may explain their strange ability to fly.\n\nArtisan Itanu might know more.>", objectives = "" }
WordHunterWoW_QuestEN[56448] = { title = "Molted Spineshell", description = "<The molted shell of a defeated spine crab, a vicious species of crab first encountered in Nazjatar.\n\nThe spines that stick out from it are quite sharp.\n\nArtisan Itanu may have some use for this.>", objectives = "" }
WordHunterWoW_QuestEN[56449] = { title = "Pearlescent Shell", description = "<A large, hardened shell of a vanquished hermit crab.\n\nThe shell itself was much larger than the crab, and shines in different colors when you look at it at different angles.\n\nSurely someone back at Mezzamere would be interested in this beautiful shell.>", objectives = "" }
WordHunterWoW_QuestEN[56450] = { title = "Eel Jelly", description = "<You examine the corpse of the abyssal eel, only to find it bathed in a strange slime.\n\nThe slime coats your hands and arms, and seems quite difficult to remove.\n\nOne of your deep sea allies may know more about it.>", objectives = "" }
WordHunterWoW_QuestEN[56451] = { title = "Mottled Hydra Scale", description = "<The scale of a recently-defeated hydra hatchling, it appears to be a mixture of several colors.\n\nThere appears to be a battle for dominance between the hydra of the region, one of your new allies may know more.>", objectives = "" }
WordHunterWoW_QuestEN[56452] = { title = "Strange Organ", description = "<You find a strange organ in the corpse of the mindbender. Upon picking it up, your head begins to throb.\n\nThe octopus-like creatures have long been one of Azeroth's mysteries, this organ may shed some light on them.\n\nSomeone in Mezzamere may know more.>", objectives = "" }
WordHunterWoW_QuestEN[56453] = { title = "Overgrown Stone", description = "<A stone taken from the earthy elemental you recently defeated, covered in kelp and various other underwater plants.\n\nYou have not seen many such creatures in the deeps. Perhaps there is a story to them.\n\nOne of your new undersea allies may know more.>", objectives = "" }
WordHunterWoW_QuestEN[56454] = { title = "Crackling Mandible", description = "<The mandible of a tidal guardian, still crackling with electricity.\n\nOne of your new allies might have a use for this.>", objectives = "" }
WordHunterWoW_QuestEN[56455] = { title = "Frenzy Fang", description = "<You remove a fully-grown fang from the fallen frenzy.\n\nYou have heard of some seafaring groups that made weapons or decorations out of fangs found in the deeps, perhaps your new allies could find use for this?>", objectives = "" }
WordHunterWoW_QuestEN[56456] = { title = "Opaline Conch", description = "<The conch slumps following your assault -- the battle appears to be over.\n\nIt doesn't move. You bend over and pick it up, instinctively turning it over, wary of any attack.\n\nIt appears to be dead, but intact. You consider bringing the entire conch back to your allies in Mezzamere.>", objectives = "" }
WordHunterWoW_QuestEN[56457] = { title = "Leathery Venom Gland", description = "<You pry a leathery gland from the snapdragon corpse. Drops of venom spill from an opening on one end and sizzle as they touch the ground, leaving small holes behind.\n\nThis toxin appears to be very potent. It would be best to bring it back to Newhome.>", objectives = "" }
WordHunterWoW_QuestEN[56458] = { title = "Opaline Conch", description = "<The conch slumps following your assault -- the battle appears to be over.\n\nIt doesn't move. You bend over and pick it up, instinctively turning it over, wary of any attack.\n\nIt appears to be dead, but intact. You consider bringing the entire conch back to your allies in Newhome.>", objectives = "" }
WordHunterWoW_QuestEN[56459] = { title = "Half-Digested Deepcoral Pod", description = "<Upon inspection of this oddly-aggressive fathom ray, you find several halfway-digested pods.\n\nYou've seen similar pods on the coral of this region, it appears to be one of the foods of the fathom rays.\n\nThis may explain their strange ability to fly.\n\nFinder Palta might know more.>", objectives = "" }
WordHunterWoW_QuestEN[56460] = { title = "Molted Spineshell", description = "<The molted shell of a defeated spine crab, a vicious species of crab first encountered in Nazjatar.\n\nThe spines that stick out from it are quite sharp.\n\nFinder Palta may have some use for this.>", objectives = "" }
WordHunterWoW_QuestEN[56461] = { title = "Pearlescent Shell", description = "<A large, hardened shell of a vanquished hermit crab.\n\nThe shell itself was much larger than the crab, and shines in different colors when you look at it at different angles.\n\nSurely someone back at Newhome would be interested in this beautiful shell.>", objectives = "" }
WordHunterWoW_QuestEN[56462] = { title = "Eel Jelly", description = "<You examine the corpse of the abyssal eel, only to find it bathed in a strange slime.\n\nThe slime coats your hands and arms, and seems quite difficult to remove.\n\nOne of your deep sea allies may know more about it.>", objectives = "" }
WordHunterWoW_QuestEN[56463] = { title = "Mottled Hydra Scale", description = "<The scale of a recently-defeated hydra hatchling, it appears to be a mixture of several colors.\n\nThere appears to be a battle for dominance between the hydra of the region, one of your new allies may know more.>", objectives = "" }
WordHunterWoW_QuestEN[56464] = { title = "Strange Organ", description = "<You find a strange organ in the corpse of the mindbender. Upon picking it up, your head begins to throb.\n\nThe octopus-like creatures have long been one of Azeroth's mysteries, this organ may shed some light on them.\n\nSomeone in Newhome may know more.>", objectives = "" }
WordHunterWoW_QuestEN[56465] = { title = "Overgrown Stone", description = "<A stone taken from the earthy elemental you recently defeated, covered in kelp and various other underwater plants.\n\nYou have not seen many such creatures in the deeps. Perhaps there is a story to them.\n\nOne of your new undersea allies may know more.>", objectives = "" }
WordHunterWoW_QuestEN[56466] = { title = "Crackling Mandible", description = "<The mandible of a tidal guardian, still crackling with electricity.\n\nOne of your new allies might have a use for this.>", objectives = "" }
WordHunterWoW_QuestEN[56467] = { title = "Frenzy Fang", description = "<You remove a fully-grown fang from the fallen frenzy.\n\nYou have heard of some seafaring groups that made weapons or decorations out of fangs found in the deeps, perhaps your new allies could find a use for this?>", objectives = "" }
WordHunterWoW_QuestEN[56469] = { title = "Pirates? I Hate Those Guys!", description = "<An old pirate hat. Seems out of place on this island, perhaps Reno Jackson will know what to make of it>", objectives = "" }
WordHunterWoW_QuestEN[56470] = { title = "Give A Dog A Bone", description = "Louison lent me Dog Bone to help uncover some marrowgrubs, but I'm busy here with the stoves. Could you be a dear and go hunting for me?\n\nDog Bone loves to pounce on the smaller nibblers and makes a lot of noise doing it. That'll scare the larger marrowgrubs into making a run for it. That's when you'll need to make your move.\n\nJust use this bone to lure Dog Bone near the nibblers. Oh, and don't forget to harvest the flesh from the marrowgrubs! That's what you're really after.", objectives = "" }
WordHunterWoW_QuestEN[56471] = { title = "Unprofitable Ventures", description = "This land is already a monumental disaster, but it could get worse!\n\nThe Venture Company is here, and will exploit this land for every ounce of profit they can make. We must make their venture here unprofitable, so they will leave.\n\nDestroy the three expensive security units with them, and they may leave for more profitable ventures.", objectives = "" }
WordHunterWoW_QuestEN[56472] = { title = "The Uldum Accord", description = "You seek assistance defending the Forge of Origination? It would seem that our goals align.\n\nThe Halls of Origination are but a small portion of the forge's true scope. Any threat to Uldum would be a potential threat to the forge, and Uldum has found itself with many new enemies of late.\n\nWe were about to convene the High Council when these Wastewanders arrived unannounced. Perhaps you could join us in learning about these threats?", objectives = "" }
WordHunterWoW_QuestEN[56473] = { title = "Envenomed Spider Fang", description = "Even wary bees have been known to fall prey to these enormous spiders. They lie in wait near flowerbeds and ambush them while they collect their harvest. Thanks to you, they have one less spider to worry about.\n\nThe Hivemother will be interested in this item.", objectives = "" }
WordHunterWoW_QuestEN[56474] = { title = "Hivekiller Stinger", description = "Wasps are a bee's natural enemy, and none are more deadly than this highly specialized killer. It will terrorize the hive no longer, thanks to you.\n\nThe Hivemother will be interested in this item.", objectives = "" }
WordHunterWoW_QuestEN[56475] = { title = "Spiral Yeti Horn", description = "All manner of creatures are attracted to the sweet smell of fresh honey, but relatively few are willing to withstand the painful and often deadly stings of the largest of bees. This yeti, however, has been a persistent thorn in the hive's side, until now.\n\nThe Hivemother will be interested in this item.", objectives = "" }
WordHunterWoW_QuestEN[56489] = { title = "Restless Dead", description = "Rumors are spreading of some new evil business happening in Stratholme of all places. We need you to head to Eastern Plaguelands and put an end to any new evil threats that may have taken residence there.\n\nWe have received contact from a member of the Argent Crusade who has offered their assistance to get you into Stratholme and find the source of this new evil.", objectives = "" }
WordHunterWoW_QuestEN[56490] = { title = "Restless Dead", description = "Rumors are spreading of some new evil business happening in Stratholme of all places. We need you to head to Eastern Plaguelands and put an end to any new evil threats that may have taken residence there.\n\nWe have received contact from a member of the Argent Crusade who has offered their assistance to get you into Stratholme and find the source of this new evil.", objectives = "" }
WordHunterWoW_QuestEN[56491] = { title = "Tiny Terrors of Stratholme", description = "Scourge activity inside of Stratholme has increased dramatically in the recent days. The air is thick with the stink of necromancy, and there are screams and shrieks coming from within these walls that will send chills down your spine for weeks to come.\n\nI haven't ventured in there yet myself, but there is definitely some new evil stirring from within. I have the keys to this entrance, and can bring you in there to see for yourself.\n\nLet me know when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[56492] = { title = "Pet Battle Challenge: Stratholme", description = "The evil presence has returned to Stratholme yet again. That's the problem with necromancy and scourge, they keep reanimating themselves and coming right back!\n\nI can bring us in there again, but I suspect all of those evil forces have returned. Are you sure you want to go back in there? That place gives me the creeps. If you really want to head back in there, I will let you back in.", objectives = "" }
WordHunterWoW_QuestEN[56493] = { title = "A Direct Approach", description = "Maokka has such a gentle heart. He is so good with the little ones, always playing games and telling stories.\n\nWe do however really dislike these Venture Co. individuals, so I suggest a more direct approach.\n\nTry killing them all.", objectives = "" }
WordHunterWoW_QuestEN[56494] = { title = "The Eve of Battle", description = "{name}. The time has come.\n\nWe may have defeated Azshara, but we still have to deal with Sylvanas. Though our position is not ideal, we have mobilized our available forces and stand ready to finish this war.\n\nKing Wrynn wanted me to brief you on the situation before we join him. There have been some... interesting developments.", objectives = "" }
WordHunterWoW_QuestEN[56495] = { title = "They Move Against Us", description = "The Dark Lady requests your presence in Orgrimmar, {name}. \n\nIt seems the rats have finally come out of hiding. Which will make it all the easier to exterminate them.\n\nDo not delay. We have waited for this moment long enough.", objectives = "" }
WordHunterWoW_QuestEN[56496] = { title = "The Eve of Battle", description = "{name}, we must speak of the Horde... and the warchief.\n\nThe war has proven costly, and the battle against Azshara drained what little resources we had left. The Horde is divided once more and the Alliance fares little better than we do. \n\nSylvanas is now in a position to destroy everyone she considers an enemy. That means us, as well.\n\nI had hoped that my old friend would see reason, but now...\n\nHigh Overlord Saurfang is rallying those of us who remain--including some unlikely allies.", objectives = "" }
WordHunterWoW_QuestEN[56499] = { title = "Storming the Battlefields", description = "We cannot afford to let up on any front, continue to press the war.", objectives = "" }
WordHunterWoW_QuestEN[56500] = { title = "Storming the Battlefields", description = "We cannot afford to let up on any front, continue to press the war.", objectives = "" }
WordHunterWoW_QuestEN[56501] = { title = "Taking The Air Out", description = "<This box of rockets could just be used to take out the Venture Co. Balloons. That would really motivate Venture Co. to go somewhere else.>", objectives = "" }
WordHunterWoW_QuestEN[56504] = { title = "Wrathion's Journal", description = "The whispers ceased as soon as I drank the potion. Thank you, {name}.\n\nStill, it is gravely concerning that N'Zoth's influence could reach me even within the Chamber of Heart. If Wrathion has found a way to resist the power of the Old Gods, then we can use it to reinforce the Chamber's defenses.\n\nPerhaps MOTHER can glean more information from Wrathion's journal.", objectives = "" }
WordHunterWoW_QuestEN[56508] = { title = "Waste Not", description = "<There's a variety of parts around this area that might be useful to Rustbolt. You should collect them before Venture Co takes them.>", objectives = "" }
WordHunterWoW_QuestEN[56515] = { title = "Vinyl: Gnomeregan Forever", description = "<This pressed vinyl is surprisingly still intact. Its label says it contains the recording of a song called \"Gnomeregan Forever.\"\n\nYou should be able to install this vinyl into the gramophone back in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[56516] = { title = "Vinyl: Mimiron's Brainstorm", description = "<This pressed vinyl is surprisingly still intact. Its label says it contains the recording of a song called \"Mimiron's Brainstorm.\"\n\nYou should be able to install this vinyl into the gramophone back in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[56517] = { title = "Vinyl: Battle of Gnomeregan", description = "<This pressed vinyl is surprisingly still intact. Its label says it contains the recording of a song called \"Battle of Gnomeragan.\"\n\nYou should be able to install this vinyl into the gramophone back in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[56518] = { title = "Vinyl: Depths of Ulduar", description = "<This pressed vinyl is surprisingly still intact. Its label says it contains the recording of a song called \"Depths of Ulduar.\"\n\nYou should be able to install this vinyl into the gramophone back in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[56519] = { title = "Vinyl: Triumph of Gnomeregan", description = "<This pressed vinyl is surprisingly still intact. Its label says it contains the recording of a song called \"Triumph of Gnomeregan.\"\n\nYou should be able to install this vinyl into the gramophone back in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[56523] = { title = "My Chickens are Not for Eating!", description = "If you've spent any time with that arrogant nitwit, Overspark, you know why I'm here.\n\nTo silence his boasting and finally prove that my inventions are better!\n\nI've released countless mechanical chickens across this island to analyze the technology here, adopt it, and evolve their own circuitry. One of them will become my ultimate battle chicken!\n\nBut those idiot troggs think my chickens are edible and keep bashing them.\n\nProtect them, so my techno-evolutionary experiment can run its course.", objectives = "" }
WordHunterWoW_QuestEN[56532] = { title = "Nuke 'Em Norbit", description = "These motospiders continue to multiply unchecked. If we don't slow them down they'll overrun Rustbolt soon.\n\nI've modified Norbit here with adequate firepower to take the spiders head on!\n\nWould you pilot Norbit and destroy the Reinforced Sparkweave Eggs?", objectives = "" }
WordHunterWoW_QuestEN[56533] = { title = "Worldvein Rumors", description = "Gather intelligence to assist SI:7 in identifying the location of the Fluctuating Worldvein.", objectives = "" }
WordHunterWoW_QuestEN[56534] = { title = "Worldvein Rumors", description = "Gather more intelligence to assist your followers in tracking down the location of the Fluctuating Worldvein.", objectives = "" }
WordHunterWoW_QuestEN[56536] = { title = "It's Never Easy", description = "The last I heard, Mogu'shan Vaults was still abandoned. \n\nWe shouldn't have too tough of a time reachin' the engine, since we've already defeated the mogu guardians in that place.\n\nWell, what are ye waitin' for? Let's get that engine turned on!", objectives = "" }
WordHunterWoW_QuestEN[56537] = { title = "The Mysterious Sigil", description = "<The slain mogu clutches a sigil in his hand -- a symbol of the mysterious clan he belongs to.\n\nPerhaps if you could track down his clan, they may know more about the mantid's invasion of Mogu'shan Vaults and how they can be overcome.\n\nLorewalker Cho is well known as font of lore for Pandaria. He may be able to track down the origins of the mogu's sigil.>", objectives = "" }
WordHunterWoW_QuestEN[56538] = { title = "Clans of the Mogu", description = "You say a mogu asked for your help? This is quite uncharacteristic. \n\nI'd be happy to help you uncover the origins of this sigil. To be honest, the prospect of a mogu clan that isn't openly hostile interests me greatly. Just think of the possibilities!\n\nLet's get down to business. We'll need to consult the volumes on the various mogu clans in the vale to narrow it down.", objectives = "" }
WordHunterWoW_QuestEN[56539] = { title = "Finding the Rajani", description = "Now that we have an idea of who we're looking for, the next question is, where can we find them?\n\nWith the constant infighting of the mogu, it is likely that each clan would keep tabs on the whereabouts of their competitors. If we can find such information, it may just lead us to the Rajani.\n\nSeek out the champions of the mogu. They would be the most likely to carry reports on their enemies' whereabouts.", objectives = "" }
WordHunterWoW_QuestEN[56540] = { title = "Proof of Tenacity", description = "If the Highkeeper is so convinced that we don't stand a chance against our enemies, perhaps a show of force would sway him.\n\nI am not sure how you would manage, but if you could bring proof of a victory against those who threaten the Vale, it may convince him that action should be taken.", objectives = "" }
WordHunterWoW_QuestEN[56541] = { title = "The Engine of Nalak'sha", description = "Your kind have proved me wrong in the past, so I will give you a chance to do so again.\n\nThe titan structure which houses the Engine of Nalak'sha spans the entirety of Pandaria. There are more ways to reach it than just the Mogu'shan Vaults.\n\nThere are many such routes, but the closest would be through Mogu'shan Palace. The chambers beneath the palace are interconnected with the vaults. \n\nSeek your fate there, champion.", objectives = "" }
WordHunterWoW_QuestEN[56542] = { title = "Restored Hope", description = "Your persistence fills me with hope for this world. \n\nLet us return to your \"Chamber of Heart.\" As the caretaker of the Forge of Origination, I believe I can help your efforts to restore it.\n\nSpeak to me when you are ready, and I will bring us there.", objectives = "" }
WordHunterWoW_QuestEN[56550] = { title = "Corpse Cleanup", description = "Our friends continue to fall as these terrible insects pour of their nests and attack our camps.\n\nIt's a terrible job to ask of anyone, but we have to dispose of the corpses as quickly as possible.\n\nWe can't allow our dead to be used as fertilizer for growing their disgusting eggs.", objectives = "" }
WordHunterWoW_QuestEN[56552] = { title = "Off-the-Books Brawlin'", description = "Gazlowe hired you for protection too? I guess it's true that he only hires the best, eh? Ha!\n\nPay's great, but the rules are dung: no fightin' in town, no exceptions. Bah!\n\n<Usha takes a big gulp of her drink.>\n\nThat tiny tender prince won't give us his tech unless he thinks we're good little angels... Ha!\n\nBut Gazlowe didn't say nothin' about fightin' outside of town.\n\nI got my own squad on the outskirts, ready to brawl with Grumbol's guzzlers if they show their bearded faces.\n\nYou want in?", objectives = "" }
WordHunterWoW_QuestEN[56557] = { title = "A Little Side Action", description = "There are only two things more fun than fighting, and the first is talking trash!\n\n<Usha shouts an insult at Grumbol Grimhammer.>\n\nThat boar-beard runt over there's been a thorn in my backside since Alterac... Can't seem to shake him.\n\nWe got a bet going about who's the best fighter on the island.\n\nYou want to help me win this wager?", objectives = "" }
WordHunterWoW_QuestEN[56558] = { title = "Off-the-Books Brawlin'", description = "*buuuurrp* Arrrright, listen 'ere. We got ourselves a bit o' a predicament.\n\nBesides this dump's ale tastin' like oil, that pigheaded Usha here been sayin' some unfortunate stuff about our troops.\n\nUnfortunate FOR HER, 'cuz now *uuuuurp* gonna needya ta rough up any Horde swine ya end up runnin' into out there.\n\nLoosely speakin' we ain't supposed to be brawlin' out 'ere, so this ain't a formal order or nothin'...", objectives = "" }
WordHunterWoW_QuestEN[56559] = { title = "A Little Side Action", description = "'Ey, {name}, I could be usin' yer talents fer a little bet I got goin' on with Usha.\n\nI'm wagerin' you can beat up five 'o her pals around the island before her dog can beat up five o' ours.\n\nYe up fer it me lad? 'O course ya are, ahahaha!", objectives = "" }
WordHunterWoW_QuestEN[56560] = { title = "A Curious Discovery", description = "<This crystal shines with a mesmerizing light that you find difficult to avert your gaze from.\n\nPerhaps the Unshackled would be able to tell you more about it.>", objectives = "" }
WordHunterWoW_QuestEN[56561] = { title = "A Curious Discovery", description = "<This crystal shines with a mesmerizing light that you find difficult to avert your gaze from.\n\nPerhaps the Ankoan would be able to tell you more about it.>", objectives = "" }
WordHunterWoW_QuestEN[56562] = { title = "The Problem with Shrinkage", description = "<Having skinned countless creatures, you can't help but notice how much usable leather is lost when the skin is dried and tanned. The Ankoan seem to have mastered using the material, perhaps Instructor Ulooaka could share some of his insights.>", objectives = "" }
WordHunterWoW_QuestEN[56563] = { title = "The Problem with Shrinkage", description = "<Having skinned countless creatures, you can't help but notice how much usable leather is lost when the skin is dried and tanned. The Unshackled seem to have a solid understanding of using the material, perhaps Rolm could share some of his insights.>", objectives = "" }
WordHunterWoW_QuestEN[56565] = { title = "Hanging by a Thread", description = "<As you peel the hide from the creature's body, you notice numerous scales break off the skin, tearing holes that render portions of the hide useless. The Ankoan seem to have mastered using the material, perhaps Instructor Ulooaka could share some of his insights.>", objectives = "" }
WordHunterWoW_QuestEN[56566] = { title = "Hanging by a Thread", description = "<As you peel the hide from the creature's body, you notice numerous scales break off the skin, tearing holes that render portions of the hide useless. The Unshackled seem to have mastered using the material, perhaps Rolm could share some of his insights.>", objectives = "" }
WordHunterWoW_QuestEN[56572] = { title = "Toys Like Us", description = "I must share the wonders of this place with all of Azeroth in a way that will entertain young and old alike. I will use the technology here to create a new line of toys unlike anything seen before!\n\nMy Quasi-Faceted scanner can help construct perfect replicas of things here on the island. \n\nI just need a helpful individual such as yourself to scan a few things around this area.", objectives = "" }
WordHunterWoW_QuestEN[56573] = { title = "Certified Pre-Owned", description = "First, let me say that you will ALWAYS be our favorite test subject.\n\nBut our experiments require far more sacrifice than a single test subject can offer. And, from time to time, some of those test subjects require new limbs.\n\nMy dear brother and I have a nascent concept for expanding the average lifespan of mechanical appendages. But we've run out of components to experiment on.\n\nSalvage some appendages from the heap outside town so we can continue our experiments.", objectives = "" }
WordHunterWoW_QuestEN[56574] = { title = "Reflections in Amber", description = "<A viscous dark ooze drips from this large chunk of amber. Attempting to wipe it off is futile, as the ooze is seemingly created by the amber itself.\n\nAs you hold it, unintelligible whispers fill the back of your mind.\n\nThe Shado-Pan will surely want to examine it.>", objectives = "" }
WordHunterWoW_QuestEN[56575] = { title = "Once More Into Kor'vess", description = "You found this on a member of the swarm? It seeps with corruption... and with power. We could be faced with a serious threat if the rest of the mantid's amber is similarly corrupted.\n\nFar to the west in the Dread Wastes lies Kor'vess, a large kypari tree that provides the swarm with most of its amber. From there, we can determine just how much of their stores have been infused with the energy of the Old Gods.\n\nI will meet you closer to the tree.", objectives = "" }
WordHunterWoW_QuestEN[56576] = { title = "Aqir Extermination", description = "There are too many of these things flyin' around for us to make a clean getaway. \n\nWe're liable to get swarmed the second we start up them plane engines!\n\nThese bugs are going straight back into the ground... one way or another. May as well expedite the process, know what I mean?", objectives = "" }
WordHunterWoW_QuestEN[56577] = { title = "Crippling the Hive", description = "The mantid here are working feverishly to harvest amber from the tree.\n\nPerhaps killing a pawful of them will slow their efforts.", objectives = "" }
WordHunterWoW_QuestEN[56578] = { title = "Rotten at the Roots", description = "Underneath Kypari Kor is a large chamber where the mantid tend to the tree. That must be where the source of the corruption lies.\n\nWe need to get into that chamber and stop them. N'Zoth must not be allowed to empower the swarm.", objectives = "" }
WordHunterWoW_QuestEN[56580] = { title = "Amber Secrets", description = "The Morrowchamber houses a small section of the Zara'thik, mantid under immediate directive of the new empress. Some of them may have been given pieces of amber like the one you found.\n\nThe Shado-Pan would be interested in any extra pieces we can acquire.", objectives = "" }
WordHunterWoW_QuestEN[56616] = { title = "Old Faces, New Problems", description = "One of N'Zoth's minions appears to have taken note of our presence.\n\nShall we pay them a visit?", objectives = "" }
WordHunterWoW_QuestEN[56617] = { title = "A Unified Swarm", description = "It seemed as though the mantid had been producing the corrupted amber for some time before our... intervention. It stands to reason that they are keeping a stockpile of it somewhere.\n\nThe Shado-Pan's scouts have been reporting an increased presence of the swarm's warriors in Klaxxi'vess. I would wager that they are guarding the corrupted amber.\n\nMeet me there. If we have a chance to destroy that amber, then we need to take it.", objectives = "" }
WordHunterWoW_QuestEN[56621] = { title = "Real Ultimate Power", description = "When I say that power is life, I'm not speaking figuratively, my dear test subject.\n\nProperly harnessed, power can create life itself--or at least a close enough facsimile for our purposes.\n\nThere is a massive reserve of discarded technology lurking deep in the mucky depths of the Outflow. As usual, Mechagon's trash is our treasure.\n\nI've finally perfected my device that will animate the sludge to bring that technology up to the surface for you.\n\nAll you have to do is pop 'em and grab the tech!", objectives = "" }
WordHunterWoW_QuestEN[56622] = { title = "Ashran Dominance", description = "The Alliance refuse to back down in Ashran. Teach them that the Horde will not stand aside while they plunder the power of the ancient ogre empire to use for their own schemes.", objectives = "" }
WordHunterWoW_QuestEN[56623] = { title = "Ashran Dominance", description = "As we feared the Horde are trying to consolidate their position here on the island by looting it, just like we feared. Get out there and show them the Alliance won't put up with their aggression.", objectives = "" }
WordHunterWoW_QuestEN[56640] = { title = "Fortunate Souls", description = "You and I survived the attack and have thus far evaded capture by the enemy.\n\nNot all were as fortunate.\n\nThere are many of our allies now under the control of the naga. We must free them before they are killed or suffer an even worse fate.", objectives = "" }
WordHunterWoW_QuestEN[56641] = { title = "Disruption of Power", description = "The naga are tapping into some latent power, infusing the energy into some manner of device.\n\nI do not know what purpose they have for this power, but it is surely in our interest to destroy the objects before they can be used against us.", objectives = "" }
WordHunterWoW_QuestEN[56642] = { title = "Dark Tides", description = "A tidemistress leads some nefarious ritual above a pool.\n\nDo not look in the pool when we approach it, or you will be rewarded with a view of our drowned allies.\n\nWe must put a stop to this ritual. The tidemistress is key.", objectives = "" }
WordHunterWoW_QuestEN[56643] = { title = "In Deep", description = "By now, King Greymane and Lady Proudmoore should be in the cave at which we are to meet.\n\nLet's not keep them waiting.", objectives = "" }
WordHunterWoW_QuestEN[56644] = { title = "Up Against It", description = "We must move quickly if we are to find safety for our people.\n\nThis cave is barely defensible, and much of our army is in an even more precarious position.\n\nLet's search deeper.", objectives = "" }
WordHunterWoW_QuestEN[56645] = { title = "Heart of the Swarm", description = "We need to know what we're up against. Before we return to the Serpent's Spine, we should take the opportunity to scout the swarm.\n\nI will fly us over the Heart of Fear. We should be able to survey Empress Shek'zara's forces from above. Then we can determine the extent to which N'Zoth has bolstered their ranks with his own.", objectives = "" }
WordHunterWoW_QuestEN[56647] = { title = "The Mantid Threat", description = "The mantid have been corrupting their kypari trees to imbue their amber with power from N'Zoth. The swarm is enough of a menace on its own. N'Zoth could transform them into something even more dire.\n\nThe Shado-Pan need to hear about this. I suggest you bring this information to your other allies as well.", objectives = "" }
WordHunterWoW_QuestEN[56648] = { title = "Call to Arms: Nazjatar", description = "Our mission in Nazjatar is being compromised by the Horde incursion. \n\nGet into Nazjatar and take out as many as you can.", objectives = "" }
WordHunterWoW_QuestEN[56649] = { title = "Call to Arms: Mechagon", description = "Our mission in Mechagon is being compromised by the Horde incursion. \n\nGet into Mechagon and take out as many as you can.", objectives = "" }
WordHunterWoW_QuestEN[56650] = { title = "Call to Arms: Mechagon", description = "Our objectives in Mechagon are being interrupted by the influx of Alliance scum.\n\nClear as many of them out of the area that you find, then report back.", objectives = "" }
WordHunterWoW_QuestEN[56715] = { title = "Hozen Totem", description = "<The hozen have been successfully chased away, and Brewfest saved once again.\n\nThe question asks itself, though: How did hozen get to Durotar? Perhaps somebody in the Brewfest grounds has experience with them.>", objectives = "" }
WordHunterWoW_QuestEN[56716] = { title = "Direbrew Cog", description = "<Direbrew's Dark Iron have fled, leaving behind a small piece of one of their mole machines.\n\nYou know they have attacked Brewfest before. Perhaps one of the goblins would be interested in hearing of your victory.>", objectives = "" }
WordHunterWoW_QuestEN[56719] = { title = "This Ain't Mine", description = "Your arrival is timely, {name}. Sylvanas's loyalists have collapsed part of the canyon path to Orgrimmar. \n\nWe are cut off from our vanguard and I fear that they will be destroyed if we cannot reinforce them quickly. Our forces are few in number. We cannot afford to leave them stranded for long.\n\nTinkmaster Overspark and Gazlowe believe they have a solution. Hurry and aid them however you can.", objectives = "" }
WordHunterWoW_QuestEN[56739] = { title = "The Power of Worship", description = "I was once like them, stuck in a loop and waiting for Azshara to come and save me. Our spirits are locked to this place.\n\nThere are naga in the other parts of these ruins. They have these magical orbs... I think they are using us to fuel their arcane experiments. They draw power from our spirits and our worship of Azshara. This keeps us weakened and unable to break free.\n\nDestroy the orbs. Breaking the connection will allow us to gain strength and move on.", objectives = "" }
WordHunterWoW_QuestEN[56740] = { title = "S.P.A.R.E. Crates", description = "I'm sure you agree that Pascal-K1N6 is the greatest invention you've ever seen!\n\nIf you're not convinced yet, try to push him to his limits. I don't mind!\n\nBring him more resources and blueprints -- he'll craft anything you need!", objectives = "" }
WordHunterWoW_QuestEN[56741] = { title = "The Spear of Destiny", description = "The Javelins are some of the most powerful magical creations of Suramar, before the Sundering. This is just what we need to bring down the wards on the protector and the Tidestone.\n\nWe must hurry back to Mezzamere, Lady Proudmoore needs to know of our success.\n\nThis will change the entire course of our campaign here in Nazjatar, {name}.", objectives = "" }
WordHunterWoW_QuestEN[56746] = { title = "Our Direct Line", description = "I'm sure you agree that Pascal-K1N6 is the greatest invention you've ever seen!\n\nIf you're not convinced yet, try to push him to his limits. I don't mind!\n\nBring him more resources and blueprints -- he'll craft anything you need!", objectives = "" }
WordHunterWoW_QuestEN[56747] = { title = "Rustbolt Requisitions: Akunda's Bite", description = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", objectives = "" }
WordHunterWoW_QuestEN[56748] = { title = "Brewfest Chowdown", description = "Mok-rah, {class}! I hope you came with an empty stomach!\n\nBack on Draenor, we often held eating contests at our festivals as a form of celebration. When we were put in charge of Brewfest, we could think of nothing better to add to the event!\n\nTake a seat and show us what you can eat. If you want more details before jumping in, just ask!", objectives = "" }
WordHunterWoW_QuestEN[56749] = { title = "Rustbolt Requisitions: Akunda's Bite", description = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", objectives = "" }
WordHunterWoW_QuestEN[56750] = { title = "Rustbolt Requisitions: Calcified Bone", description = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", objectives = "" }
WordHunterWoW_QuestEN[56751] = { title = "Rustbolt Requisitions: Calcified Bone", description = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", objectives = "" }
WordHunterWoW_QuestEN[56752] = { title = "Rustbolt Requisitions: Deep Sea Satin", description = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", objectives = "" }
WordHunterWoW_QuestEN[56753] = { title = "Rustbolt Requisitions: Deep Sea Satin", description = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", objectives = "" }
WordHunterWoW_QuestEN[56754] = { title = "Rustbolt Requisitions: Monelite Ore", description = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", objectives = "" }
WordHunterWoW_QuestEN[56755] = { title = "Rustbolt Requisitions: Monelite Ore", description = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", objectives = "" }
WordHunterWoW_QuestEN[56756] = { title = "My Punkin, the Action Figure", description = "Heya, {name}.\n\n<Grizzek leans in close and whispers.>\n\nI'm workin' on a surprise for Saffy. Hopin' you can help me out.\n\nI overheard her beggin' Jepetto Joybuzz to make her into one of his fancy new action figures.\n\nThat ol' jerk told her no. Can you believe it? My Punkin!\n\nWell, we don't need him. I reverse engineered a few of his toys and found out what makes them tick.\n\nI got a blueprint ready to go. We can make Saffy's action figure ourselves and surprise her with it!", objectives = "" }
WordHunterWoW_QuestEN[56757] = { title = "Rustbolt Requisitions: Winter's Kiss", description = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", objectives = "" }
WordHunterWoW_QuestEN[56758] = { title = "Rustbolt Requisitions: Winter's Kiss", description = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", objectives = "" }
WordHunterWoW_QuestEN[56759] = { title = "Rustbolt Requisitions: Tempest Hide", description = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", objectives = "" }
WordHunterWoW_QuestEN[56760] = { title = "Rustbolt Requisitions: Tempest Hide", description = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", objectives = "" }
WordHunterWoW_QuestEN[56761] = { title = "Rustbolt Requisitions: Lane Snapper", description = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", objectives = "" }
WordHunterWoW_QuestEN[56762] = { title = "Rustbolt Requisitions: Great Sea Catfish", description = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", objectives = "" }
WordHunterWoW_QuestEN[56763] = { title = "Rustbolt Requisitions: Great Sea Catfish", description = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", objectives = "" }
WordHunterWoW_QuestEN[56764] = { title = "Brewfest Chowdown", description = "Welcome, {class}! I hope you came with an empty stomach!\n\nWhat's better, or more Brewfest, than sausage and brew? The Brewfest Chowdown is our new celebration of the things that make this festival great.\n\nTake a seat and show us what you can eat. If you want more details before jumping in, just ask!", objectives = "" }
WordHunterWoW_QuestEN[56765] = { title = "Rustbolt Requisitions: Lane Snapper", description = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", objectives = "" }
WordHunterWoW_QuestEN[56771] = { title = "Time-Lost Warriors", description = "According to the scouting report ye found, the Rajani are holed up in the Silent Sanctuary, overlooking Mistfall Village. \n\nThey are described in the report as seclusive and dangerous, so we'd had best take caution when approaching them.\n\nI'll meet ye there.", objectives = "" }
WordHunterWoW_QuestEN[56775] = { title = "Warming Up", description = "Prepare yourself, {name}. We're nearing the island where the previous expedition was lost.\n\nWarm up on these combat dummies. We need everyone ready for whatever we find on that island.", objectives = "" }
WordHunterWoW_QuestEN[56777] = { title = "A Gift From The Clan", description = "Speaker Utia has requested that I direct you back to Mezzamere when you have a chance, {name}.\n\nOur clan has prepared a gift for you to show our appreciation for the courage and valor you have shown in battle against the naga.\n\nI am sure that you will find the gift of supplies to be a valuable addition to your arsenal as you continue your campaign against Azshara.", objectives = "" }
WordHunterWoW_QuestEN[56778] = { title = "A Glint in the Darkness", description = "There are many treasures hidden throughout Nazjatar.\n\nRecently, I spotted an object glinting from within a cave not far from here. It appeared to be some sort of lockbox.\n\nI suggest we head back and investigate. There may be valuable items inside that will help us in our battle against the naga.", objectives = "" }
WordHunterWoW_QuestEN[56779] = { title = "A Valorous Reward", description = "Your deeds on the battlefield have brought honor upon your Alliance, {class}.\n\nSpeaker Utia has requested your presence in Mezzamere to accept a reward on behalf of our clan.\n\nYou should return to Mezzamere at your soonest convenience.\n\nIt is an honor to fight at your side.", objectives = "" }
WordHunterWoW_QuestEN[56780] = { title = "Hidden, But Dangerous", description = "The naga have hidden many useful treasures throughout Nazjatar.\n\nI have heard tell that there is a treasure hoard not far from here. It will be dangerous, but it may be worth investigating.\n\nThere may be untold valuables inside the cache that could aid us in our fight against the naga.", objectives = "" }
WordHunterWoW_QuestEN[56781] = { title = "Treasure In The Deep", description = "There are many treasures to be found throughout the naga stronghold of Nazjatar.\n\nSome time ago, I noticed a mysterious looking chest. The area was heavily fortified with naga troops, so whatever it contains must be valuable.\n\nWe should go back and investigate the chest. Whatever is inside is better used in our hands than the hands of the enemy.", objectives = "" }
WordHunterWoW_QuestEN[56782] = { title = "The Speaker's Gift", description = "Speaker Utia has requested your presence in Mezzamere, {name}.\n\nI believe that the Speaker has prepared a collection of items to aid you in your journey.\n\nYou should return to Mezzamere at your soonest convenience and accept the Speaker's gift.", objectives = "" }
WordHunterWoW_QuestEN[56783] = { title = "The Lambent Lockbox", description = "There are many treasures to find throughout these ancient ruins.\n\nSometime ago, I noticed a strange looking chest in a cave not far from here.\n\nThere may be valuable items inside that can help us in our fight against Queen Azshara.\n\nWe should go back and investigate the chest.", objectives = "" }
WordHunterWoW_QuestEN[56784] = { title = "Helpful Provisions", description = "Speaker Utia is awaiting your return to Mezzamere.\n\nThe Speaker has bundled together some helpful provisions to aid you in your journey.\n\nPlease accept this gift with the thanks of our clan.", objectives = "" }
WordHunterWoW_QuestEN[56785] = { title = "The Mystic Chest", description = "We have uncovered many rare treasures while exploring Nazjatar. I believe that I have found yet another cache of valuable artifacts to retrieve.\n\nSome time ago, I noticed a strangely glowing object in the distance. I believe that it may have been a treasure chest.\n\nWe should go and investigate the object. If it is a treasure chest, its contents may prove valuable in our quest to defeat the naga!", objectives = "" }
WordHunterWoW_QuestEN[56786] = { title = "Naga Treasure", description = "The naga have stashed away the spoils of their wars throughout Nazjatar.\n\nEarlier while we were adventuring, I noticed a mysterious looking cache. The chest is located deep within naga territory, so I imagine that whatever is inside is most likely extremely valuable.\n\nWe should retrieve the contents of the cache. Whatever is inside is better used in our hands than the hands of the enemy.", objectives = "" }
WordHunterWoW_QuestEN[56787] = { title = "Additional Supplies", description = "Speaker Utia has asked me to send you back to Mezzamere when you have a moment, {name}.\n\nThe Speaker has some additional supplies that might aid you in your fight against the naga.\n\nPlease return to Mezzamere at your soonest convenience and accept the Speaker's gift with the thanks of our entire clan.", objectives = "" }
WordHunterWoW_QuestEN[56788] = { title = "Reclaimed Treasure", description = "The naga have filled Nazjatar with the ill-gotten spoils of war. We should reclaim whatever we come across in our effort to put an end to their tyranny once and for all.\n\nI noticed a strange looking chest in a cave nearby. It appeared to be of naga make.\n\nWe should claim the contents of the cache. There may be valuable items inside that will help us in our battle against the naga.", objectives = "" }
WordHunterWoW_QuestEN[56789] = { title = "A Gift of Supplies", description = "Speaker Utia has asked that I send you back to Mezzamere at your soonest convenience.\n\nThe Speaker has gathered together a gift of supplies to further aid you in your fight against the naga.\n\nYou should return to Mezzamere at your soonest convenience. Please accept this gift with the thanks of our clan.", objectives = "" }
WordHunterWoW_QuestEN[56790] = { title = "Treasure To Find", description = "The naga have stashed away treasures all over Nazjatar.\n\nNot long ago, I noticed an ornately crafted treasure chest hidden in plain view. The area is heavily fortified, but such minor inconveniences have not stopped us yet.\n\nWe should head back there and liberate the contents of the cache.", objectives = "" }
WordHunterWoW_QuestEN[56791] = { title = "Mysterious Treasure", description = "We have located many treasure hoards while exploring Nazjatar. I believe that I have found yet another cache for us to liberate.\n\nSome time ago, I noticed a mysterious looking chest. It is held in an extremely dangerous area, so whatever it contains must be valuable.\n\nWe should embark on a mission to liberate the contents of the cache. Whatever is inside is better used in our hands than the hands of the enemy.", objectives = "" }
WordHunterWoW_QuestEN[56803] = { title = "Just A Friend", description = "Look, mudfoot, I need to make sure a slight current isn't going to knock you over.\n\nI asked Atolia to see if she could pull together some things to make you a little less useless here.\n\nAfter what I saw in that last fight, we should probably head back sooner rather than later.", objectives = "" }
WordHunterWoW_QuestEN[56804] = { title = "With Friends Like You, Who Needs Anemones?", description = "I sometimes amuse myself with excursions into Zanj'ir Terrace, where the naga tough guys hang out.\n\nI grab things that could be useful and stash them somewhere I can pick them up later.\n\nI haven't been down there in a while. \n\nI could have something in there you may find useful.", objectives = "" }
WordHunterWoW_QuestEN[56805] = { title = "That's What Friends Are For", description = "Hmm. I am not admitting to anything, but there is a very small chance that I could have possibly, but not definitely, been mistaken about your whole... thing.\n\nOn the off chance we were still tolerating each other, Atolia mentioned she had another delivery for you.\n\nWe should swing through Newhome.", objectives = "" }
WordHunterWoW_QuestEN[56806] = { title = "Friends Through Eternity", description = "You may have noticed by now that me and the sea giants get along great.\n\nThey mostly just want to be left alone. They want to laugh, and they want to tell you stories that make no sense.\n\nA simple life.\n\nWe do share one interest, aside from killing naga, that is sampling interesting brews. \n\nMaedin recently brought in a lovely new keg, I hid it away. When it is ready to be opened, that round will be on me!\n\nCome, take a look!", objectives = "" }
WordHunterWoW_QuestEN[56807] = { title = "Real Friends Help Hide Bodies", description = "Bodies... treasures... \n\nI've seen it all, but it was a long time before I found someone worth calling friend.\n\nI am glad I added you to that list.\n\nSo, back to those friends... I have one more place I would like you to see.", objectives = "" }
WordHunterWoW_QuestEN[56808] = { title = "We're Going To Be Friends", description = "It is going to be fun getting to know you. You're not half bad!\n\nWe kinda got a little gift for you, to welcome you to the neighborhood.\n\nI hope Atolia was able to put together something neat, she didn't have much time.", objectives = "" }
WordHunterWoW_QuestEN[56809] = { title = "Super Friends", description = "You are a super trooper duper friend!\n\nThere is a place I go to visit some of my smaller buddies. I keep some neat things I find in a bag there.\n\nWould you like to see it? \n\nWhat am I asking? Of course you would, let's go!", objectives = "" }
WordHunterWoW_QuestEN[56810] = { title = "A Friend Indeed", description = "My friend, every day with you is a new adventure. \n\nI am sorry your ships crashed, but I am so happy we met!\n\nI heard a rumor, that Atolia found some more goods!\n\nWe should swing by and see what she has this time!", objectives = "" }
WordHunterWoW_QuestEN[56811] = { title = "You've Got A Friend In Me", description = "There are a few spots I enjoy checking out with my friends. \n\nI actually found this amazing... well, I don't know what it is.\n\nThink you could check it out with me?", objectives = "" }
WordHunterWoW_QuestEN[56812] = { title = "Friendship Is Magic", description = "Every day with you, I feel like I am a better kelfin than I was the day before.\n\nYou have no idea how much that means to me.\n\nI felt like I wanted to do more, be more... help more.\n\nNow, I'm starting to be a real contributing member of the Unshackled.\n\nIt's all thanks to you.", objectives = "" }
WordHunterWoW_QuestEN[56813] = { title = "An Unexpected Friend", description = "Oh, {name}, I nearly forgot!\n\nTo help you with your mission here in Nazjatar, Atolia and I put together some items you may need.\n\nWe should swing by and grab them when we have the time!", objectives = "" }
WordHunterWoW_QuestEN[56814] = { title = "Anytime You Need A Friend", description = "You're not that bad for a... what was it? {race}?\n\nI like when I am reminded to look past appearances. Ha!\n\nBut, really, speaking of hiding things in plain sight, I put some things in a naga crate. It is close to one of their camps in the Spears of Azshara, so they will never suspect it belongs to me!\n\nLet's go see if it is still there.", objectives = "" }
WordHunterWoW_QuestEN[56815] = { title = "With A Little Help From My Friends", description = "It has been so long since we have been able to trust anyone not in our little pack of survivors.\n\nI forgot how good it feels. \n\nThank you for reminding me.\n\nAtolia should have the rest of your gift together by now. We should go check in with her!", objectives = "" }
WordHunterWoW_QuestEN[56816] = { title = "A Kelfin's Best Friend", description = "There is no better weapon in our fight than knowledge. \n\nKnowing you is proof of that!\n\nI found this thing, it lets me see better than my eyes could ever do before. \n\nWith the water gone, I can see far, too! I have been using it sometimes to see what is happening in Nazjatar.\n\nLet me show you!", objectives = "" }
WordHunterWoW_QuestEN[56817] = { title = "Thank You For Being A Friend", description = "Since the waterwall appeared, so much has changed here. \n\nThere is a little spot I found, where you can feel the sea spray on your face. \n\nSometimes I just ride over there and relax.\n\nI will show it to you, if you'd like.", objectives = "" }
WordHunterWoW_QuestEN[56829] = { title = "Bottom Feeders", description = "Oh this is bad. This is really bad.\n\nEvery time one of the lads makes it down here they don't come back. Things that come down here... they sort of stay down here one way or another.\n\nLet's make a deal. You're a Maw Walker. You go find Cudgelface and the Chamberlain while I get this here carriage back in service and then we all get out of here before somethin' tries to eat us and THEN go to work on us.", objectives = "" }
WordHunterWoW_QuestEN[56833] = { title = "Leaders of the Horde", description = "Saurfang has shown his true colors and now enlists the aid of the Alliance. \n\nMeet with those who have remained loyal to the Horde. They are to ready themselves for the battle against our enemies.\n\nAnd as for Eitrigg... bring him to Nathanos. A quick death is too lenient a punishment for his treachery.\n\nGo, {name}. Let us end this.", objectives = "" }
WordHunterWoW_QuestEN[56836] = { title = "The Eternal Palace: Master's Call", description = "The palace hums with the power of Azshara's master. It calls to her, pulling her closer to his power. If we could focus this energy, it would be possible to travel directly to the Wards of the Abyss.", objectives = "" }
WordHunterWoW_QuestEN[56837] = { title = "The Eternal Palace: Master's Call", description = "The palace hums with the power of Azshara's master. It calls to her, pulling her closer to his power. If we could focus this energy, it would be possible to travel directly to the Wards of the Abyss.", objectives = "" }
WordHunterWoW_QuestEN[56838] = { title = "The Eternal Palace: Master's Call", description = "The palace hums with the power of Azshara's master. It calls to her, pulling her closer to his power. If we could focus this energy, it would be possible to travel directly to the Wards of the Abyss.", objectives = "" }
WordHunterWoW_QuestEN[56839] = { title = "Killclaw the Terrible", description = "<You see a crude sign made by the ogres. It contains a warning.>\n\nBIG bear! Bad!\n\nBig bear guard big ogre treasure!\n\nKill after ritual! Get treasure, make more power!", objectives = "" }
WordHunterWoW_QuestEN[56842] = { title = "Lunar Preservation", description = "My staff has served me well for many years. It has stood by my side, been through many trials... and as I grow older I find myself leaning on it more and more.\n\nIts flowers bloom every Lunar Festival, basking in the Elune's might. They bring me so much joy, I wish for them to stay all year long. I know a way... but my bones are too old to make the trip.\n\nPerhaps you would take the journey for me? Empower my staff in the light of the moon at the moonwells around the world. Then my flowers can stay.", objectives = "" }
WordHunterWoW_QuestEN[56889] = { title = "Wounded Wastewanderers", description = "Ahh, my friend, have you returned to render additional aid?\n\nAs you can see, we are still locked in battle with these creatures, with no end to their numbers in sight.\n\nThis is a war of attrition and we find ourselves at a clear disadvantage as injuries continue to mount.\n\nPlease, assist any of our wounded that you find within the ruins.", objectives = "" }
WordHunterWoW_QuestEN[56903] = { title = "Crown of Courage", description = "I see you are a fan of pink flowers. It is a shame those that make up your crown will one day come to perish.\n\nPerhaps I can help with that.\n\nThough those are ordinary blossoms, I know similar flowers that bloom only during Lunar Festival. If you retrieve them for me, I can imbue them with Elune's power so that you may enjoy them throughout the year.", objectives = "" }
WordHunterWoW_QuestEN[56904] = { title = "Crown of Prosperity", description = "Your crown is so colorful! Such beautiful pinks and yellows and blues... if only it could last.\n\nAlthough those particular flowers cannot, I know some that can!\n\nSimilar flowers to those bloom every Lunar Festival. They hold a special connection to Elune that I can empower, thanks to you. Retrieve them for me, and we can fashion a crown that you can enjoy year round!", objectives = "" }
WordHunterWoW_QuestEN[56905] = { title = "Crown of Dark Blossoms", description = "Such somber flowers... but they hold a beauty of their own, don't you think? If only they could last.\n\nAllow me to lend my aid.\n\nEvery Lunar Festival, similar flowers to yours bloom around the world. They hold a special connection to Elune... one that I can empower. If you bring them to me, I can preserve them so you may enjoy them long after an ordinary flower would die.", objectives = "" }
WordHunterWoW_QuestEN[56906] = { title = "Crown of Good Fortune", description = "Those flowers remind me of Elune herself! I wear similar ones year round, to remind me of her watchful grace.\n\nPerhaps you would like to as well?\n\nYour crown is made of ordinary blossoms that will one day wilt and die. It is an unfortunate fate for such delicate beauties, but my crown is made of similar flowers that I made to last year round! If you bring me specific flowers that bloom only during Lunar Festival, I can bless them so that you too can enjoy your crown all year long.", objectives = "" }
WordHunterWoW_QuestEN[56907] = { title = "Paint Bottle: Nukular Red", description = "<Kram Kelada could make use of this item.>", objectives = "" }
WordHunterWoW_QuestEN[56908] = { title = "Paint Bottle: Goblin Green", description = "<Kram Kelada could make use of this item.>", objectives = "" }
WordHunterWoW_QuestEN[56909] = { title = "Paint Bottle: Electric Blue", description = "<Kram Kelada could make use of this item.>", objectives = "" }
WordHunterWoW_QuestEN[56942] = { title = "On The Road Again", description = "Right lads! All aboard!", objectives = "" }
WordHunterWoW_QuestEN[56955] = { title = "Rebels on the Road", description = "This is unacceptable. The stoneborn rebels have ambushed a convoy intended for the Tithelord. He is the local Harvester who rules this ward. \n\nWe need to get through this mess. The bridge on the far side of this conflict leads to Darkhaven. The Master typically keeps some of his own Stone Legion forces there. \n\nCarve us a way through, Maw Walker. Destroy any who would delay us. We must not keep Sire Denathrius waiting.", objectives = "" }
WordHunterWoW_QuestEN[56978] = { title = "To Darkhaven", description = "Across this bridge is the hamlet of Darkhaven. It is fortified by those loyal to Sire Denathrius. These pitiful rebels would not dare approach it.\n\nHowever, getting to it may prove challenging. Here, I shall carry the anima, you make sure no one throws us back into the Endmire.", objectives = "" }
WordHunterWoW_QuestEN[56979] = { title = "Saving the Siege", description = "In the chaos of the rockslides, Sylvanas dispatched her saboteurs to sneak past our sentries and plant bombs on our siege weaponry. \n\nSeveral of them have already been lost. We cannot afford to lose more.", objectives = "" }
WordHunterWoW_QuestEN[56980] = { title = "Already Among Us", description = "While some of the Horde have joined forces with us, many within Orgrimmar remain loyal to Sylvanas. Her saboteurs have infiltrated our ranks and are posing as our technicians. Her assassins are lurking in the shadows.\n\nStop any loyalists you encounter, before they can cause any harm.", objectives = "" }
WordHunterWoW_QuestEN[56981] = { title = "Strategic Deployment", description = "Saurfang maintains that the key to taking Orgrimmar is to exploit its multiple points of entry. He led the city's defenses for years, and knows its vulnerabilities better than anyone. We are spread thin as it is, but I trust his judgment in this matter.\n\nWe must also fortify Thunder Bluff in case Sylvanas plans to assault it while our forces are committed here.\n\nDeliver these deployment orders to our officers. We will assail all of Orgrimmar's gates at once while also defending Thunder Bluff.", objectives = "" }
WordHunterWoW_QuestEN[56982] = { title = "Before the Gates of Orgrimmar", description = "We have prepared for this battle as best we can, {name}.\n\nI pray that we all survive what is to come.", objectives = "" }
WordHunterWoW_QuestEN[56993] = { title = "The Price of Victory", description = "Saurfang... how could this have happened....\n\n<Jaina takes a moment to compose herself.>\n\nThe Alliance has known High Overlord Saurfang as both a sworn enemy and an invaluable ally.\n\nAnduin will want to honor his memory. Recall our forces and inform them of what has happened. Genn's soldiers were dispatched to the western gate. You should be able to find him there.", objectives = "" }
WordHunterWoW_QuestEN[57002] = { title = "Old Soldier", description = "No matter what doubts he harbored, Saurfang was an honorable soldier. \n\nHe prevented both a civil war within the Horde and the potential destruction of the Alliance. He brought an end to Sylvanas's reign and saved many lives at the cost of his own. \n\nWe shall honor his sacrifice.", objectives = "" }
WordHunterWoW_QuestEN[57003] = { title = "Create Your Own Strength", description = "For something that has been sitting on the ocean floor, there is still power to be found in this item.\n\nTake your piece of Benthic armor to Voidbinder Zorlan. He has been eyeing it with great curiosity.\n\nGo ahead and humor the ethereal and let him have a look.\n\nMaybe he has something to offer.", objectives = "" }
WordHunterWoW_QuestEN[57004] = { title = "Create Your Own Strength", description = "That Benthic armor you carry has been lost beneath the tides for too long.\n\nThere is still power within it.\n\nVoidbinder Sturzah may be able to provide insight.\n\nTake your find to our intrepid ethereal friend, and see what he can do with it.", objectives = "" }
WordHunterWoW_QuestEN[57005] = { title = "Becoming a Friend", description = "Some of our bravest kelfin have volunteered to join you on your adventures, should you ever need a friend.\n\nYou will find they each have their own special interests and they will mark your map with different opportunities every day.\n\nUse the conch when you're ready, choose who you would like to join you, and explore Nazjatar!\n\nChoose wisely! You may only select one friend per day.", objectives = "" }
WordHunterWoW_QuestEN[57006] = { title = "A Worthy Ally", description = "Some of our bravest ankoan have volunteered to join you on your expedition.\n\nYou will find each have their own special interests and they will mark your map with different opportunities every day.\n\nUse the Deepflame Campfire when you are ready. Choose a noble ally to join you, and explore what remains of Nazjatar.\n\nChoose wisely! You may only select one friend per day.", objectives = "" }
WordHunterWoW_QuestEN[57007] = { title = "Invitation of the Master", description = "The great Sire Denathrius, Master of Revendreth, and King of the venthyr, has asked me, his loyal Chamberlain, to escort you safely to his personal gardens. This is an honor never before bestowed upon a living mortal. \n\nYou should feel honored.\n\nCome, join me in the carriage and we shall ride to the castle in style.", objectives = "" }
WordHunterWoW_QuestEN[57009] = { title = "Fame Waits for Gnome One", description = "Tinkmaster Overspark requests your assistance on an important research expedition. \n\nWorking with the esteemed Tinkmaster will certainly be of benefit to your career. It's done wonders for mine!", objectives = "" }
WordHunterWoW_QuestEN[57010] = { title = "Harnessing the Power", description = "Heart Forge online.\n\nInitiate final attunement sequence.\n\nAwaiting input from champion unit {name}.", objectives = "" }
WordHunterWoW_QuestEN[57022] = { title = "Assault: Amathet Advance", description = "", objectives = "" }
WordHunterWoW_QuestEN[57024] = { title = "Rumors of Mechagon", description = "I knew I should've taken that gig with the Greasemonkeys...\n\nGazlowe's crew always get paid, and no dumb risks. I heard they got somethin' big comin' up too...", objectives = "" }
WordHunterWoW_QuestEN[57025] = { title = "A Plea to Revendreth", description = "Revendreth is quite possibly the most... efficient... realm at extracting anima. Perhaps they can lend aid where others cannot. \n\nKnow that while souls sometimes return from Revendreth, they are never the same when they do. It is a dark realm, where those the Arbiter deems worthy of a chance of redemption are sent.\n\nTheir path, however, is not an easy one.\n\nKah-Sher will assist you in opening the gateway to Revendreth. Meet him in the Ring of Transference.", objectives = "" }
WordHunterWoW_QuestEN[57026] = { title = "The Sinstone", description = "Well, you ain't like the others. Usually you're supposed to be dead before you come here. Ah well. A sin is a sin and a stone is a stone, as it goes.\n\nLet's get you sorted out with your sinstone. This way, if you please.", objectives = "" }
WordHunterWoW_QuestEN[57037] = { title = "A Once Sweet Sound", description = "The bells! That sound!\n\nTheir song has been twisted! If their dire toll continues, we will all succumb.\n\n<Eridia presses her hammer into your hands.>\n\nFind the great vespers within the temple and strike them with my hammer. May the mallet's tonal purity restore their true voices!\n\nI will listen for their clarion call and meet you near the bridge. Go swiftly!", objectives = "" }
WordHunterWoW_QuestEN[57043] = { title = "Old Friends, New Opportunities", description = "Greetings, {name}. I have a... strange message for you from a group of goblins.\n\nSomeone named Sassy Hardwrench is asking for your help for what was described as a, \"big job\". \n\nThe word \"big\" was mentioned several times, followed by murmuring about time and money. \n\nSassy is waiting for you over in Stranglethorn Vale.", objectives = "" }
WordHunterWoW_QuestEN[57045] = { title = "A Special Delivery", description = "I'm glad you're finally here, {name}. I've got an important delivery to make and you're the goblin I trust most.\n\nYeah, yeah. I know that's not sayin' much, but it's hard to find good help these days!\n\nThis package is for Hobart Grapplehammer. He's got a workshop in Crapopolis and I need you to deliver it to him. He's been working on somethin' big lately!\n\nDeliver the package and for the love of money... DON'T DROP IT!\n\nYou have no idea how long it took me to locate this thing!", objectives = "" }
WordHunterWoW_QuestEN[57047] = { title = "A Simple Experiment", description = "Now that you've delivered the necessary parts, I can begin testing my latest prototype!\n\nI call it the X-52 Personnel Armor! It will be nearly indestructible!\n\nGallywix has always coveted my inventions and now that he knows about the X-52 I'm sure he'll be up to no good. I've gotta complete the prototype before Gallywix comes up with a way to steal it out from under me!\n\nI could really use an extra set of hands with the experiments.\n\nCan I count on you, {name}?", objectives = "" }
WordHunterWoW_QuestEN[57048] = { title = "Shopping For Parts", description = "I'm going to need some additional components in order to complete the next phase of testing.\n\nRight now, what we need most are thermoplugs and thermoplug adaptors! I'll explain what they're for later...\n\nCrank Greasefuse runs a shop near the entrance of the town. Go speak with Crank and get him to fork over the necessary parts.\n\nI don't care what they cost, just tell him to bill me later! I can't be bothered to negotiate right now. I need to prepare the modifications to the X-52 Personnel Armor!", objectives = "" }
WordHunterWoW_QuestEN[57051] = { title = "Debt Collection!", description = "You need thermoplugs? Well, you came to the right place, kid.\n\nBut I ain't giving 'em to you on credit. There's way too many shlubs who haven't paid me back the money they owe. I'm in over my head here, if I don't get paid fast, I'll be out of business in no time.\n\n<Crank Greasefuse thinks for a moment.>\n\nLook, I tell you what... If you can muscle those no-good goons into paying me my money, I'll give you the thermoplugs as payment.\n\nYou won't find a better deal than that!", objectives = "" }
WordHunterWoW_QuestEN[57052] = { title = "I've Got What You Need", description = "A deal's a deal, {name}. Here's the thermoplugs you ordered!\n\nBe sure to let that ol' grouch Grapplehammer know that I won't be giving out anymore handouts. If he needs more thermoplugs he'd better be ready to pay up.\n\nAnyway, it was a pleasure doing business with you...\n\nNow get lost!", objectives = "" }
WordHunterWoW_QuestEN[57053] = { title = "Blunt Force Testing", description = "Now that we have the thermoplugs we're ready for our next test of the prototype X-52 Personnel Armor!\n\nUnfortunately, my lab assistants have either quit or expired. What a pity! But their loss is your gain, {name}... now YOU get to wear the X-52 Personnel Armor!\n\nHow exciting!\n\nThe next test will be conducted by my new mechanized lab assistant. Head over to the main workshop and press the big red button to begin.\n\nDon't worry, I'll be giving you directions over the X-52's built in intercom!", objectives = "" }
WordHunterWoW_QuestEN[57058] = { title = "Fun With Landmines", description = "The prototype X-52 Personnel Armor is ready for the final test! \n\nHow are you with loud noises and sudden bursts of concussive energy, {name}?\n\nFor the final test, we're going to strap you into the X-52 Personnel Armor and have you traverse a minefield!\n\nI have placed a refreshing coconut beverage in the center of the minefield. Consider the drink a fitting reward for reaching the oasis and surviving the inevitable explosions in the process!", objectives = "" }
WordHunterWoW_QuestEN[57059] = { title = "Let's Rumble!", description = "This is bad, {name}! Real bad!\n\nGallywix and his goons are destroying my workshop, but he's got another thing coming if he thinks I'm gonna hand over the X-52 Personnel Armor!\n\nYou've gotta get down there and clear out his goon squad before this place--AND ALL MY INVENTIONS--go up in flames!", objectives = "" }
WordHunterWoW_QuestEN[57067] = { title = "Mogu at the Gates", description = "The time has come. The other mogu clans have set their sights on the Vale of Eternal Blossoms.\n\nThey will not conquer it.\n\nSome of your kind have already gone to the gate to scout out the size of their force. If you think yourself worthy for such a mission, meet them there.", objectives = "" }
WordHunterWoW_QuestEN[57068] = { title = "Kite Surveillance", description = "We heard for ourselves that there were mogu attacking, but I had no idea it would be this many!\n\nThere must be a way to stop them before they completely overrun the Vale. Quickly, let us fly over and scout out their numbers.\n\nWe just so happen to have a kite that can carry three people. Usually it's more, but I had a big lunch.", objectives = "" }
WordHunterWoW_QuestEN[57069] = { title = "Cut Off the Heads", description = "Okay. We're stuck in the middle of three mogu armies, and Uncle Chen is too hurt to move yet.\n\nIt's not hopeless though. We have the chance to take out the leaders of these armies. Maybe that will slow them down or distract them long enough for us to get back to the gate!\n\nSee if you can get out there and take down the biggest, baddest mogu you can find. Those will be the commanders.", objectives = "" }
WordHunterWoW_QuestEN[57070] = { title = "Mogu Massacre", description = "I think this is what my friends would call a \"target rich environment.\" As a nicer way of saying \"we're surrounded and probably doomed.\"\n\nYou know what this means. We have to kill as many of these mogu as possible! It doesn't matter how you do it, just take them out!", objectives = "" }
WordHunterWoW_QuestEN[57071] = { title = "No Brew Left Behind", description = "My head is... hurting. There can be only one solution.\n\nWe flew over an abandoned brew caravan. You must go find it, and save that brew! That should help bring me back to full strength.\n\nPlus, it would do wonders for the morale of those fighting in the Vale, if we can recover it.", objectives = "" }
WordHunterWoW_QuestEN[57072] = { title = "Yak of All Trades", description = "<The brew barrels are too heavy and numerous to carry alone.\n\nPerhaps you can find something, or someone, to help you.>", objectives = "" }
WordHunterWoW_QuestEN[57074] = { title = "Our Backs to the Gate", description = "It is most fortuitous that you found this brew, and a yak to carry it on!\n\nBut we cannot remain here. Li Li has healed me up enough to travel. We can ride the yak back to the gate and hope that the mogu do not notice our passing.\n\nLet me know when you are ready to leave.", objectives = "" }
WordHunterWoW_QuestEN[57075] = { title = "Liquid Courage", description = "We have to do something about all these mogu. At least to thin their ranks before they invade the Vale!\n\nAs much as Uncle Chen loves his brew, I think we can put it to better use. Let's hop onto that yak and give the mogu something to fear!", objectives = "" }
WordHunterWoW_QuestEN[57076] = { title = "Return to Mistfall", description = "We have done all we can here. We know how much the mogu are a clear threat.\n\nThe forge is in great danger of falling into their hands if we lose our hold on the Vale.\n\nLet us return to Mistfall and report to the Rajani. They will want to know what we are up against.", objectives = "" }
WordHunterWoW_QuestEN[57077] = { title = "Buyers Wanted!", description = "The X-52 Personnel Armor is finally complete and Gallywix has been sent packing with his tail between his legs!\n\nI've got you to thank for this, {name}!\n\nBut we're still not done... the best part is yet to come. We're going to hold an auction and sell the X-52 Personnel Armor to the highest bidder!\n\nSassy Hardwrench should have a list of interested buyers ready to go. Head over to Hardwrench Hideaway and let her know we're ready for the auction!", objectives = "" }
WordHunterWoW_QuestEN[57078] = { title = "The VIP List", description = "While you've been assisting Grapplehammer with his newest invention, I've been hard at work finding potential buyers!\n\nThis is going to be a private auction, so we're only inviting the best and the brightest, the cream of the crop, the creme de la creme... got it?\n\nI've narrowed the potential buyers down to an 'A' list of only the wealthiest, classiest, most connected goblins around... minus Gallywix, of course!\n\nHead out and deliver these invitations while I finish up preparations for the auction!", objectives = "" }
WordHunterWoW_QuestEN[57079] = { title = "Beat The Crapopolis Outta Him!", description = "Boy am I glad to see you! We've got a bad situation on our hands...\n\nWhile you were away delivering the invitations, Gallywix and his goons took over Crapopolis! They're holding Hobart Grapplehammer hostage until he hands over the X-52 Personnel Armor!\n\nYou have to stop Gallywix before it's too late!", objectives = "" }
WordHunterWoW_QuestEN[57080] = { title = "A Fitting Reward", description = "Although the X-52 Personnel Armor's power-core was destroyed during the battle with Gallywix, the invention was a success!\n\nI doubt anyone will be interested in purchasing the rights to the X-52 without a working power-core, so why don't you hang onto the armor instead? It is quite stylish after all!\n\nNow that Crapopolis is saved and Gallywix is conveniently trapped inside of his own mechanical pummeler, I think I'm going to renegotiate that \"contract\" of his.\n\nHe is a \"captive audience\" after all!", objectives = "" }
WordHunterWoW_QuestEN[57086] = { title = "Legacy of the Mad Mage", description = "<This rather large jewel has an inscription etched on its base:\n\nProperty of Mardivas. If found please return to my laboratory. \n\nPerhaps this laboratory can still be found somewhere?>", objectives = "" }
WordHunterWoW_QuestEN[57088] = { title = "This Ain't Mine", description = "Sylvanas's loyalists have collapsed part of the canyon path to Orgrimmar. Our forces are now cut off from each other.\n\nWe need to reinforce our front line or the Banshee will pick us off at her leisure. We have come too far to be slain by a thousand cuts.\n\nGazlowe and one of the Alliance's gnomes believe they have an answer. You'd best ensure that their plan does not backfire.", objectives = "" }
WordHunterWoW_QuestEN[57090] = { title = "Saving the Siege", description = "The Banshee's spies were able to sneak past our guards in the chaos of the rockslides. They've been planting bombs on our siege weaponry.\n\nGet rid of those bombs.", objectives = "" }
WordHunterWoW_QuestEN[57091] = { title = "Already Among Us", description = "Sylvanas still commands the loyalty of many within the Horde. The war she started has blinded them with rage and hatred. She exploits that to maintain her support.\n\n<Saurfang scowls.>\n\nThey do not yet see she will lead us to ruin, that her so-called victories are all hollow.\n\nSome of her agents have been spotted lurking within our ranks. Kill them. They will show us no mercy, and will have none in return.", objectives = "" }
WordHunterWoW_QuestEN[57092] = { title = "Strategic Deployment", description = "For years, I guarded the gates of Orgrimmar. The city's greatest weakness has always been its multiple entrances. We should strike at all of them to seize victory.\n\nWrynn and I have drawn up orders for deployment. The mages will cover our flank. Greymane will close in from the west, and the elves will take the north. We will send Mayla to reinforce Thunder Bluff's defenses in case Sylvanas launches a counterattack.\n\nBring the orders to our commanders.", objectives = "" }
WordHunterWoW_QuestEN[57093] = { title = "Before the Gates of Orgrimmar", description = "It is time.\n\nWe have done all that we can to prepare. All that remains is the battle itself.\n\nI am not one for speeches. So I will say only this.\n\nLok-tar ogar, {name}. Victory. Or death.", objectives = "" }
WordHunterWoW_QuestEN[57094] = { title = "The Price of Victory", description = "Saurfang... I...\n\n<Lor'themar takes a moment to compose himself.>\n\n...Thrall will wish to honor Saurfang's sacrifice. And so shall the rest of us.\n\nRecall our forces. Let them know what has transpired. Tell them that the great warrior Varok Saurfang is dead and that the warchief has abandoned us.\n\nSpeak to Baine when you arrive in Thunder Bluff. You will find him on the Elder Rise. I am certain he will want to pay his respects to Saurfang as well. \n\nLet us stand as a united Horde once more.", objectives = "" }
WordHunterWoW_QuestEN[57095] = { title = "Old Soldier", description = "No matter what anyone says, he was an honorable orc. A legend in his own right, the ideal to which all warriors of the Horde aspired. \n\nHe gave his life to heal the rift in the Horde and give us the chance to forge a new path forward. His was more than a death befitting a warrior. It was the death of a hero.\n\nWe shall honor his sacrifice.", objectives = "" }
WordHunterWoW_QuestEN[57098] = { title = "The Grove of Terror", description = "Ah, yes. You've done me a great favor in delivering the Accuser, Maw Walker. \n\nTo celebrate, I must insist that you take part in a sacred tradition of Revendreth: The Penitent Hunt. It is a duty we undertake to strike a humbling fear into the hearts of the most... stubborn souls.\n\nFear can be a very powerful motivator for change.\n\nMeet the Fearstalker in the Grove of Terror below. There you will prepare.", objectives = "" }
WordHunterWoW_QuestEN[57099] = { title = "A Dreadful Roundup", description = "Welcome to The Banewood, Maw Walker.\n\nAs Huntmaster it is my duty to lead the Fearstalk. Our first order of business is to collect the souls selected for the hunt.\n\nIn the woods behind me we have souls who have been ripening for several hundred years now. Go choose the souls who will be hunted today.", objectives = "" }
WordHunterWoW_QuestEN[57100] = { title = "Feeding Time is Over", description = "A crucial element to a successful Fearstalk is our tool: the fangs of a terrorbeast.\n\nTheir fangs are perfect for revealing the scent of their prey once bound to a soul. There's plenty of them in the forest surrounding the ripening souls. \n\nGo and collect some from their corpses. Their population is a bit large right now anyhow.", objectives = "" }
WordHunterWoW_QuestEN[57102] = { title = "Pardon Our Dust", description = "Ah yes, the Greeter.\n\nIt seems this Mnemis unit has been deactivated. Anima has been so scarce of late, and with no new souls entering our gates... I suppose it was a prudent measure. Anima is our most precious resource, after all.\n\nThere are some centurions nearby. A portion of their anima could serve our needs.\n\nAh! One of our most helpful stewards is here to lend her aid. She will guide you in the collection effort.\n\nReturn when you have sufficient anima and we will power the Greeter once more.", objectives = "" }
WordHunterWoW_QuestEN[57113] = { title = "On Lysonia's Trail", description = "Our scouts have reported spotting Lysonia and Uther en route to the Temple of Humility.\n\nAs the de facto leader of the Forsworn, we must not allow her to stand free, twisting the minds of those around her.\n\nThe disciples of Humility have not answered our beckons. I have sent Kleia ahead to reconnoiter. Meet her outside the temple.", objectives = "" }
WordHunterWoW_QuestEN[57114] = { title = "Aerial Reconnaissance", description = "The temple grounds are crawling with those loyal to the Forsworn.\n\nIf I were still an aspirant, this task would be monumental. Luckily, that is no longer the case.\n\nLet us survey the situation from the sky. We can both take stock of the challenges ahead and find any survivors we can.", objectives = "" }
WordHunterWoW_QuestEN[57115] = { title = "Sacred Scrolls of Humility", description = "The Forsworn are ransacking the library, looking for specific texts amongst our archives.\n\nWe cannot allow them to uncover the scrolls they are searching for. Find any set aside scrolls and return them to me for safekeeping.", objectives = "" }
WordHunterWoW_QuestEN[57116] = { title = "Succumbing to Pride", description = "The aspirants that spend the most time at this temple are those who must face their pride.\n\nI was one of them, once.\n\nDuring our surveillance, I saw Forsworn forcing these aspirants to fall to their vices then toss them aside as if they meant nothing.\n\nYou must stop the Forsworn. Free the aspirants from a terrible fate.", objectives = "" }
WordHunterWoW_QuestEN[57117] = { title = "Fallen to Their Vices", description = "Lysonia's forces ransack our sacred temple... they are long gone from the Archon's embrace.\n\nIt pains me to say, but you must defeat them so they can no longer abuse our people.\n\nTake Compassion with you. You will find it more than helpful, now that its power has returned.", objectives = "" }
WordHunterWoW_QuestEN[57118] = { title = "Distorted by the Maw", description = "Lysonia's forces are rerouting the anima collectors to spew Maw energy across the temple. They hamper our forces while strengthening their own.\n\nThe collectors have been tainted. Take Compassion and destroy them to halt Lysonia's boon.", objectives = "" }
WordHunterWoW_QuestEN[57120] = { title = "Compassion, Blade of Humility", description = "<You find a familiar sword impaled into one of the Forsworn corpses. The Paragon of Humility must have left it behind in pursuit of Lysonia.\n\nIt seems inert, as if all its anima has been used. Perhaps you could restore it to its usual glory.>", objectives = "" }
WordHunterWoW_QuestEN[57121] = { title = "The Power of the Maw", description = "Lysonia flees to the Maw to enact her dark rituals. As the Maw Walker, you are the only one who can pursue her.\n\nTake Kleia and my blade. She must be stopped.", objectives = "" }
WordHunterWoW_QuestEN[57122] = { title = "A Step Too Far", description = "My initial scouting revealed things I did not believe at first.\n\nThe Mawsworn hold Forsworn captive here, transforming them against their will.\n\nThough the Forsworn stand against the Archon, they are still kyrian. It is our duty to free them.", objectives = "" }
WordHunterWoW_QuestEN[57123] = { title = "Kyrian No More", description = "Mawsworn kyrian... I have not seen one since that vision when we first met.\n\nI am not intimidated. They are enemies of Bastion, of the Archon, and it is our duty to defeat them.", objectives = "" }
WordHunterWoW_QuestEN[57124] = { title = "Her Will, Inflicted", description = "I feel myself drawn across the double bridges to the west...\n\nLysonia must be there.\n\nCome, {name}. We must confront her before she can escape again. Who knows what she plans.", objectives = "" }
WordHunterWoW_QuestEN[57125] = { title = "Time to Reflect", description = "I knew that Devos had powerful allies. I turned a blind eye. When Lysonia took her place... I was blinded by my loyalty.\n\nI have much to reflect on.\n\nWe may not be allies, but I have one request. Please, escort me from this wretched place. I will leave you be... but do not leave me here in the Maw.", objectives = "" }
WordHunterWoW_QuestEN[57126] = { title = "...And Following Seas", description = "My brother Derek died in the Second War, only to be raised against his will by the Banshee Queen. If not for Baine Bloodhoof's courageous act of defiance, Derek would have been turned into a weapon against my family.\n\nHe's lived in torment since his awakening. I feared he would be lost to us, but he has received help from an old friend of mine who has also been recently raised--Calia Menethil. She has guided him back from the brink of despair.\n\nI am on my way to pay them a visit. Care to join me?", objectives = "" }
WordHunterWoW_QuestEN[57130] = { title = "Traitors In Our Midst", description = "There is a difference between loyalty and blind obedience. I am done following the Banshee's orders!", objectives = "" }
WordHunterWoW_QuestEN[57131] = { title = "Let the Hunt Begin", description = "One step remains until we may begin the Penitent Hunt.\n\nYou and the other hunters will first siphon a small amount of anima from the souls. It will come with ease. The soul's time in the Grove of Terror causes trace anima to release.\n\nThis anima helps us venthyr in tracking the prey's fear.\n\nI also ask that you do us the honor of signaling the hunt.\n\n<The Fearstalker hands you an anima stake and a hollowed dredbat fang.>\n\nUse these to complete the task.", objectives = "" }
WordHunterWoW_QuestEN[57136] = { title = "The Penitent Hunt", description = "You will descend upon these poor souls. Remember, you are helping them and Revendreth through the terror you bring. When a soul is filled with fear, their resistances to our methods falter.\n\nThe Master has requested that you hunt the Accuser yourself. But we must prey upon some of the others first.\n\nI will be able to guide you through your first hunt.", objectives = "" }
WordHunterWoW_QuestEN[57147] = { title = "Not My Warchief", description = "There is little time. Sylvanas likely knows of my intentions and sent you to deal with me accordingly. I doubt she will be pleased with your decision.\n\nWe must make our way to the wyverns and take to the skies.", objectives = "" }
WordHunterWoW_QuestEN[57148] = { title = "Siegebreakers", description = "The fools who follow Saurfang have grown bold enough to launch a direct assault. We cannot allow these pests to swarm before our gates.\n\nOur operatives are collapsing the pass between Razor Hill and Orgrimmar as we speak. Saurfang's treasonous forces will be cut in half.\n\nYour task is to sneak into their ranks and sabotage their siege engines. Wear this disguise, but know that it will not hold up under close examination. Slay anyone who discovers you.", objectives = "" }
WordHunterWoW_QuestEN[57149] = { title = "Propaganda Takedown", description = "Recently, dissidents have been posting propaganda around the city and spreading all manner of lies.\n\nThis is no time to entertain delusion. An army of traitors and sworn enemies assembles at our gates. These ingrates would see us become pin cushions for the Alliance's archers.\n\n<Nathanos rolls his eyes.>\n\nTear down the rubbish. It can only lead to panic in the streets. \n\nAnd should you encounter any... resistance... you are hereby authorized to respond with force.", objectives = "" }
WordHunterWoW_QuestEN[57150] = { title = "Militia", description = "The war has proven costly and our ranks have been steadily depleted. But the Horde is nothing if not strong. Each and every citizen of Orgrimmar is worth ten Alliance weaklings on the battlefield.\n\nRally the citizens and form a militia! Remind them of their slain brothers and sisters!", objectives = "" }
WordHunterWoW_QuestEN[57151] = { title = "A Line in the Sand", description = "Now that we have put our house in order, it is time to purge the filth before our gates.\n\nHow thoughtful of those traitors to gather themselves in one place, so that we may slay them all in one fell swoop.\n\nLet us end this pitiful rebellion.", objectives = "" }
WordHunterWoW_QuestEN[57152] = { title = "Most Loyal", description = "The Dark Lady anticipated this as a possible outcome. She has prepared a contingency plan to deal with it accordingly.\n\nYou are to rendezvous with her in the Ghostlands. Take this hearthstone. It is good for one more use. \n\nShe will meet you near Windrunner Spire.", objectives = "" }
WordHunterWoW_QuestEN[57155] = { title = "Blinding the Eye", description = "Ah yes, just the {class} I wanted to see.\n\nI can still sense his touch lingering upon you. Our victory over the god of the deep will not be complete until we remove all traces of his infection.\n\nThrough my research I have learned a less painful way of removing the infection.\n\nSpeak with me, and let's put an end to this nightmare.", objectives = "" }
WordHunterWoW_QuestEN[57156] = { title = "Blinding the Eye", description = "You finally arrived {name}. Dat dark mojo on you has lingered for too long. N'Zoth be defeated and we need to cleanse all de traces of his infection from you.\n\nDis won't hurt. Much.\n\nTell me when you are ready to begin.", objectives = "" }
WordHunterWoW_QuestEN[57159] = { title = "A Reflection of Truth", description = "I sent the Fearstalker far from here with that trap--buying us some time.\n\nOn the other side of this mirror lies the depths of Castle Nathria, the fortress of Denathrius himself. There, a meeting between Denathrius and one of his lackeys is about to take place.\n\nJoin me through the mirror, {name}. You shall see the truth of this \"drought\" first hand.", objectives = "" }
WordHunterWoW_QuestEN[57161] = { title = "I Don't Get My Hands Dirty", description = "You heard Sire Denathrius. Today, I ascend to the Court of Harvesters.\n\nYou are fortunate to have the honor of witnessing my rise to power.\n\nThe traitors have barricaded the bridge ahead. Clear a path for me, so that I might cross it undisturbed.\n\nNothing can stand against me now that I have a Harvester's medallion.\n\nBut I will not waste my power on this rabble.", objectives = "" }
WordHunterWoW_QuestEN[57164] = { title = "Devour This", description = "Though the souls are our primary target, another challenge has arisen.\n\nThe Banewood has seen an infestation of devourers: disgusting vermin who gorge themselves on the anima we need to survive. A fitting challenge for any true hunter, no?\n\nI should only thank the Master that they have remained in a few secluded pockets. I loathe to think that their numbers could multiply. Let us exterminate them before they pose a true threat.", objectives = "" }
WordHunterWoW_QuestEN[57172] = { title = "Break Their Will", description = "The timing of your arrival is a sign. You are the force behind the Arbiter. The only one to walk in and out of the Maw in ages. You are the symbol that can help crush this rebellion once and for all.\n\nOnly one leader remains who is strong enough to command the Darkwing Legion. The Accuser. Defeat her, and the rebellion will fall.\n\nHere, take this medallion. Place it in the hands of my faithful Lord Chamberlain in the Grand Palisade. Together, you and he can crush this rebellion.", objectives = "" }
WordHunterWoW_QuestEN[57173] = { title = "The Accuser's Sinstone", description = "Lord Chamberlain will cross the bridge when it pleases him.\n\nBefore he arrives, you will seize the Accuser's sinstone.\n\nWise venthyr like Lord Chamberlain hide their sinstone, so that it can never be used against them.\n\nThe Accuser is too proud to hide her sinstone. Instead, she puts it on display for all to see.\n\nBoasting of the many, many sins she's overcome.\n\nProud. Arrogant. Most importantly, foolish.\n\nHer sinstone lies on the altar before us, seemingly unguarded. Retrieve it.", objectives = "" }
WordHunterWoW_QuestEN[57174] = { title = "The Stoneborn", description = "The Stone Legion is not even here yet? This is an outrage.\n\nIf we do not do something quickly, the rebels will overrun this filthy hamlet.\n\nHere, take the anima and go activate a few of the stoneborn along the periphery of Darkhaven. Take whatever is left over to the Quartermaster and tell her to do her job.\n\nI will try to commune with the Master and see if he can send reinforcements.", objectives = "" }
WordHunterWoW_QuestEN[57175] = { title = "Inquisitor Vilhelm's Sinstone", description = "Inquisitor Vilhelm has taken exceptional precautions to protect his sinstone.\n\nBroken into several pieces and hidden from sight, he believed his sinstone would be safe from us.\n\nBut his plan had the same weakness as most: he trusted weak-willed underlings.\n\nI \"interrogated\" several dredgers to learn where they helped the inquisitor hide the broken fragments of his sinstone.\n\nFind all the fragments and bring them to me.", objectives = "" }
WordHunterWoW_QuestEN[57176] = { title = "Sinstone Delivery", description = "Lord Chamberlain has held off the Accuser to buy us the time we needed to break the ward on her sinstone.\n\nBut, thanks to your delays, our reinforcement of his position is overdue.\n\nI will collect the Accuser's sinstone and carry us to the battle.", objectives = "" }
WordHunterWoW_QuestEN[57178] = { title = "The Master Awaits", description = "Maw Walker, I am General Kaal. Those stoneborn who remember their oaths to the Master are under my command.\n\nThe path between here and Sire Denathrius is no longer secured by my forces. I am pulling my troops from this ward to support the Master's will elsewhere. \n\nSire Denathrius has dispatched me to bring you directly to him. Myskia can carry you.", objectives = "" }
WordHunterWoW_QuestEN[57179] = { title = "The Authority of Revendreth", description = "{name}, a proud {race} {class}. I know your name and your deeds. I can taste your regrets and your shame.\n\nMore importantly, I know what you might become. You can be the beacon for the Shadowlands to rally behind. The symbol my people need to set aside these petty squabbles and help fix the problems that afflict all reality.\n\nBefore you stands the Court of Harvesters, my most loyal and trusted venthyr. Where once there were seven, only four remain. \n\nIntroduce yourself to them, for where they go, my power follows", objectives = "" }
WordHunterWoW_QuestEN[57180] = { title = "The Accuser's Secret", description = "Now that I possess the Accuser's sinstone, I can finally end her treasonous charade once and for all!\n\nProtect me while I study this sinstone, and you will be rewarded as first among my retainers.\n\nAfter I crush her with my incredible power, I will seize control of the Halls of Atonement and receive the Master's reward.\n\nThis feat heralds my own ascension to the Court of Harvesters!", objectives = "" }
WordHunterWoW_QuestEN[57182] = { title = "The Accuser's Fate", description = "You now stand in the presence of a Harvester, Maw Walker.\n\n<Lord Chamberlain breathes in deeply and smiles.>\n\nI will use the Accuser's medallion to solidify my foothold over the Halls of Atonement.\n\nMeanwhile, the Master has requested that you deliver both the Accuser and the medallion that he loaned to me.\n\nMyskia will be along shortly to retrieve you. Do not keep the Master waiting.", objectives = "" }
WordHunterWoW_QuestEN[57185] = { title = "Dutybound", description = "Welcome to the fight, {name}. You're with us now.\n\nTake a moment and introduce yourself. I will meet you by Draven at the lodge.", objectives = "" }
WordHunterWoW_QuestEN[57189] = { title = "Breaking the Hopebreakers", description = "The Fearstalker has surely sent her hunters across the entirety of the Banewood in search of us, {name}. \n\nDraven informed me that some of her top hunters are scouring Dredhollow as we speak. We can use this to our advantage. Slaying them should get her attention.\n\n<The Accuser hands you a collection of bright red vials.>\n\nThrow these on her hunters. It should draw the attention of the devourers infesting this place.", objectives = "" }
WordHunterWoW_QuestEN[57190] = { title = "They Won't Know What Hit Them", description = "Luring the Fearstalker here will prove pointless unless we can tilt the odds. She will surely show up with a small army. \n\nPlant these anima containers. When the time comes, we will release their contents into the air, dousing her and her forces in a thick layer of anima.\n\nThat should get the devourers infesting this place to flock to them like moths to a flame.", objectives = "" }
WordHunterWoW_QuestEN[57198] = { title = "Sense of Obligation", description = "Derek is free. I have to atone for much with him.\n\nThere is a rumor of a meeting with Jaina and her brother.\n\nHead to Seabreeze Village in Stormsong Valley. I hope there you will be able to find out... well, let's just say I am trying to keep the bigger picture in focus.\n\nIf you find out anything of interest, I would be most appreciative.\n\nFor now, let's keep this between the two of us.", objectives = "" }
WordHunterWoW_QuestEN[57207] = { title = "Lysonia's Plan", description = "Lysonia has brought the Paragon to his knees! The Maw powers she wields are far too potent.\n\nWe must stop her.", objectives = "" }
WordHunterWoW_QuestEN[57220] = { title = "Power Protocol Initiation", description = "We've come a long way, {name}.\n\nOnce the power from the auxiliary systems are brought online MOTHER will be able tae run diagnostics.\n\nAll that's left is settin' the final pieces in place.", objectives = "" }
WordHunterWoW_QuestEN[57221] = { title = "Re-Origination", description = "If the Ramkahen haven't reached out tae sound any alarms then the anomaly must be contained within the Halls of Origination.\n\nWe best get back tae investigate, {name}.", objectives = "" }
WordHunterWoW_QuestEN[57222] = { title = "Investigating the Halls", description = "Whatever's happenin' has tae be comin' from deep within the inner chamber. If we can get tae the forge maybe we'll find some answers.\n\nBest check yer gear 'fore headin' in, {name}. Who knows what's waitin' fer us in there.", objectives = "" }
WordHunterWoW_QuestEN[57228] = { title = "The Assault on Dredhollow", description = "The time is upon us, Maw Walker. The Fearstalker's hunters are descending upon us.\n\nWe have done all we can do to prepare for their assault. Here.\n\n<The Accuser gives you an ornate staff.>\n\nI fashioned this out of the supplies you brought me. Use it to destroy the Fearstalker's forces.\n\nThe fight begins.", objectives = "" }
WordHunterWoW_QuestEN[57240] = { title = "Where is Prince Renathal?", description = "This is not victory, {name}. If Prince Renathal does not return, we've merely delayed defeat.\n\nThe Prince was last seen during an assault on the Master's keep alongside Duke Theotar.\n\nWe don't know the Prince's fate, but we've learned that Duke Theotar was banished to the Ember Ward.\n\nThe Ember Ward is a land of madness and torture. Blighted by the Light, the Master sends his most hated enemies there to suffer unending agony.\n\nEnter the Ember Ward, find Theotar, and discover the Prince's fate.", objectives = "" }
WordHunterWoW_QuestEN[57245] = { title = "Ani-Matter Animator", description = "This area is rich with the remains of fallen soldiers... some of which still carry a spark of potential.\n\nI've created what I call the \"Ani-Matter Orb,\" with which you can reanimate the skeletal matter littered throughout the foundry. \n\nLet us see how many of the new animates would join our cause.\n\nAs for those who don't... well, they should be quite accustomed to being slain by now.", objectives = "" }
WordHunterWoW_QuestEN[57249] = { title = "A Timely Invitation", description = "The time has arrived to remember the past and celebrate our adventures across Azeroth and Beyond. \n\nTo commemorate the occasion the Bronze Dragonflight is throwing a celebration and you are invited! \n\nCome to the Caverns of Time and present this ticket to gain entry to the party!", objectives = "" }
WordHunterWoW_QuestEN[57261] = { title = "Walk the Path, Aspirant", description = "If you wish to stand before the Archon, there is a path you must walk. Thankfully, it is well worn and serviceable even in these dire times.\n\nThough you are not destined to become kyrian, our ways may be of interest to you. Learn well, learn fast, and perhaps the Archon will take notice and grant you this audience you seek.\n\nAspirant Kleia will show you the way. Archon's eyes upon you.", objectives = "" }
WordHunterWoW_QuestEN[57263] = { title = "The Cycle of Anima: Etherwyrms", description = "Forge is cold, yes? Need LOTS of anima to light.\n\n<Sika references her scroll.>\n\nTimes before now, anima is everywhere, yes? Now it hides. Small bits, weird places.\n\nWe know that etherwyrms -- flappy scale-things that are blue -- eat anima. They are not dead, so they are finding anima to eat still, yes?\n\nMaybe if we take what they have eaten, we can use it to light the forge. This will probably kill them.\n\nSad, yes. But! We will not take too much. Just a little.", objectives = "" }
WordHunterWoW_QuestEN[57264] = { title = "On the Edge of a Revelation", description = "Ah! Good. You answered the call.\n\nAs you can see, there are many aspirants who require our aid. Myself and the other disciples are hard pressed to deal with all of them. Some are in greater need than others.\n\nAspirants are most at risk when they are on the precipice of a revelation. It is a critical moment that we cannot allow to pass without intervention.\n\nYou must push them, one way or another.\n\nFind the most vulnerable among your peers and do what you can to help them find the path forward.", objectives = "" }
WordHunterWoW_QuestEN[57265] = { title = "The Cycle of Anima: Drought Conditions", description = "In days past, keeping a forge burning was a trivial task. The anima extractors could run constantly without ever running dry.\n\nNow, even turning an extractor on is a risk. Etherwyrms, without the anima streams to feed on, are attracted to any source of anima. They are a frequent nuisance.\n\nI am going to ask that you risk their attentions. Activate the extractor and guard it until it can accumulate what little anima remains.\n\nBring me the product it collects. Let us hope it is enough.", objectives = "" }
WordHunterWoW_QuestEN[57266] = { title = "The First Cleansing", description = "This situation may feel familiar, {name}.\n\nWhen you found Pelagos, he was undergoing a similar rite. As you saw, it can end in violence.\n\nThis will be the first time you are asked to draw out the burdens that held you to a mortal life. It may be a painful process. It is for many.\n\nFor you, this is the path you must walk to attain your goals. To earn the right to stand among us, to be heard. So we may carry your message to the Archon herself.\n\nCenter yourself. When you are prepared, we will begin.", objectives = "" }
WordHunterWoW_QuestEN[57267] = { title = "The Cycle of Anima: Flower Power", description = "For forge to light, need more anima. Always more. Never too much, for forge!\n\n<Sika consults her scroll and nods vigorously as she reads.>\n\nOut in fields, there is a glowy flower. The round thing inside. Bulb? It glows. So, has anima. From the ground, we think.\n\nAccording to scrolls, it is called Adrima's Lily. We do not know who Adrima is. But the lily is good.\n\nGet flowers, too. Not just bulbs. Petals make stewards happy, too. \n\nThank you!", objectives = "" }
WordHunterWoW_QuestEN[57269] = { title = "The Hand of Doubt", description = "Quickly! We have no time to lose. Lysonia has weakened Eridia to the point that she may fall. Our Paragon will do what she can, but we must intervene.\n\nWe will challenge Lysonia, and perhaps buy Eridia more time. \n\nThis so-called Hand of Doubt will make no easy foe. Stand ready, {name}.", objectives = "" }
WordHunterWoW_QuestEN[57270] = { title = "The Temple of Purity", description = "Greetings.\n\nI am Kosmas, Disciple to the Temple of Purity.\n\nThe temple is a place of cleansing. Its sole purpose is to free aspirants of the burdens they carry with them from life. It is a place of quiet reflection even for those who have shed their burdens.\n\nOf late, those who look to us for purification have grown numerous. My fellow disciples are stretched terribly thin. I have come to ask the aid of all able-minded aspirants.\n\nYour help is needed. Please report to the Hand of Purity at once.", objectives = "" }
WordHunterWoW_QuestEN[57274] = { title = "Quartermaster's Bounty", description = "To defeat the enemy, you will need to keep your equipment in peak condition. If you have been unable to acquire more powerful arms, I can requisition from the quartermaster on your behalf.", objectives = "" }
WordHunterWoW_QuestEN[57275] = { title = "Something in Your Mind", description = "<Looking into the crystal, the light around you is slowly drowned in inky smoke. An imposing presence crushes down on you, whispering unintelligibly in your ear. Looking for the source, you see nothing, but the sensation grows. Your head begins to swim as the darkness deepens and the noise becomes deafening.\n\nSummoning all your willpower to steel your resolve...\n\nThe light has returned, the noise silenced, and you stand with a humble crystal in your hand.\n\nPerhaps Wrathion knows more about it...>", objectives = "" }
WordHunterWoW_QuestEN[57276] = { title = "Maintaining Focus", description = "At present, the focus holds but a fraction of N'Zoth's true power. If we further empower it, we could craft even more effective weapons to wield against him.\n\nN'Zoth's influence is everywhere, {name}, and is most concentrated within powerful foes. Vanquish them and claim whatever vestiges of the Old God's power remain.", objectives = "" }
WordHunterWoW_QuestEN[57278] = { title = "Bring Me Their Heads", description = "I swore to the grave of Vistara the Fallen that I would bring him the head of the one who betrayed him. \n\nThough that was eons ago, it is an oath I must fulfill. Whatever fate ultimately befell the traitor, it is likely that his head can still be found nearby.\n\nSlaughter everyone here. Surely one of them must be the traitor... or be in possession of his head.", objectives = "" }
WordHunterWoW_QuestEN[57284] = { title = "Blade of Blades", description = "The finest sword in existence has been lost!\n\nNever in your pitiful adventures have you encountered such a blade, mortal. Foe Cleaver was forged to strike down the titans themselves!\n\nI have wielded it against countless adversaries. Emissaries of the Light, minions of the Void, meddlers from the Gardens of Life... all have fallen before me! Soon the very planes of reality will kneel to my greatness!\n\nOnce I find my weapon, that is.\n\nI insist you help me reclaim it. I know it's here somewhere!", objectives = "" }
WordHunterWoW_QuestEN[57288] = { title = "Assessing Your Strength", description = "The trial to come will test you in ways you can likely only imagine.\n\nI can see both from your past and from your demeanor that you are no stranger to combat. I would like to know where your strengths lie so we may address any weaknesses we find before your trial.\n\nYou will find three praetorian soldiers created for this purpose, each stronger than the last.\n\nDefeat them all and I will consider your strength sufficient to continue at this time.", objectives = "" }
WordHunterWoW_QuestEN[57290] = { title = "Beginning the Descent", description = "Protecting one's mind against the old gods requires an object of pure corruption. Unbeknownst to many, one such object exists--dormant beneath the molten pits of Blackwing Descent.\n\nUntil recently, one of my agents stood watch over the area, keeping detailed records of suspicious activities. Unfortunately, this agent has gone silent. It is now clear we are not the only ones with this knowledge.\n\nIf we are to find answers, there is one place to look.\n\nOur journey continues, {name}. Blackrock awaits.", objectives = "" }
WordHunterWoW_QuestEN[57291] = { title = "The Chamber of First Reflection", description = "Ah, Athanos. It remains undefeated, as intended.\n\nStill, you have exceeded any expectation I might have had. You are stronger than many that have come before you.\n\nYou have come here for a purpose, and Kleia has illuminated a path that she believes you can walk. I agree. I have opened the way to the Crucible's final rite.\n\nFollow the path to the south and east. There you will find the entrance to the Chamber of First Reflection.\n\nKleia will instruct you further. Go in service, {name}.", objectives = "" }
WordHunterWoW_QuestEN[57298] = { title = "How Things \"Really\" Happened...", description = "You've come a long way over the years, {name}.\n\nFrom humble beginnings doing odd jobs to saving Azeroth's very existence, you've done so much to ensure the safety of our world.\n\nBut why should we just stand around trying to remember things? Let's just go back in time and relive all of the exciting bits again! \n\nDon't worry, in all of the millions upon millions of timeways I'm sure I'll find one where you never die.", objectives = "" }
WordHunterWoW_QuestEN[57300] = { title = "Soldier of Time", description = "Long ago, the land of Alterac Valley was peaceful. However, when the Frostwolves moved in it became highly contested real estate between them and the Stormpikes. Battles used to rage for days. \n\nWell, actually the battle is still ongoing, the bronze dragons have figured out a way for you to revisit those early days.", objectives = "" }
WordHunterWoW_QuestEN[57301] = { title = "Callous Concoctions", description = "I witnessed your success with the Pool of Potions and I think you could be of help. Within this larger pool, we create more dangerous mixtures!\n\nThere are three different oozing ingredients we mix together in different combinations to create violent creatures. When enough ingredients have been added to the pool, the mixture takes shape and a creature will emerge!\n\nBring any combination of these ingredients, Mephitic Goo, Viscous Oil, or Miscible Ooze to the Pool of Mixed Monstrosities.", objectives = "" }
WordHunterWoW_QuestEN[57302] = { title = "Alterac Valley Graveyards", description = "The graveyards in Alterac Valley are prized territories.  Both the Horde and the Alliance fight savagely for these sacred grounds.  Are you, {name}, ready to join that fight?\n\nI want you to assault an enemy graveyard.  Find a graveyard with a Horde banner in its midst, and pull it from the ground!  Do that, and your task will be complete....\n\nBut if you can also hold the graveyard for a few minutes, then our troops will soon come to relieve you.", objectives = "" }
WordHunterWoW_QuestEN[57303] = { title = "The Quartermaster", description = "{name}, our quartermaster charged me to direct new recruits to him.  He needs supplies from caches stored in the mines of Alterac, and he'll probably send you to get them.\n\nFollow the road.  You'll find our quartermaster to the west.", objectives = "" }
WordHunterWoW_QuestEN[57304] = { title = "Capture a Mine", description = "The mines in Alterac Valley hold more than just minerals.  Both the Frostwolf and Stormpike have cached excess supplies in the Irondeep and Coldtooth mines... that's not a bad idea, if we could only maintain control of them!\n\nCapture a mine, then return to me.  To capture a mine, enter one that we do not control and kill its leader.  When you do that, the mine will be ours, and we'll send troops to protect it!", objectives = "" }
WordHunterWoW_QuestEN[57305] = { title = "Armor Scraps", description = "Battles rage constantly in Alterac Valley, and the supplies we get from Ironforge are not enough to outfit our experienced troops.\n\nIf you find armor scraps from the battlefield, aid the war effort and bring those scraps to me!", objectives = "" }
WordHunterWoW_QuestEN[57307] = { title = "Towers and Bunkers", description = "Towers and bunkers are key defensive positions, and so we must hold as many as possible!  I want you to attack a tower or a bunker in Alterac Valley.\n\nTo do that, enter a tower with a Horde banner atop it.  You will see another enemy banner inside.  Pull out that banner, and a white Alliance banner will appear in its place.  Well done!\n\nAt that point your mission for me will be complete, but hold the area long enough, and if the Horde doesn't take it back, then it will be destroyed!", objectives = "" }
WordHunterWoW_QuestEN[57308] = { title = "The Battle of Alterac", description = "The Explorers' League believes there are artifacts in Alterac Valley, but the Frostwolf orcs won't let us explore.  We can't allow the Horde to stop our scholarly pursuits!  Defeat the Frostwolf general, Drek'Thar.  With him dead, the orcs will lose their edge.\n\nDrek'Thar is in Frostwolf Keep, in the south of Alterac Valley.  Vanquish him, and then return to me.", objectives = "" }
WordHunterWoW_QuestEN[57312] = { title = "The Graveyards of Alterac", description = "The battle lines of Alterac Valley are ever shifting.  Territories swing back and forth as we meet our opponents in deadly combat.  And graveyards, {name}, are where battles rage most fierce.\n\nI want you to attack an Alliance held graveyard!  Find a graveyard with an Alliance banner in its midst and pull it from the ground.\n\nDo that and your task for me will be complete, but... if you hold the graveyard for a few minutes, then it will be ours and troops will come and relieve you.", objectives = "" }
WordHunterWoW_QuestEN[57313] = { title = "Speak with our Quartermaster", description = "{name}, the Frostwolf Quartermaster is looking for recruits, for tasks that lead into the mines of Alterac Valley.  Speak with him; he will tell you more.\n\nFollow the road west into the bunker, then take the west exit and you'll find our quartermaster.", objectives = "" }
WordHunterWoW_QuestEN[57314] = { title = "Capture a Mine", description = "As battle rages over the landscape of Alterac Valley, so too does it rage through the Coldtooth and Irondeep mines.  Both are rich sources of minerals and both are used to store supplies; it's no wonder they are so highly valued!\n\nHelp our war effort, {name}!  Capture one of the mines for the Horde!  To capture a mine, enter one that we do not control and kill its leader.  When that is done, the mine will be ours and we'll send troops to protect it!", objectives = "" }
WordHunterWoW_QuestEN[57315] = { title = "Towers and Bunkers", description = "Towers and bunkers are important positions, and we must capture and hold them all!  So to that end, I want you to attack a bunker that is controlled by the enemy.\n\nTo do that, enter one with an Alliance banner.  You will see another banner inside.  Pull out that banner, and a white Horde banner will appear in its place.  Well done!\n\nAt that point your task for me will be complete, but if you hold the place long enough, and if the Alliance doesn't take it back, then it will be destroyed!", objectives = "" }
WordHunterWoW_QuestEN[57316] = { title = "The Ladder", description = "Within the Theater of Pain, brother, legends rise like cream to the top.\n\nListen to me, brother. If you have the courage to step into that sacred arena, you're going to face the greatest threats in all of existence! The cards will be stacked against you, but only those who can work together will emerge as champions.\n\nGather your team and meet this challenge head on! Enter the Theater of Pain and defeat the opponents within! Prove that you can rise to the top!", objectives = "" }
WordHunterWoW_QuestEN[57317] = { title = "Enemy Booty", description = "When you fight the enemy, gather the scraps of their armor and bring them to me.  I'll use those scraps to make armor for our own troops!", objectives = "" }
WordHunterWoW_QuestEN[57319] = { title = "The Battle for Alterac", description = "The Stormpike dwarves and their allies have invaded Alterac Valley, and we must drive them out!  To win the battle for Alterac, we must defeat their general, Vanndar Stormpike!\n\nYou will find Vanndar in Dun Baldar, in the north of Alterac Valley.\n\nDestroy him, {name}, and then return to me.", objectives = "" }
WordHunterWoW_QuestEN[57324] = { title = "Sail With the Tide", description = "Hello, {name}.\n\nI have received word from Calia asking that we meet with her once again. \n\nShe has so much to offer those who feel lost, those seeking a better way. Once she is free of doubt, she will know what must be done.\n\nWill you join me?", objectives = "" }
WordHunterWoW_QuestEN[57326] = { title = "Prototypes for Profit", description = "<Gazlowe pulls you in close and whispers.>\n\nLookit here, {name}. I gotta keep my nose clean here in front of the prince.\n\nBut I trust you know what's gotta be done outside of town, yeah?\n\nOutside of town... where all the tech is...\n\nTech that Alliance grubs are tryin' to get their clumsy mitts on...\nwhich we could use for the Horde...\nto build big weapons...\nand scary robots...\nand other lucrative products...?\n\nI don't gotta spell this out for you, right?", objectives = "" }
WordHunterWoW_QuestEN[57327] = { title = "Prototypes for Inspiration", description = "<Overspark pulls you in close and whispers.>\n\nAs the leader of this momentous expedition, I must stay with Prince Erazmin to ensure he's not swindled by this Horde hooligan.\n\nBut I cannot stop my research, or the Horde will gain the advantage!\n\nUnderlings like yourself must collect the technology samples required to fuel my legendary brainstorms.\n\nBring me prototypes from the island, and I will turn them into groundbreaking new innovations for the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[57362] = { title = "Deeper Into the Darkness", description = "This recent change of events allows us to continue our journey to discover what darkness lies beyond the sands.\n\nIt will not be easy, {name}. We stand on the precipice of the unknown, but now the tables have turned.\n\n<Wrathion glances at your new attire.>\n\nYou do dress the part. \n\nLet's see what insights your return to the Halls of Origination bring to light.", objectives = "" }
WordHunterWoW_QuestEN[57370] = { title = "Assault: The Black Empire", description = "", objectives = "" }
WordHunterWoW_QuestEN[57371] = { title = "Assault: Aqir Unearthed", description = "", objectives = "" }
WordHunterWoW_QuestEN[57373] = { title = "Descending Into Madness", description = "As unfortunate as the spreading corruption may seem, I believe it provides us the opportunity to prepare for what lies ahead.\n\nLocate one of these incursions and see what happens when you peer beyond the dark veil.", objectives = "" }
WordHunterWoW_QuestEN[57374] = { title = "Into the Darkest Depths", description = "With our connection secured, it is time for us to breach the veil and discover what lies beyond.\n\nWhat you find may provide us the key to unlocking our success.", objectives = "" }
WordHunterWoW_QuestEN[57376] = { title = "The Hidden Need", description = "Because of Sylvanas, some members of the Horde are skeptical of the Forsaken. We must regain their trust. \n\nWe cannot do that without accepting ourselves. So many feel lost, alone... abandoned.\n\nI have arranged a meeting. It could be a big step... or all go horribly wrong. Either way, you should bear witness.\n\nMeet me in Tirisfal Glades, at the Calston Estate.", objectives = "" }
WordHunterWoW_QuestEN[57377] = { title = "A Hand Offered", description = "Here begins the calia intro", objectives = "" }
WordHunterWoW_QuestEN[57378] = { title = "Remnants of a Shattered World", description = "The knowledge gained from these visions affords us a unique opportunity to further protect one's mind from corruption. To continue our research, we must investigate the deeper mysteries of these experiences.\n\nSeek out those of power within these visions. Should you come across anything of interest do not hesitate to share your findings.\n\nIn the meantime, MOTHER and I shall continue our research here in the chamber. \n\nWe await your return, {name}.", objectives = "" }
WordHunterWoW_QuestEN[57380] = { title = "Sign Your Own Death Warrant", description = "Ember Ward only for bad buds!\n\n<Stonehead squints at you and shakes head.>\n\nYou not look like other bad buds!\n\nBad buds come with bad paper!", objectives = "" }
WordHunterWoW_QuestEN[57381] = { title = "The Greatest Duelist", description = "A mortal in Revendreth. Well, well, well... you are primed to be at the head of high adventure.\n\nThe name you may call me is Nadjia the Mistblade, and, if I might be so humble as to say, I am the finest duelist that has ever wielded a sword.\n\nThis trap you found me in was a lesson learned in getting paid in advance. Release me and my blade is yours to command for as long as I find you interesting.\n\nDo we have an accord?", objectives = "" }
WordHunterWoW_QuestEN[57386] = { title = "If You Want Peace...", description = "Maldraxxus is a land which revels in strife and conflict. But they should also be bound by honor.\n\nIf their honor has been tossed aside, then they may move their forces beyond just Bastion.\n\nTake care, danger lies beyond that gate. It is a realm of heroes as well as a realm of villains.", objectives = "" }
WordHunterWoW_QuestEN[57390] = { title = "To Die By the Sword", description = "What's this? You fly no colors! Where is the pride in your house, gladiator?\n\nBah, this drought has left us with slim pickings indeed, if this is the best Maldraxxus can muster!\n\nI remember the old days. The strongest souls arriving, then being divided among the five houses...\n\nNo matter. The tournament beckons. Enter the arena! Fight for glory!\n\nBy the look of you, it's likely you won't last long. Try to make a name for yourself in the time you have left.", objectives = "" }
WordHunterWoW_QuestEN[57391] = { title = "Reconstructing \"The Curse of Stone\"", description = "I came across several references to this book in my research of Ny'alotha. Penned by a neophyte cultist, it documents the \"lies of the Titans\" and the \"injustices\" they inflicted upon the denizens of Azeroth.\n\nMad ravings, intended to erode the reader's acceptance of reality.\n\nStill, by studying this work, we can gain a better understanding of the Old God's power, and thus tailor the cloak to offer better protection against it.\n\nBring as many pages from this tome as you can find.", objectives = "" }
WordHunterWoW_QuestEN[57392] = { title = "Reconstructing \"The Curse of Stone\"", description = "Thus far, the contents of this book are unsettling to say the least. Nevertheless, I have been able to glean valuable information on the nature of N'Zoth's power, and have made alterations to your cloak accordingly.\n\nThere remains much to learn, however. Continue your search for additional pages as you delve into the visions.", objectives = "" }
WordHunterWoW_QuestEN[57393] = { title = "Stepping Through the Darkness", description = "By now you've noticed the protection of your cloak wavering the deeper you delve into these visions. \n\nTo further bolster your resistance to N'Zoth's influence, we will need to gain an even deeper understanding of his nefarious power.\n\nSeek out knowledge from manifestations deeper within the visions, and we shall have our answers soon enough.", objectives = "" }
WordHunterWoW_QuestEN[57394] = { title = "Reconstructing \"Fear and Flesh\"", description = "Another tome written by one lost to N'Zoth's madness. I dread to think of what vile words await us within it.\n\nBut if we are to strengthen your cloak, then we must know more of that which it was meant to resist. See if you can find the remaining pages so that we can complete this tome and make use of the knowledge it holds.", objectives = "" }
WordHunterWoW_QuestEN[57395] = { title = "Reconstructing \"Fear and Flesh\"", description = "Adherents of the Old Gods maintain that flesh is a gift, not a curse. This tome reflects on the Old Gods' supposed benevolence in granting us such a generous blessing.\n\nNaturally, it omits any mention of what occurs when their corruption is allowed to run unfettered.\n\nGather more of these pages for me. As wretched as these words might be, studying them will allow us to increase the efficacy of your cloak.", objectives = "" }
WordHunterWoW_QuestEN[57396] = { title = "Reconstructing \"Fear and Flesh\"", description = "Adherents of the Old Gods maintain that flesh is a gift, not a curse. This tome reflects on the Old Gods' supposed benevolence in granting us such a generous blessing.\n\nNaturally, it omits any mention of what occurs when their corruption is allowed to run unfettered.\n\nGather more of these pages for me. As wretched as these words might be, studying them will allow us to increase the efficacy of your cloak.", objectives = "" }
WordHunterWoW_QuestEN[57397] = { title = "Reconstructing \"Fear and Flesh\"", description = "Perhaps the most insidious element of the Old Gods' whispers is that they contain within them the smallest kernel of truth. There is something to be said for the joy that comes with feeling the sun on one's skin and the wind in one's hair.\n\nBut you have braved N'Zoth's visions. You have seen where their designs are ultimately meant to lead. The curse of flesh has nothing to do with bringing us joy.\n\nContinue to collect the pages of this book. We have nearly finished piecing it back together.", objectives = "" }
WordHunterWoW_QuestEN[57398] = { title = "Walking in the Darkness", description = "The end nears. The darkest corners of these visions await.\n\nOur work has ensured you are well equipped to seek out the most horrific manifestations these visions have to offer. The final answers lie just beyond. Our preparations for Ny'alotha are nearly complete.", objectives = "" }
WordHunterWoW_QuestEN[57399] = { title = "Reconstructing \"The Final Truth\"", description = "I know of this book. It is a sacred tome to those who worship the Old Gods, containing the deepest secrets and most incomprehensible mysteries of the Void. Only the most devout cultists are allowed to gaze upon its pages.\n\nEven incomplete, holding it makes my skin crawl. I must take care not to read too much of it in a single sitting.\n\nThat being said, we must find its missing pages in order to continue our research. Retrieve them from the darkest corners of N'Zoth's visions.", objectives = "" }
WordHunterWoW_QuestEN[57400] = { title = "Reconstructing \"The Final Truth\"", description = "I dare not repeat aloud the horrors that are recorded in these pages. The words themselves seem to shift and morph as I read them, as if the book itself is attempting to induce a descent into madness.\n\nThis is taxing work, but it is necessary if we are to fully prepare you for the dangers of Ny'alotha. For as disturbing as its descriptions might be, setting foot within it will prove more challenging by an order of magnitude.\n\nKeep looking for pages from the book, {name}. But... leave the reading to me.", objectives = "" }
WordHunterWoW_QuestEN[57401] = { title = "Reconstructing \"The Final Truth\"", description = "Long have I studied the secrets of the Old Gods. I have traversed the whole of Azeroth in search of esoteric texts, lost archives, and forbidden knowledge, all in the name of preparing for the horror to come.\n\nNo amount of research could have prepared me for the depths of the insanity I would find within this book. A madness so absolute that only the Shath'yar language can convey it.\n\nFind me the final pages of this accursed tome, {name}. I wish to learn what I need from it and be done with it forever.", objectives = "" }
WordHunterWoW_QuestEN[57402] = { title = "Reconstructing \"The Curse of Stone\"", description = "N'Zoth is nothing if not subtle and insidious. I can see how an impressionable mind could be turned against the Titans by reading these words. Thankfully, we are not so susceptible to such manipulation, are we?\n\nThe book is nearly complete. Continue retrieving its pages from within the visions.", objectives = "" }
WordHunterWoW_QuestEN[57403] = { title = "Reconstructing \"Fear and Flesh\"", description = "Perhaps the most insidious element of the Old Gods' whispers is that they contain within them the smallest kernel of truth. There is something to be said for the joy that comes with feeling the sun on one's skin and the wind in one's hair.\n\nBut you have braved N'Zoth's visions. You have seen where their designs are ultimately meant to lead. The curse of flesh has nothing to do with bringing us joy.\n\nContinue to collect the pages of this book. We have nearly finished piecing it back together.", objectives = "" }
WordHunterWoW_QuestEN[57405] = { title = "Chasing Madness", description = "<This wretched shamble of a venthyr mumbles uncontrollably as it claws at the ground.\n\nIt looks up suddenly and points its finger at you.>\n\nAn adversary with no ferry cannot be merry unless it is wary!\n\n<It seems to be waiting for a response from you.>", objectives = "" }
WordHunterWoW_QuestEN[57414] = { title = "Mount Up Test", description = "", objectives = "" }
WordHunterWoW_QuestEN[57425] = { title = "Land of Opportunity", description = "<The grandmaster's voice rings out over the roaring crowd.>\n\nThis is it! The final event of the tournament!\n\nThese two Maldraxxi gladiators have cut down challenger after challenger. Now the only thing left...\n\nIs for one to slay the other!", objectives = "" }
WordHunterWoW_QuestEN[57426] = { title = "My Terrible Morning", description = "You simply won't believe what happened to me!\n\nI was out for my daily stroll when Marquis Pummeler and his band of ruffians assailed me!\n\nAmongst the many unfortunate and ungentlemanly behaviors they displayed was destroying my parasol.\n\nA tragedy of the highest order!\n\nWithout it, I'm afraid I'm left quite vulnerable to the oppressive Light that curses this land.\n\nThe Marquis controls a coveted shaded hideout nearby. Will you avenge my parasol and teach this ruffian some manners?", objectives = "" }
WordHunterWoW_QuestEN[57427] = { title = "Unbearable Light", description = "Have you encountered an ash ghoul yet? Wretches crawling on the ground. Jump on everything. Terrible table manners.\n\nThat is the unfortunate fate awaiting all venthyr exposed to the Light for too long. The overwhelming pain it causes us breaks our willpower, our mind, and finally our body.\n\nWith the right skills, it is possible to reverse the Light's desecration if it is treated quickly.\n\nBut the ash ghouls in this Light-burned crater are beyond redemption. There is only one mercy left.", objectives = "" }
WordHunterWoW_QuestEN[57428] = { title = "Theotar's Mission", description = "Oh the Accuser sent you? How keen!\n\nI do, in fact, know the fate of Prince Renathal... at least part of it.\n\nWhen our assault on the Master's keep failed, we were both captured. I was banished to the Ember Ward, but the Prince was dragged off to Sinfall.\n\nI'm cultivating an escape from this Light-blighted land to follow after him, but the Light here... it makes it hard to think.\n\nMy parasol once protected me, but the ruffians destroyed it. Help me rebuild it, and we'll find the Prince together.", objectives = "" }
WordHunterWoW_QuestEN[57442] = { title = "Lost in the Desiccation", description = "<Exposure to the Light has rendered Theotar incapable of forming coherent sentences.\n\nInstead of telling you how to get to his hideout, he mumbles incoherently while pointing in random directions.>\n\nLost... Syb... Tubbins... Late for tea...\n\n<You'll have to find Theotar's hideout a different way.>", objectives = "" }
WordHunterWoW_QuestEN[57444] = { title = "An Inspired Moral Inventory", description = "{name}! You are well! I am glad of it.\n\nMany of the ascended who once served this place have betrayed us. To turn so wholly against all that the kyrian stand for is... unimaginable.\n\n<The acolyte places a heavy spear in your hands.>\n\nThis is a tool that has seen little use before today. Its sole purpose is to inspire a moment of reflection in those it touches. It will show them the error of their ways.\n\nIf they remain unrepentant, then there is no hope for them. They must die.", objectives = "" }
WordHunterWoW_QuestEN[57446] = { title = "The Enemy You Know", description = "My heart is filled with dread. If it truly is Lysonia who leads them now...\n\nNo. What is important is that we restore the great vespers. So long as their mighty voices are corrupted, all who hear them will suffer as this temple does. It is only a matter of time before all of Bastion succumbs.\n\nThey will no doubt try to stop you. I will hold their leader's attention as long as I can.\n\nIf I do not survive... my disciple will see you safely from this place. Go in service.", objectives = "" }
WordHunterWoW_QuestEN[57447] = { title = "Purity's Prerogative", description = "Do you feel it, {name}?\n\nThat cold hand that grips your throat? That chill settled in the pit of your stomach? That is the touch of the Maw, as certain as the Archon's will.\n\nI do not know how Lysonia came to possess this power, but we must act quickly.\n\nI will inform the Archon of what transpired here. You will act where my Hand could not. I will explain as we fly.\n\nSpeak to me when you are prepared to leave the temple.", objectives = "" }
WordHunterWoW_QuestEN[57448] = { title = "New Allies Among Us", description = "Even in times of peace, the Horde is not without its problems.   \n\nAlthough they can be overwhelming at times, our struggles should never stop us from remembering what it means to be a part of the Horde. \n\nWe don't turn people away when times get tough; we band together and endure. \n\nFor a moment I forgot this. Burdened by the troubles facing our new allies, I hastily dismissed the vulpera. \n\nMy only hope is that they still see as much value in the Horde as I see in them.", objectives = "" }
WordHunterWoW_QuestEN[57454] = { title = "Silence in the Stalks", description = "Hmm. Well that's not... great. But no cause for alarm, yet!\n\nIt has been a long time since our ring withdrew from here, and we probably need to go to its source to get it to return!\n\nUnfortunately, I haven't heard from the Chief Mushroomancer, Cortinarius, since the crisis began.\n\nPlease, find him and help us rejoin the rings! Head west of Dreamsong Fenn to the Stalks. You can't miss them... just follow the mushrooms!", objectives = "" }
WordHunterWoW_QuestEN[57455] = { title = "Mushroom For Improvement", description = "The mushrooms are under attack! I need your help, or we risk losing it all!\n\nSome fae wearing strange masks came in and demanded to gain access to the rings. When I told them they were closed due to the drought, they attacked me!\n\nI'm too weak to fight back now, and I'm cut off from the center ring. These fae have destroyed so much, but there is something we can do.\n\nSprinkle some of these spores on their corpses so we can regrow the rings. Even when slain, our enemies can still serve Ardenweald.", objectives = "" }
WordHunterWoW_QuestEN[57457] = { title = "Shaking 'Shrooms", description = "The mushrooms in there need your help, {class}!\n\nSome of the larger mushrooms become laden with spores. It is one of my duties to help disperse them and grow the grove, but it is too dangerous for me in there.\n\nIf you're going to go in, do you mind giving any particularly full mushrooms a good shake for me? That should get most of the spores loose until we can secure the grove.", objectives = "" }
WordHunterWoW_QuestEN[57458] = { title = "Ring Repairs", description = "The damage wrought here is severe, but it can be reversed.\n\nMy master is weakened by all this destruction, but mushrooms are difficult to completely eradicate. By restoring power to the rings throughout the grove, we can strengthen them once again.\n\nTake this beacon. Use it near a damaged mushroom in a ring, and watch how quickly nature can heal its wounds.", objectives = "" }
WordHunterWoW_QuestEN[57459] = { title = "Fighting For Fungus", description = "Behold, Marasmius!\n\nThis is his home, his heart. Every mushroom in Ardenweald, maybe even all of the Shadowlands, stems from here. And the masked fae want to take him for their own purposes. As chief mushroomancer, I cannot abide this.\n\nOur foes may look mindless, but they are clever. They will have tracked my position by now.\n\nI shall make my final stand here, and hope that Marasmius is strong enough to lend his aid.\n\nWill you stand with me, {class}?", objectives = "" }
WordHunterWoW_QuestEN[57460] = { title = "Tubbins's Tea", description = "Theotar teach Tubbins special tea that make Light go away!\n\nTubbins good tea maker!\n\nWatch Tubbins make Theotar feel good!\n\nThen Tubbins feel good!", objectives = "" }
WordHunterWoW_QuestEN[57461] = { title = "An Uneventful Stroll", description = "I hope I wasn't too unpleasant while under the Light's influence. I do try to restrain myself, but the pain it causes is... maddening.\n\nAnyway, that tea picked me right up!\n\nWhen I last saw Prince Renathal, the Master was dragging him off to that big tower looming over the Ember Ward.\n\nMyself and a few others have been working to gain access to that tower from below, but there are... obstacles.\n\nWhen you're ready to depart, I will lead you to our headquarters of sorts, the Sanctuary of the Mad.", objectives = "" }
WordHunterWoW_QuestEN[57462] = { title = "Dream Catcher", description = "It appears that the focus remains stable, and its containment field remains intact. I daresay we can empower it even further.\n\nHunt down and defeat formidable enemies to acquire additional remnants of N'Zoth's influence. This time, we will infuse the focus with even greater amounts of the Old God's power. I am confident that the containment field will continue to hold.", objectives = "" }
WordHunterWoW_QuestEN[57463] = { title = "My Way or the Hyphae", description = "<An old, booming voice fills your mind.>\n\nHmph. More are coming.\n\nI would rather not lose more of myself, and I don't want you to think I'm not appreciative of the work you and Cort here have done.\n\nHow about you take a ride on the rings and give those oafs a good thrashing? We'll teach them not to mess with Marasmius and his fae rings!", objectives = "" }
WordHunterWoW_QuestEN[57464] = { title = "Maintaining Focus", description = "At present, the focus holds but a fraction of N'Zoth's true power. If we further empower it, we could craft even more effective weapons to wield against him.\n\nN'Zoth's influence is everywhere, {name}, and is most concentrated within powerful foes. Vanquish them and claim whatever vestiges of the Old God's power remain.", objectives = "" }
WordHunterWoW_QuestEN[57466] = { title = "[REUSE]", description = "I like you, youngling. You are not like the others, sitting in their fancy court, leaving old Marasmius to keep the network running.\n\nI'll open up the ring by the celestial tree nearby as a thank for all your help. You can use it to come back and visit me whenever you like.\n\nYou come back now! There will always be plenty for you to do here. Might even be something special in it for you.", objectives = "" }
WordHunterWoW_QuestEN[57470] = { title = "An Abominable Discovery", description = "{name}. Come with me. I could explain, but it's easier to understand if you see it for yourself.", objectives = "" }
WordHunterWoW_QuestEN[57471] = { title = "It's a Dirty Job", description = "This muck pool is all out of order. The anima shortage has taken its toll here for sure. \n\nYou see, the pools require filth and fiber to grow dredgers effectively. The problem is every time I try to treat the pool, the dang devourers are on my back!\n\nNow the untreated muck is starting to coagulate into these elementals! Can you go and toss some of the filthy rubble into the pool to restore it?", objectives = "" }
WordHunterWoW_QuestEN[57473] = { title = "Prized Possession", description = "This chest is different. It's larger than the others... but more importantly, it's locked.\n\n<Mograine bashes the lock apart.>\n\nNow, let's see what's inside.", objectives = "" }
WordHunterWoW_QuestEN[57474] = { title = "Dredger Duty", description = "You fixed up the muck pool so we can make some dredgers, but them devourers are gonna keep causin' trouble.\n\nWe're gonna need a Gem of Binding so we can dredge up a biggun to protect the pool.\n\nI'll show you how to dredge up some disposable dredgers to work with for now.\n\nGet 'em digging in the rubble to find us a Gem of Binding, and then we'll reshape 'em all into a biggun to kick them devourers outta here!", objectives = "" }
WordHunterWoW_QuestEN[57475] = { title = "The Mantle Returned", description = "The Mantle of the Primus...\n\nI can hardly believe it. That Gharmal possessed it. That they did not use it against us. That we reclaimed it.\n\nThis could prove vital toward our efforts to restore Maldraxxus. We must return it to Baroness Draka at the Seat of the Primus immediately.", objectives = "" }
WordHunterWoW_QuestEN[57477] = { title = "We're Gonna Need a Bigger Dredger", description = "Thanks for getting the stone, {name}. While you were out I went ahead and dredged up a few more folks.\n\nNow we just need to re-shape these dredgers into a biggun.", objectives = "" }
WordHunterWoW_QuestEN[57481] = { title = "Running a Muck", description = "Bootus ready to smash devourer skulls.\n\nHop on.", objectives = "" }
WordHunterWoW_QuestEN[57486] = { title = "Waning Energy", description = "Mekkatorque's pod is powering down. \n\nWe are no longer able to hear him speak. \n\nHis pulse has slowed, in spite of the best efforts of Kul Tiran healers.\n\nI have an idea, but I am going to need your help.\n\nMeet me at Proudmoore Keep. We must go soon.", objectives = "" }
WordHunterWoW_QuestEN[57487] = { title = "Someone Who Can Help", description = "I believe there is a way to help Mekkatorque, but some may not be a hundred percent on board... \n\nThe mechagnomes have advanced techniques in biomechanical repair and improvements.\n\nIf there is even a chance they can help him, we have to try! There are some mechagnomes sending supplies out to the island from a dock in Hook Point. No one will notice one more piece of cargo. We need to reroute one of their homing copters.\n\nWill you please help me get Mekkatorque's Pod to Mechagon?", objectives = "" }
WordHunterWoW_QuestEN[57488] = { title = "The Current Schematic", description = "I think I can modify one of our existing devices to give us access to Gelbin Mekkatorque without disturbing his life preserving functions.\n\nThere are some items I will need you to procure. \n\nFrom the nearby vector of the Heaps, you will find scrapbots and scraphounds. These would be a fine source of spare parts for my construction project.\n\nThe Outflow is home to some particularly slimy friends. From them, you will find excellent ingredients for the heat resistant lubricant we need.", objectives = "" }
WordHunterWoW_QuestEN[57490] = { title = "Voyage to Safety", description = "One of our defenders saw the troggs take out the homing copter carrying Mekkatorque's pod. \n\nSince we started bringing goods in from Tiragarde, they have been a real thorn in our side. \n\nPiston, a very promising young inventor, has a vehicle able to handle this task. Meet his crew down in Bondo's yard.\n\nPlease hurry and retrieve the pod! I am not sure what will happen to Gelbin, if they break it open.\n\nAhem, we would not be upset if you did a little beach clean-up while you were there...", objectives = "" }
WordHunterWoW_QuestEN[57491] = { title = "Better... Stronger... Less Dead", description = "King Mechagon may have been crazy, but his minions did have exemplary robotic creation capabilities. \n\nThere are a few residual creations wandering Mechagon. Refusing to accept King Mechagon's dethroning.\n\nThe logical conclusion to defeat is withdrawal, if one remains operational. Some do not excel at logic.\n\nThey currently bear the latest in technical advancement. I believe retrieving specific pieces from these units would greatly benefit our recovery endeavor.", objectives = "" }
WordHunterWoW_QuestEN[57492] = { title = "Him?", description = "Speak to some of the gnomes in Mechagon, enhanced or otherwise. Of my people, ask what they hope for in a leader of our kind. Of our new friends, ask what they appreciate most about their current leader.\n\nFrom what I have learned thus far, the High Tinker has always led his people by necessity, he never sought or desired the crown. I believe the gnomes should be united once again. \n\nI seek a solution that will be most amenable to all. Will you gather the information I need?", objectives = "" }
WordHunterWoW_QuestEN[57493] = { title = "Mental Attunement", description = "We now have a baseline of who Mekkatorque is, looks like there could be some room for improvement. \n\nYour assistance is needed to get him stabilized and synchronized before removing him from his pod.\n\nPlease position yourself by the Synchroscope. I will make adjustments, you will need to fire the machine when I call.", objectives = "" }
WordHunterWoW_QuestEN[57494] = { title = "A Strong Heart", description = "We saw a flare near Junkwatt Depot. \n\nThe retrieval team has made it out with the power source. We are now forever safe from King Mechagon's Annihilo-tron, its heart will serve a new purpose.\n\nThis is great news!\n\nHowever, the flare means they have company. Your help will be needed to extricate the team and retrieve the Spark Reactor.\n\nPlease move with haste, we are so close to completion.", objectives = "" }
WordHunterWoW_QuestEN[57495] = { title = "The Future of Mechagon", description = "Now that Mechagon City has been cleared of its remaining dangers, it may once again be a place of peace and prosperity for gnomes and mechagnomes alike.\n\nIt is time for me to speak with Prince Erazmin regarding the future of our peoples. It is my sincere hope that we will forge an alliance that will last for generations to come!\n\nWhen you are ready, please join us at the High Tinkertory for a special address.", objectives = "" }
WordHunterWoW_QuestEN[57496] = { title = "Ascension", description = "After everything the mechagnomes have done for us today, it is our duty to return the favor.\n\nLet us clear out the rogue creations that remain in Mechagon. \n\nWith their home returned, Prince Erazmin and his people will have a brilliant path forward.\n\nWith this team, we will make short work of the remaining King Mechagon loyalists.\n\nLet me know when you are ready to roll out!", objectives = "" }
WordHunterWoW_QuestEN[57497] = { title = "Propagate the News", description = "We wanted to save a life and we have accomplished so much more!\n\nWe really couldn't have done it without you, {name}. I am so excited about the future of all gnomekind.\n\nHead back to Stormwind and share the good news!", objectives = "" }
WordHunterWoW_QuestEN[57506] = { title = "Light Lost", description = "Some of our aspirants foolishly believed they could enter the Maw and make a difference in that dark abyss.\n\nSadly, they are mistaken. To enter the Maw is to invite eternal damnation.\n\nBut not for you.\n\nPlease investigate their fate. If you can find them, their souls might once again be free.", objectives = "" }
WordHunterWoW_QuestEN[57511] = { title = "Arms for the Poor", description = "This trench is strewn with the remnants of countless attacks upon the Seat of the Primus by forces which threatened the Shadowlands.\n\nEach time, Maldraxxus claimed victory.\n\nNow scavengers pick at scraps in hopes of buying their way into one of the three remaining houses. In these desperate times, we must gain every advantage possible over our rivals.\n\nIf we arm these scavengers and offer them a second chance at glory, we can bolster the ranks of the Chosen.", objectives = "" }
WordHunterWoW_QuestEN[57512] = { title = "Walk Among Death", description = "This trench echoes with necromantic energies unleashed in the countless battles waged here. That power has coalesced into chaotic entities we call deathwalkers.\n\nIn simpler times, we would have sent troops out to subdue them to serve the House of the Chosen. But with war brewing, there is no time for that.\n\nEliminate this potential threat, before our enemies turn them against us.", objectives = "" }
WordHunterWoW_QuestEN[57513] = { title = "Enemy of My Enemy", description = "I have no doubt you have questions. Know that we share enemies in this land.\n\nFor now, we must move. I will get you to a safer location and then we can speak.", objectives = "" }
WordHunterWoW_QuestEN[57514] = { title = "The First Act of War", description = "Look around you, {name}. This army is all that remains to defy the treachery of the other two houses.\n\nI must regroup with the margrave and discuss strategy. War will soon be upon us.\n\nI would ask that you prepare for the coming battle alongside the rest of our forces. We cannot afford for a single soldier to falter.\n\nSeek out Baron Vyraz. He has earned countless victories for Maldraxxus. I fear his blades must soon be turned upon our former allies.", objectives = "" }
WordHunterWoW_QuestEN[57515] = { title = "The House of the Chosen", description = "<Draka gestures to the sky.>\n\nLook there, mortal. That is the necropolis of Margrave Krexus, who leads the House of the Chosen. It is my honor to serve as his baroness.\n\nLet us ride to our fortress. There we can gather our strength and make ready for the battle to come.", objectives = "" }
WordHunterWoW_QuestEN[57516] = { title = "Through the Fire and Flames", description = "Margrave Krexus was pleased to hear of your service to our house. He senses great potential within you.\n\nPotential that must be tested.\n\nA stone stands at the center of our citadel, surrounded by magma. Reaching the stone is a challenge of endurance and fortitude.\n\nThis trial is usually attempted only by our most renowned soldiers, but Margrave Krexus commands you to attempt the rite at once.\n\nGo on, then. Prove your worth.", objectives = "" }
WordHunterWoW_QuestEN[57524] = { title = "Accessing the Archives", description = "The information you've gathered has allowed us to better understand these manifestations.\n\nI believe MOTHER is waiting to share some of her findings with you.", objectives = "" }
WordHunterWoW_QuestEN[57529] = { title = "Garden in Turmoil", description = "Please excuse me for not standing. I would rather not disturb these creatures.\n\nIf you have a desire to help the creatures of Bastion, Zosime needs aid to regain control of our garden. You will find her just down this path.\n\nGo in service.", objectives = "" }
WordHunterWoW_QuestEN[57530] = { title = "Gharmal's Tower", description = "Gharmal collected anything they believed to be an item of power.\n\nWe'll need to search the tower. There is almost certainly something here of value to us.", objectives = "" }
WordHunterWoW_QuestEN[57531] = { title = "An Unfortunate Situation", description = "Laurent, mirror maker to the Master. Pleasure to meet you. Excuse my disheveled appearance. It appears I've found myself in a most unfortunate situation.\n\nI was attempting to travel on royal business when my mirror sent me to this wasteland instead.\n\nNot a moment after I arrived, a band of exiles ripped the clothes right from my back, making it impossible for me to traverse this unforgiving terrain.\n\nAssist me and I will endeavor to create a mirror which will allow us to escape this wretched place.", objectives = "" }
WordHunterWoW_QuestEN[57532] = { title = "Foraging for Fragments", description = "Forgive me. I don't mean to appear ungrateful, but my mirror fragments are missing.\n\nI shouldn't be surprised, really. They're quite powerful and I'm sure the miscreants out here would be happy to get their hands on them.\n\nNonetheless, I will not let this deter me.\n\nThe Master sends his stone servants to smash any mirrors erected in this ward, so we should have no trouble finding fragments nearby.", objectives = "" }
WordHunterWoW_QuestEN[57533] = { title = "Light Punishment", description = "The reasons we were banished here differ, but our goal once we arrive is always the same--to avoid becoming ash.\n\nThe Shrouded control the areas shaded from Light. Those that trespass within their stronghold are made to suffer. Our flesh blisters and burns, yet we do not die. Instead, our minds descend into madness from the pain.\n\nI do not claim to know the crimes of those trapped within the Light, but I know this is not the Maw. It is not our role to punish.\n\nFree the others as you have freed me.", objectives = "" }
WordHunterWoW_QuestEN[57534] = { title = "When Only Ash Remains", description = "Is this really what becomes of the exiled? Are they left here to burn to ash?\n\nHow could the Master allow such a thing? It is cruel. Heartless, even.\n\nNo venthyr would want to continue on like this. \n\nYou must end their suffering.", objectives = "" }
WordHunterWoW_QuestEN[57535] = { title = "Escaping the Master", description = "Now more than ever I wish to escape this place, but I cannot go back to serve the Master. Not after seeing what goes on here.\n\nSimone and I are in agreement. With your assistance, I will craft a mirror that connects to a sanctuary controlled by the prince. We will leave this place and pledge our support to Renathal. \n\nBut first, I'll need fragments of glass. The Shrouded seem to have plenty, and the fewer they have to make traps, the better.", objectives = "" }
WordHunterWoW_QuestEN[57536] = { title = "Mirror Making, Not Breaking", description = "Denathrius does not allow mirrors to be erected within the ember ward. His stone servants shatter anything that so much as glints. \n\nI need you to remain vigilant as I make this mirror. I have no doubt that the Master's minions will try to stop us. \n\nAre you ready?", objectives = "" }
WordHunterWoW_QuestEN[57537] = { title = "Covering our Tracks", description = "I belong to the House of the Chosen. We have a stronghold to the south, it should be safe there.\n\nWe'll fly the rest of the way. Approach my flayedwing when you are prepared.", objectives = "" }
WordHunterWoW_QuestEN[57538] = { title = "Disturbing the Peace", description = "This anima drought isn't hard on just the kyrian. The wildlife of Bastion are suffering too!\n\nMany creatures are becoming aggressive and menacing, wyrms and cloudfeathers especially. They are hurting the other wildlife and long beyond saving.\n\nIf someone doesn't clear this garden of these starved creatures, we can no longer meditate here. And if we can no longer meditate, that will make the anima shortage even worse!", objectives = "" }
WordHunterWoW_QuestEN[57545] = { title = "Distractions for Kala", description = "When the animals became aggravated, we left in a hurry. However, all of Kala's toys are still inside the garden.\n\nSince you are going to be there, would you please collect them? Kala may be very large, but she is still young. She can be a bit of a troublemaker as well.\n\nHopefully the return of her toys will help keep her distracted.", objectives = "" }
WordHunterWoW_QuestEN[57547] = { title = "A Test of Courage", description = "I'm still new and haven't passed all of my Aspirant tests. But, I have an idea.\n\nThere is an artifact called Korinna's Allaying Crook. Korinna was a powerful Ascended who tamed the creatures of Bastion eons ago. Her staff has the power to prevent more creatures from succumbing to a savage, anima-starved state.\n\nHowever, the artifact is protected and only one with great courage can retrieve it. I bet you could, {name}.\n\nGo on ahead. The staff is in the reliquary to the north. I'll join you there shortly.", objectives = "" }
WordHunterWoW_QuestEN[57549] = { title = "In Agthia's Memory", description = "Greetings, mortal!\n\nAre you here to learn about the legacy of Agthia, Paragon of Courage?\n\nI welcome you to walk the grounds of this ancient battleground to learn of the battle that occurred here, and the heroic Paragon who saved all of Bastion and the Shadowlands.", objectives = "" }
WordHunterWoW_QuestEN[57551] = { title = "Agthia's Path", description = "Now that you have familiarized yourself with the events leading to the battle that took place here eons ago, it is time to experience it for yourself.\n\nRing the bell, take a deep breath, and walk in Agthia's steps.", objectives = "" }
WordHunterWoW_QuestEN[57552] = { title = "Warriors of the Void", description = "These Void invaders are wiping our forces from existence!\n\nMy disciples fall, returning their anima to the lands.\n\nIf we fail to drive them from our lands, more than kyrian will be lost. First Bastion, then the Shadowlands as a whole.", objectives = "" }
WordHunterWoW_QuestEN[57553] = { title = "On Wounded Wings", description = "I see my peers fall in pain, their wounds from the Void overtaking them.\n\nWe cannot allow ourselves, or each other, to give up hope.\n\nShare your anima with our wounded brothers and sisters. Help them stand tall for another fight!", objectives = "" }
WordHunterWoW_QuestEN[57554] = { title = "Wicked Gateways", description = "The forces of the Void are infinite.\n\nThey travel through the Great Beyond by creating portals, twisting gateways between our planes.\n\nQuickly, move to close these portals. Cripple the swell of their forces for as long as we can hold.", objectives = "" }
WordHunterWoW_QuestEN[57555] = { title = "Shadow's Fall", description = "Despite our efforts, the Void stands strong. All of the forces of Bastion fight, and fall one by one...\n\nThe Void cannot destroy us!\n\nThey are led by Tezulat the Annihilator, scourge of a thousand realms. This day, his reign of terror will end!", objectives = "" }
WordHunterWoW_QuestEN[57568] = { title = "Tough Love", description = "Heavens! Kala has flown off with Korinna's Allaying Crook!\n\nI saw her fly into her den to the west. I must warn you, she can become very protective when she's in there. Please be careful, but do not be afraid to give her some tough love. She is exceptionally resilient.\n\nHere, take her slobber ball. It's her favorite and may help to distract her.", objectives = "" }
WordHunterWoW_QuestEN[57571] = { title = "Moving Mirrors", description = "What sort of horrific trap is this? The Light is being reflected directly on her! \n\nSimone's a dear friend of mine! Free her from that thing, please!", objectives = "" }
WordHunterWoW_QuestEN[57583] = { title = "Through the Veil", description = "I like you, youngling. You put in the work while the others sit in their fancy court, leaving old Marasmius to keep the fae rings thriving.\n\nHere, take one of my spores back with you to the Heart of the Forest. Find somewhere nice and cozy for me to rest, will you?\n\nCome back and visit me whenever you like. Cort and I can keep an eye on things for now, but there will always be plenty for you to do here. Might even be something special in it for you.", objectives = "" }
WordHunterWoW_QuestEN[57584] = { title = "A Fate Most Noble", description = "Welcome, Worthy One!\n\nI am Greeter Mnemis. It is my duty and pleasure to assist you on this, your first day among the kyrian.\n\nAllow me to congratulate you. Your fate is reserved for the most noble of souls. Only those who lived a life of service may call Bastion home.\n\nI am certain you have many questions- all new aspirants do! Please allow me the honor of introducing you to the next chapter of your existence.\n\nWe will begin when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[57634] = { title = "Bring Your Own", description = "Scunner, a roiling mass of flesh and slime, has crawled out of the ruins of the House of Plagues. \n\nHe emits a toxic vapor that impairs the functions of those who attempt to fight him. You can try it, Maw Walker, but it's doubtful you could hurt him on your own.\n\nConstructs are built to fight creatures like Scunner. So gather a force of them and eliminate the threat.", objectives = "" }
WordHunterWoW_QuestEN[57636] = { title = "Pride of Place", description = "The Mantle of the Primus. It belongs on his statue.\n\nYou were the one to recover it, so you will have the honor of returning it to its proper place.", objectives = "" }
WordHunterWoW_QuestEN[57637] = { title = "Disturbance Detected: Firelands", description = "You're early {name}, I hadn't even sent for you yet.\n\nAnother temporal disturbance has flared up, this time in the Firelands. If Ragnaros hadn't been dealt with when he was, well, you've already seen one way the end time could turn out.\n\nSome intricate time weaving is required to be sure you catch Ragnaros early, but still after whatever is causing the disturbance. Whoever is doing this isn't messing around any more.", objectives = "" }
WordHunterWoW_QuestEN[57638] = { title = "Korrak the Bloodrager", description = "The indigenous Winterax trolls of the region are ruthless savages that would love nothing more than to have our bones added to their foul stew.\n\nWe must show them our might!\n\nWe have recovered tomes from their caves that detail their leadership hierarchy. The artifacts indicate that their leader, Korrak the Bloodrager, tends to remain hidden until given a reason to make his presence known.\n\nDeath to Korrak would mean death to Winterax Clan! Slay him and return.", objectives = "" }
WordHunterWoW_QuestEN[57639] = { title = "The Legend of Korrak", description = "The invading Stormpike are not the only threat in the region, soldier. The war in the Valley is waged on two fronts. The cannibal Winterax trolls also vie for power.\n\nThey are lead by Korrak the Bloodrager - a cruel and cunning beast.\n\nA strike against Korrak could prove to be a crushing blow to the Winterax clan. Slay the beast and be rewarded!", objectives = "" }
WordHunterWoW_QuestEN[57642] = { title = "A Winter Veil Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[57643] = { title = "A Gently Shaken Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[57644] = { title = "No Friend Left Behind", description = "I would care for nothing more than to serve as navigator again, but my dearest friend suffers. I cannot stand to abandon him.\n\nI can feel Twigin now. He struggles against the binding web of the spiders who once served us. More victims of this senseless conflict...\n\nThough it pains me to say it, you must slay our spiders and gather their caustic venom. You can then use it to free Twigin.\n\nIf not out of empathy, rescue him for the sake of your plans. My skills will be useless without his direction.", objectives = "" }
WordHunterWoW_QuestEN[57646] = { title = "The Tithelord", description = "With his army defeated, the Tithelord is vulnerable. Now, he has but a small contingent to protect him. Let us strike him down decisively. \n\nHe draws power from these anima wells, keeping it all for himself. If you can hold his attention, I can not only empower you to defeat him but also disable the wells.\n\nSpeak to me when you are ready to begin. When the time is right, the baroness will lead our new recruits into battle.", objectives = "" }
WordHunterWoW_QuestEN[57648] = { title = "The Impossible Plan", description = "Everything is in place for us to seize a necropolis. I will coordinate our efforts and meet you at the Seat of the Primus. \n\nDraka will undoubtedly commend you on your success. I, however, will do so once our mission is complete.", objectives = "" }
WordHunterWoW_QuestEN[57649] = { title = "Whisper of Hope", description = "Akarek's demise has cast a dark shadow upon our house... but it is in the shadows where we thrive.\n\nI know that not all the Eyes have perished. They could lie in wait, hidden for eternity, if such was demanded of them.\n\nBut it is time to reclaim our destiny. Take my sigil through the wreckage and awaken any Eyes who remain.\n\nWe will seize our victory.", objectives = "" }
WordHunterWoW_QuestEN[57651] = { title = "Trouble in the Banks", description = "Ah, be welcome in my glade, Maw Walker. You are safe here.\n\nWhile it is regrettable that Sorcha must wait for her weapons, it is of paramount importance that I keep my charges safe. I will do anything to prevent them from suffering as the rest of Ardenweald.\n\nPerhaps I could ask a small favor of you. I have not heard from the gatherers at the Banks of Life in some time. Would you mind checking on them to make sure they are well? I would go myself, but I must deal with Sorcha. Seek out Foreman Thorodir.", objectives = "" }
WordHunterWoW_QuestEN[57652] = { title = "Supplies Needed: Amber Grease", description = "Foreman,\n\nOur supply of gris is running low. You know as well as I do that there is no end to Glitterfall Basin's need of it.\n\nI've overheard from some of the other workers that you have a bit of a gorm problem. But the bigger the gorm, the bigger the gris, right?\n\nIf you happen to harvest some more, we can certainly put it to good use.\n\n<The work order is signed: \"Cavina.\">", objectives = "" }
WordHunterWoW_QuestEN[57653] = { title = "Unsafe Workplace", description = "You've returned just in time! Fae are in danger!\n\nIt seems our actions have enraged the gorm. They are even more aggressive than they were before!\n\nWhile some fae were able to evacuate, there are still many who are trapped down there.\n\nTake this jar and slather anyone you find with a generous helping. That should heal their wounds and give them a chance to escape.", objectives = "" }
WordHunterWoW_QuestEN[57655] = { title = "Supplies Needed: More Husks!", description = "I need more husks, Thorodir! The Lady herself wants to make sure we are outfitted with the finest armor.\n\nThey've been soaking in the waters long enough to be workable. Find some time to retrieve them before our hunters find themselves without adequate protection.\n\n<The work order is signed: \"Cavina.\">", objectives = "" }
WordHunterWoW_QuestEN[57656] = { title = "Gifts of the Forest", description = "These gorm have gone out of control! We need to stop them.\n\nI have a plan, but I cannot do it on my own. We lure the gormlings to the Banks of Life by using special totems that are drained of their anima. If you can retrieve the wood required for the totem, I can prepare the ritual.\n\nTake these pipes. Find the Culex trees growing on the banks and play a song for them. You will recognize them by their pale green leaves. The wood must be given freely for the ritual to work.", objectives = "" }
WordHunterWoW_QuestEN[57657] = { title = "Tied Totem Toter", description = "Hope you've caught your breath.\n\nThe totem is now a big, tasty beacon to all the nearby gorm. They're going to want to eat it and you're going to be carrying it!\n\nWe need to rehome the smaller ones. If they stay here they're just going to get big and angry again. If you can drop off a few groups of them outside the Banks of Life we can make sure they find their way to more balanced feeding grounds.\n\nLet Thorodir know when you're done. I will let him know the plan.", objectives = "" }
WordHunterWoW_QuestEN[57658] = { title = "The Final Leg", description = "Please, I must get to Glitterfall Basin.\n\nI thought I was being careful. I did not realize I was being hunted until it was too late. Such is the nature of the forest.\n\nI am too close to fall here. The Lady herself invited me to come join her. She said I would be safe.\n\nCan you take me to her?", objectives = "" }
WordHunterWoW_QuestEN[57659] = { title = "Bring Your Friends!", description = "This is only the beginning, friend.\n\nI must thank you again for rescuing me. Now that we have found a safe route, I am but the first of many. Druids from all around Ardenweald have heard of the safety of this glade, and I wish to bring them all here.\n\nI have known Roriel for most of my time in this place. She is a capable healer, despite her appearance. She would be a fine addition to this place.\n\nShe was last seen near Tirna Fein to the west. Please let her know the way is clear.", objectives = "" }
WordHunterWoW_QuestEN[57660] = { title = "The Grove of Creation", description = "I probably would have been digested if not for you. And while that sounds like a fascinating phenomenon, I am glad I did not experience it... firsthand.\n\nYou have a knack for solving problems and you're not afraid to get your hands dirty with our tools. Might I suggest paying a visit to Glitterfall Basin, to the west? It is home to our finest minds and workshops, and I am sure they could use your help in this drought.\n\nThe Lady of the Falls is droman there. She will know where you can best help!", objectives = "" }
WordHunterWoW_QuestEN[57661] = { title = "Silk Shortage", description = "We are running short on silk! We use it for so many things, like instruments, weapons, and tools. But our supply has dried up!\n\nWe are in desperate need for fresh silk.\n\nOur main hub of silk production is in the Gossamer Cliffs. If you could, seek out Caretaker Lillythistle, and see what the holdup is!", objectives = "" }
WordHunterWoW_QuestEN[57663] = { title = "Blackthorn Blackout", description = "I don't know what caused the Blackthorn to attack, but I can't allow them to just come in here and take over my operation. Think you could help me out? I'll give you a little something for your trouble.\n\nThe Blackthorn Droman has three powerful witches that serve as his enforcers. Take them out and you'll send the tribe into disarray. \n\nOf course, this could just get their leader to show up and make an already bad situation even worse but I'm willing to risk it.", objectives = "" }
WordHunterWoW_QuestEN[57670] = { title = "Unbeelievable Quality", description = "<Now that your harvester has matured, the Honeyback hive is creating additional honey.\n\nSomeone in Brennadam could certainly find a use for this honey.>", objectives = "" }
WordHunterWoW_QuestEN[57676] = { title = "The Things That Haunt Us", description = "As you will soon learn, a ritual cleansing can be a... painful process.\n\nIn most cases, the upwelling of emotion is harmless. It can even generate anima under the right circumstances.\n\nHowever... sometimes the result is far less pleasant. Negative memories can take a form of their own and manifest in a violent fashion.\n\nI fear Pelagos' attempt at cleansing has brought forth such monsters. You must destroy them, and quickly.", objectives = "" }
WordHunterWoW_QuestEN[57677] = { title = "A Soulbind In Need", description = "Pelagos is my Soulbind. He is my brother, my closest friend, my mentor, and my student. He knows me completely, and I him. It is a bond stronger than any other.\n\nThat he now struggles is a torment to me, but I am forbidden from intervening. An aspirant must succeed or fail on their own merits, or the trial is forfeit.\n\nI am bound by this law... but you are not.\n\nPlease bring Pelagos back to me. This will not be his last trial. Not when he may finally have a chance.", objectives = "" }
WordHunterWoW_QuestEN[57686] = { title = "The Eternal Traveler", description = "Hail, mortal.\n\nFor untold ages, my kind has traversed the myriad realms of reality. We have beheld phenomena that you cannot begin to comprehend. But there is much you must learn of what awaits you on the horizon.\n\nThe power of Death is on the rise. The veil weakens between your world and the Shadowlands.\n\nWhen a mortal life expires, an echo of it remains behind. The most powerful mortals leave the most resonant echoes.\n\nBring these to me, that I might study them... to both our benefits.", objectives = "" }
WordHunterWoW_QuestEN[57689] = { title = "Prince Renathal", description = "You! They say you are a Maw Walker. Well, time to put that to the test.\n\nMy master, Prince Renathal, was the one who started the rebellion. He knew Denathrius was working towards something truly nefarious, and attempted to stop him.\n\nThe rebellion failed, and Renathal was flung into the Maw.\n\nI propose you and I venture into the Maw. There is an old device here that only you will be able to use. Together, we can recover my Prince. You need him, if you are to have any hope of success.", objectives = "" }
WordHunterWoW_QuestEN[57690] = { title = "Cages For All Occasions", description = "Okay, do not lose focus. I can feel Renathal's presence. It is faint but I can sense he is outside of the tower, at least.\n\nCome, let's find him and get out of here.", objectives = "" }
WordHunterWoW_QuestEN[57691] = { title = "A Royal Key", description = "I am not about to question whatever twist of fate led you to me. Your timing could not be better.\n\nThis cage was custom built to contain me. There is one key, and of course it is on the armor of that large brute over there.\n\nVanquish him and take the key. Be swift, the Jailer's eyes are always on this area.", objectives = "" }
WordHunterWoW_QuestEN[57692] = { title = "Prisoner Transfers", description = "While I appreciate the rescue, I am not the only one we must recover. When I was cast in to the Maw, those most loyal to me were also condemned to this place.\n\nUntil recently they were in this camp. I do not know where they were taken but I am sure one of these denizens has a scroll elaborating on their location. The Jailer's forces are nothing if not thorough in their organizational skills.\n\nCan you find the transfer orders?", objectives = "" }
WordHunterWoW_QuestEN[57693] = { title = "Torghast, Tower of the Damned", description = "My allies were taken into the Tower of the Damned, and so we must follow.\n\nI do not think we must venture deep into those halls, which is good as I do not believe either of us is in shape for a fight like that.\n\nCome, let us find our way to one of the most dangerous towers in all of existence.", objectives = "" }
WordHunterWoW_QuestEN[57694] = { title = "Refuge of Revendreth", description = "Sinfall is more than a ruin. It was once a place of dark magic and experimentation.\n\nWhen the Light retaliated and scorched the Ember Ward, the walls of this place stood. It is fortified, supplied, and filled with secrets. A perfect staging ground for our upcoming conflict.\n\nBut first, take me to meet these allies who led you to Vorpalia. We must take stock of what resources we have to work with.", objectives = "" }
WordHunterWoW_QuestEN[57709] = { title = "The Aspirant's Crucible", description = "I have given Kalisthene's words some thought.\n\nIf you are to learn our ways, we should proceed as if you were an aspirant yourself. The next step is to journey through the Aspirant's Crucible.\n\nIt is a place of reflection, training, and cleansing. For an aspirant, it is where they prepare for the long journey ahead. For you... I hope you will learn how you might help us in this time of crisis.\n\nWord of your arrival has likely spread. We will not keep them waiting.\n\nTake my steed, and go in service.", objectives = "" }
WordHunterWoW_QuestEN[57710] = { title = "A Life of Service", description = "Curious. You are unlike any aspirant that has come before, that much is certain.\n\nYou will notice that we have an audience. It has been a long time indeed since we welcomed another to the path. We are all eager to see what deeds brought you to us.\n\nSimply approach the dais before you and gaze into the flame. The Watcher will pull forth your memories of those you served in life, and you will be transported back to those moments to aid them once more.", objectives = "" }
WordHunterWoW_QuestEN[57711] = { title = "A Forge Gone Cold", description = "I have seen firsthand that you are a most capable soul.\n\nKleia has told me of your purpose here. She has spoken of the hopes she places in you. I am not yet certain if I am ready to do the same.\n\nThere is one small task that I would set before you, however. My forge has grown cold without anima to keep it burning bright. I long to practice my craft again.\n\nMy helper, whom you have met before, can elaborate on our needs.\n\nYou will find Sika near the forge. I will follow shortly.", objectives = "" }
WordHunterWoW_QuestEN[57712] = { title = "Suggested Reading", description = "Greetings. You must be the new aspirant everyone is talking about.\n\nI thought you might like to learn more about us. There are three tomes that would serve you well as a starting point, but they are not currently in the library.\n\nAspirant Leda was the last to hold \"Worlds Beyond Counting.\" Aspirant Ikaran has yet to return \"The Infinite Treatises.\"\n\nIt seems \"Bear Witness: The Watcher's Code\" went missing some time ago. I would search the village.\n\nOnce returned, you can read them at your leisure.", objectives = "" }
WordHunterWoW_QuestEN[57713] = { title = "The Work of One's Hands", description = "Too long have my hands been idle!\n\n<Forgelite Sophone smiles warmly at you.>\n\nYou cannot know what this means to me, but I might be able to show you. For your aid in restoring my forge, please allow me to craft you a piece of armor.\n\nIt will not be an extravagant affair, but through good works we grow to know ourselves better.\n\nI will need your aid once more. Sika and I will guide you on the specifics. All you need to do is listen and do as instructed.\n\nWhat do you say?", objectives = "" }
WordHunterWoW_QuestEN[57714] = { title = "Assessing Your Spirit", description = "It is clear to all that you are indeed a skilled combatant.\n\nThere is one challenge here that continues to test even the strongest among us. I would have you attempt to best a well-known centurion, beloved by all aspirants. It is called Athanos.\n\nConsider this a test of your spirit.\n\nIf you can withstand this trial, then I will deem you ready for what lies ahead.", objectives = "" }
WordHunterWoW_QuestEN[57715] = { title = "The Archon's Answer", description = "Your cleansing is complete, and you are whole.\n\nOur plan was a success. Undergoing such a rite, so soon after your arrival, has attracted Kalisthene's attention once more. \n\nNow is our opportunity to request an audience with the Archon.\n\nStand before her and be proud of what you have accomplished. No matter what happens now, you have done all that any aspirant could hope to.", objectives = "" }
WordHunterWoW_QuestEN[57716] = { title = "A Wayward Disciple?", description = "While you are here and as yet unaffected by this--rash of doubt, we shall call it--there is one other errand I would ask of you.\n\nI sent one of the disciples to investigate reports of the fallen fleeing our temple. For their own safety, they must be taken to the Temple of Loyalty.\n\nDisciple Nikolon has yet to return. If he is to be found nearby, it will be near the border of our temple to the north.\n\nPlease, seek him out and ensure that he is not injured or in peril.", objectives = "" }
WordHunterWoW_QuestEN[57717] = { title = "Step Back From That Ledge, My Friend", description = "This disciple... such emotion...\n\n<Eridia stares at Nikolon for a long moment.>\n\nRarely do ascended require such rigorous cleansing, but I cannot deny what is readily apparent. This disciple will fall if I do not intervene.\n\nThere is no time to lose. Come. I will instruct you.\n\n... I only hope we are not too late.", objectives = "" }
WordHunterWoW_QuestEN[57718] = { title = "Bound in Stone", description = "Some of our warriors were camped in the small settlement near Guo-Lai when the Baruk invaded the area. Some managed to escape, but they returned with tales of their brothers and sisters in arms being petrified by the mogu stoneshapers into living statues!\n\nWe can't leave our warriors behind! \n\nThe stoneshapers must carry some means to reverse the spell and free them from their stone prisons. Bring our soldiers back!", objectives = "" }
WordHunterWoW_QuestEN[57719] = { title = "Dangerous Discourse", description = "<The scroll's runes shift and change as you attempt to read it. At first glance, it appears illegible.\n\nSimilar scrolls have appeared all over the Temple of Purity.\n\nEridia will be interested in these.>", objectives = "" }
WordHunterWoW_QuestEN[57720] = { title = "Champions of the Mogu", description = "These lesser clans warring with each other in the Vale need to be taught their place.\n\nSeek out their champions and eliminate them. Show them that only the Rajani have rightful claim here!", objectives = "" }
WordHunterWoW_QuestEN[57721] = { title = "Spoils of War", description = "The warring clans are relentless and our warriors are going through armor faster than I can keep it repaired.\n\nIf you find yourself in battle with the other clans, see if you can salvage any undamaged armor pieces from their soldiers. We should not let good resources go to waste.", objectives = "" }
WordHunterWoW_QuestEN[57724] = { title = "Securing Sinfall", description = "They're all still active...\n\nThe stoneborn, the gargon, the stone fiends... All of 'em!\n\nDon't got much time. They're always watching.\n\n<Breakfist points up.>\n\nVulca told me to follow that big beam of Light in the sky.\n\nGoes to a tower guarded by a big old brute, though. Couldn't get in.", objectives = "" }
WordHunterWoW_QuestEN[57727] = { title = "Stonevigil Unrest", description = "Greetings, {name}. I'm sure you've met my associate, Baroness Draka.\n\nI have recruited her to help us with the growing threat of the Tithelord.  His involvement with the Maldraxxi renegades is troubling.\n\nOne conspiracy begets another. So I recruited Draka to help us end it.\n\nWe must not treat this situation lightly. We first need to put an end to his oppression of Stonevigil Overlook. That way we can we win over the hearts and minds of his subjects.", objectives = "" }
WordHunterWoW_QuestEN[57729] = { title = "To the Estate", description = "A window of opportunity has presented itself to us, {name}.\n\nWith his supply line cut off, Vartox dead, and people turned against him, the Tithelord should be no match for us. However, I must admit I do fear what tools he may have acquired from his Maldraxxi cohorts.\n\nHis base of operations is just down the road: the Caretaker's Manor, named for the Harvester whom he replaced.\n\nWe will meet you there.", objectives = "" }
WordHunterWoW_QuestEN[57733] = { title = "Pocketfuls of Silk", description = "The Blackthorn are stealing all of our silk stores. Without that silk it's going to be impossible for us to build any more aether extractors!\n\nSuffice to say, we're going to need to get that silk back!", objectives = "" }
WordHunterWoW_QuestEN[57737] = { title = "Ramkahen Rescue", description = "Mar'at was overrun by those foul K'thir before we could safely evacuate our citizens. \n\nI fear the worst has happened to them.\n\nPlease, if anyone is left alive within the city, tell them to come to Ramkahen.", objectives = "" }
WordHunterWoW_QuestEN[57766] = { title = "War with the Horde", description = "Good to see you've received proper training as a {class}.\n\nWe'll need it for what's next. The Alliance's war with the Horde has reached a fevered pitch... and we've lost a lot of good soldiers.\n\nKing Anduin is looking for aid in an operation to bolster our forces. I told him you'd be a good fit for the job.\n\nBefore you meet him, let me get get you caught up on what has been happening so far.", objectives = "" }
WordHunterWoW_QuestEN[57771] = { title = "An Unwelcome Incursion", description = "The Tithelord sent his stoneborn to further reap the anima from these citizens. How long has this been going on? These acts reek of unfathomable greed.\n\nThere is but one answer to this dilemma: to send a message. Crush these oppressors. Drain their anima and return it to Stonevigil's anima well.\n\nThe incursion will be dealt with and the downtrodden's spirits lifted. Two birds, one stone.\n\n<Draka hands you an anima container.>\n\nTake this. I stole it from one of the guards earlier.", objectives = "" }
WordHunterWoW_QuestEN[57772] = { title = "Fangs and Minds", description = "The denizens of Stonevigil have been wrung dry by the Tithelord's greed. \n\nWhile some have taken up arms against these injustices, most are too downtrodden to act. We need them on our side to take him down.\n\n<Prince Renathal hands you a heavy scroll dripping with anima.>\n\nGo, show them the hypocrisy of their oppressor! Send them to me with the promise of sanctuary.", objectives = "" }
WordHunterWoW_QuestEN[57773] = { title = "Close to Tears", description = "Our warriors have observed foul manifestations coming forth from numerous void tears within the surrounding jungle. \n\nThey have been but mere weaklings, clearly intended to test our defenses before the real forces arrive.\n\nIf we do not deal with this threat now, however, it will only be a matter of time until we are overrun by their fodder.\n\nFind a way to close those portals!", objectives = "" }
WordHunterWoW_QuestEN[57774] = { title = "Nine Lives", description = "Scouts have returned recently, nearly on the verge of death, with reports that I find... disconcerting.\n\nNeferset have been spotted wandering the streets of their city to the south.\n\nThis would normally be no cause for alarm, except the Neferset were completely wiped out.\n\nI must ask you to investigate further... and if by some foul magic these reports turn out to be true, you must do whatever you can to contain this threat!", objectives = "" }
WordHunterWoW_QuestEN[57778] = { title = "The Maldraxxian Job", description = "We cannot hope to hold the Seat without a necropolis. Khaliiq reports that Vashj is ready to set her plan in motion.\n\nMeet with her and the other Eyes at Nurakkir. Do what must be done.", objectives = "" }
WordHunterWoW_QuestEN[57787] = { title = "Keep to the Path", description = "That's everything on the list for this part of the forest. Lady Moonberry said to meet her in Tirna Vaal. It's just down the road; I'm going to fly ahead so everyone knows to expect you.\n\nJust stay on the path and you won't be eaten. Probably. See you soon!", objectives = "" }
WordHunterWoW_QuestEN[57816] = { title = "Dreamweaver", description = "Troubled winds sweep across Tirna Vaal. The boughs tremble in concern over the Queen's arrival. All must be as it should be.\n\nDreamweaver's wings droop with the weight of worry. Chaos swirls around the wildseeds under his care.\n\nCalm the churning waters of the grove. Bring harmony to discord and let Dreamweaver flutter once more.", objectives = "" }
WordHunterWoW_QuestEN[57818] = { title = "Nothing Goes to Waste", description = "The gormlings are industrious creatures. Naturally, they are our source of gorm gris.\n\nGormlings are cute, small, and hungry, like Gloober here! Except he is not hungry right now, because I just fed him. Look at that little belly...\n\n<Ahem>. I digress.\n\nGormlings will be drawn to consume anything that is not brimming with anima. They find it simply delicious. \n\nTake that wildseed there, and bring it into their pen. Then, see if you can get the gormlings to feast upon it!", objectives = "" }
WordHunterWoW_QuestEN[57824] = { title = "Collection Day", description = "Now, we can collect the gorm gris for Guardian Kota!\n\nOnce the gormlings have eaten something, we can 'encourage' them to give it back up. What they produce, we call gorm gris!\n\nMy Gormherd Branch should encourage them to do this safely. \n\nGo on, give it a try on good ol' Gloober first.\n\nWhat has me worried is how the other gormlings might behave. They have been acting so strangely lately!", objectives = "" }
WordHunterWoW_QuestEN[57825] = { title = "Delivery for Guardian Kota", description = "This is most disturbing, indeed. The gorm are just too... wild, now!\n\nI wonder if the drought is making everything delicious to them, and that is why.\n\nThis isn't enough gorm gris, either. And I do not want to disappoint Kota..\n\nBut, I also don't want to put you through more trouble collecting it. I will go myself into the burrows nearby, to see if I can find any more for her.\n\nWould you take this gorm gris to her for me, please?", objectives = "" }
WordHunterWoW_QuestEN[57860] = { title = "How to Become Forsworn", description = "The Forsworn have taken control of Kalliope's Rest and are looting its antiquities. They must be looking for the Spear of Kalliope, a relic of great power.\n\nTheir numbers are far too great and we are no match. Perhaps there is another way? \n\nA small group of aspirants is removing artifacts from the shrine. If you gather uniform pieces and an insignia from them, we can get you inside the shrine unnoticed.", objectives = "" }
WordHunterWoW_QuestEN[57861] = { title = "Just Act Natural", description = "With this disguise you will blend right in. I... know a Forsworn artificer on the inside who should prove useful. You need to remain convincing, however.\n\nThe most important thing is to get to Kalliope's spear before the Forsworn manage to do so. The shrine has many defenses, but it's only a matter of time before they find it.\n\nI am somewhat ashamed. Many of the aspirants here used to be friends. So much has been lost.", objectives = "" }
WordHunterWoW_QuestEN[57865] = { title = "Ages-Echoing Wisdom", description = "Hmph. Even if I wanted to give her weapons, I cannot. My glade is under attack!\n\nMost of my people were driven out during the attack on the growthworks but a few of the elders stayed behind. Whether to delay the enemy or see the friends to safety, they are not here where it is safe.\n\nEach elder can perform extraordinary works and could make the weapons in no time at all. Rescue the elders and then we'll talk about using their talents for the good of Ardenweald.", objectives = "" }
WordHunterWoW_QuestEN[57866] = { title = "Idle Hands", description = "If you want my help then you are going to need to help me first.\n\nThere is a group of spriggans that have assaulted the growthworks to the northeast. They are causing all manner of havoc and I simply will not abide this trespass into my lands.\n\nGo there and teach them a lesson. If they will not flee, then slay them on the spot!", objectives = "" }
WordHunterWoW_QuestEN[57867] = { title = "The Sweat of Our Brow", description = "Ah, an outsider! You are perfect for this task.\n\nThe spriggans are known for their mischief. They have been cursing our tools and supplies and trapping unsuspecting workers!\n\nLike our curses, they must obey the rules. You'll need shimmerdust for baskets, thread made of gossamer for harps, and minty fresh breath for the soulwebs. How odd.\n\nGood luck and let the Lady of the Falls know when you're done. She'll be delighted to hear it!", objectives = "" }
WordHunterWoW_QuestEN[57868] = { title = "Craftsman Needs No Tools", description = "Oh, I am quite all right! There's just one little thing....\n\nOne of these fiends made off with my lucky mallet! I simply cannot leave my mallet behind. I do not even use it much any more, but it is quite lucky and I always keep it with me.\n\nPlease, I cannot even think about building anything without it. Do keep an eye out for it, will you?", objectives = "" }
WordHunterWoW_QuestEN[57869] = { title = "Spirit-Gathering Labor", description = "You are not like the others.\n\nThe waters here carry deep power. Power most have forgotten. But the tirnenn forget very little.\n\nPower flows through the earth just as water flows with power. Flows can be trapped for a time, dripping. Drop by drop they drip into vessels.\n\nSearch for the vessels beneath the falls. Collect the power.", objectives = "" }
WordHunterWoW_QuestEN[57870] = { title = "The Games We Play", description = "Do not worry about me. We have a bigger problem.\n\nI heard their leader around here somewhere during the attack. I have been keeping watch from here but I have not been able to see them. They must be using some sort of glamour to hide themselves.\n\nI have yet to meet a spriggan who can resist a game. If you find one eager to play and can win, then perhaps you can learn something about their leader.", objectives = "" }
WordHunterWoW_QuestEN[57871] = { title = "Outplayed", description = "Now we can strike down their leader, friend.\n\nIt just so happens that I have a large pouch of puffpetal powder right here. Why don't you take it and toss a few handfuls around the workshop floor at the top of the falls? If they are still there, I imagine they will have an... unfortunate reaction.\n\nWhile you do that I will gather the other elders and make our way to Glitterfall Basin. Speak with the Lady when your task is done.", objectives = "" }
WordHunterWoW_QuestEN[57872] = { title = "Bring More Friends!", description = "This is only the beginning, friend.\n\nI must thank you again for rescuing me. Now that we have found a safe route, I am but the first of many. Druids from all around Ardenweald have heard of the safety of this glade, and I wish to bring them all here.\n\nI have known Roriel for most of my time in this place. She is a capable healer, despite her appearance. She would be a fine addition to this place.\n\nShe was last seen near Tirna Fein to the west. Please let her know the way is clear.", objectives = "" }
WordHunterWoW_QuestEN[57873] = { title = "Word from Orsis", description = "As you can see, {name}, we have our hands full here dealing with these disgusting bugs.\n\nOur caravans from the south have stopped arriving and we have received disturbing news from the few who've made it back recently.\n\nI've sent a patrol toward Orsis to investigate; they are past due for a report back.\n\nCan I ask you to check in on them for me?", objectives = "" }
WordHunterWoW_QuestEN[57875] = { title = "Mark of Humility", description = "Quartermaster, you've arrived.\n\nThose fools over there still haven't gotten past the first barrier. We need to get into that cave to have any chance at recovering the Spear of Kalliope.\n\nOur research discovered the phrase, \"Only the humble find their way. Even heroes kneel before virtue.\" But those fools have been working on that clue for ages.\n\nGo figure out the problem and get inside that cave. We need its mark to open the final vault.", objectives = "" }
WordHunterWoW_QuestEN[57876] = { title = "The End of the Beginning", description = "<Renathal struggles to speak, his wounds evident.>\n\nI knew Denathrius had hoarded anima, but this... this is beyond imagining.\n\nThe Jailer will surely use this power to shatter his bonds. Should he break free of the Maw, all the realms of Death will fall.\n\nWe must continue to press the fight against Denathrius. Alas, we cannot hope to succeed alone.\n \nReturn to Oribos with Draven and speak to the Honored Voice, Tal-Inara. Tell her what you have seen this day and implore her to action.", objectives = "" }
WordHunterWoW_QuestEN[57877] = { title = "The Looming Dark", description = "It is good you have returned safely from Revendreth, {name}. We sensed a betrayal that has shifted the infinite threads of fate.\n\nThe Maw surges with power. We must know the cause.", objectives = "" }
WordHunterWoW_QuestEN[57878] = { title = "Choosing Your Purpose", description = "Each covenant is vital to the Shadowlands. Though they often seem at odds with one another, this too is part of the Purpose.\n\nAll the covenants need to grow strong to face the threat of the Jailer. But your efforts cannot be divided. They must be focused upon a single path. Other mortals may make a different choice.\n\nThe time has come for you to take a side. \n\nSpeak to your allies. Then make your choice at the map of the Shadowlands before me.", objectives = "" }
WordHunterWoW_QuestEN[57880] = { title = "An Estate Within the Old Gate", description = "I believe I know how we can obtain the Countess's medallion and avoid making any new enemies.\n\nBefore being cast out into the Light, I held a prominent position within the Countess's court. She bestowed upon me an estate with direct access to her private chambers. \n\nIf the estate still stands, you can use it to sneak into the Countess's manor and steal the medallion without ever drawing your weapon. \n\nTake this note to my trusted butler, Bogdan. He will provide whatever assistance you need.", objectives = "" }
WordHunterWoW_QuestEN[57881] = { title = "The Key to Rebuilding", description = "If we plan to revive the estate, we'll first need the keys!\n\nWhen Theotar was exiled to the Ember Ward, he lost all titles and property, meaning that the estate fell into the hands of another aristocrat. \n\nThe new owner is a mystery to me, but household staff almost always carry keys on them as they do their business within the Old Gate. \n\nRecover the key and we'll be on our way to rebuilding the manor.", objectives = "" }
WordHunterWoW_QuestEN[57882] = { title = "Reestablishing the Household", description = "Unfortunately, when ownership of the estate changed hands, the staff were all displaced and forced to find new work. Some of us found suitable roles within favorable households. After all, everyone needs a sommelier! \n\nOthers were not so lucky. They're still here in the Old Gate, taking odd jobs to survive. I'm sure they'll be eager to work for the Duke again once they learn we're reestablishing the household.\n\nSeek them out and present this offer of employment.", objectives = "" }
WordHunterWoW_QuestEN[57884] = { title = "Reclaiming Thornhill Manor", description = "I've done some digging and discovered that Viscount Nicolae is the new inhabitant of Thornhill Manor. \n\nA vile thing, he is. It'll take us weeks to rid the estate of his stench!\n\nHopefully, you can rid us of him in a much timelier fashion. \n\nI'll gather the rest of the staff and together we can reclaim Thornhill Manor.", objectives = "" }
WordHunterWoW_QuestEN[57885] = { title = "A Discreet Entrance", description = "I can assure you--this is not how we left the place. Never would we ever let the manor fall into such a state. \n\nAt least the mirror is still intact, that's what's important. You can use it to enter the Countess's private chambers discreetly and recover the medallion. \n\nGo, quickly, before word spreads of what we've done. We'll do our best to restore the manor while you're gone.", objectives = "" }
WordHunterWoW_QuestEN[57886] = { title = "A Meal and A Deal", description = "Even though you arrived here uninvited, you weren't unexpected. I know all that goes on within my district. \n\nAs such, let us share a meal and speak of the matters at hand.\n\nI believe there's a way in which we can both get what we want.", objectives = "" }
WordHunterWoW_QuestEN[57887] = { title = "Killing the Messenger", description = "I make it my business to know what is going on within my district. \n\nTraditionally we use stone fiends to relay messages, but my informants have alerted me to some suspicious communications going on within the Old Gate. \n\nA venthyr has been hired to run missives between two undisclosed parties. When someone puts that much effort into concealing their identity, it can never be good.\n\nFind this courier and recover whatever missives they might be carrying.", objectives = "" }
WordHunterWoW_QuestEN[57888] = { title = "An Invitation to Treachery", description = "While the missive made it clear that Andrei is displeased with my position, nothing in the letter identifies his co-conspirator. \n\nAll we really know is that they are trying to gain access to my soiree this evening so they can carry out their plans. Let's make it easy for them, shall we? \n\nHead into the Redelav District and deliver an invite to the prominent houses. This way, we'll be sure the traitors show up.", objectives = "" }
WordHunterWoW_QuestEN[57889] = { title = "\"Accidental\" Arson", description = "It's no use trying to get Andrei to tell us who he's working with. He won't talk, and we can't risk alerting his accomplice. \n\nWe need to get rid of him, and it needs to look like an accident. \n\nOnce Andrei's been dealt with, set fire to his rug and let the whole estate burn down.  \n\nAndrei isn't someone you want coming into power. He's as ruthless as he is cruel.", objectives = "" }
WordHunterWoW_QuestEN[57890] = { title = "Beautiful, But Deadly", description = "The Redelav District is home to the most affluent venthyr in all of Revendreth. Its denizens spare no expense on the upkeep of their extravagant gardens.\n\nWell worth the effort, I must say. For the Redelav District is the only place where Duskmire mushrooms can grow. They are as beautiful as they are deadly.\n\nWould you mind collecting a few? Their uses are varied, and it's always a good idea to have some on hand.", objectives = "" }
WordHunterWoW_QuestEN[57891] = { title = "Mix, Mingle, and Meddle", description = "Once the party begins, I will be occupied with a plethora of nobles that wish to cling to my side. \n\nThis is why I need you to mingle. Speak with the attendees and see if you can determine which house is conspiring against me. \n\nBe warned, invited guest or not, these aristocrats can smell an outsider. You won't receive a warm welcome from everyone.", objectives = "" }
WordHunterWoW_QuestEN[57892] = { title = "Enacting Immediate Justice", description = "There are likely many in attendance who wish me harm. \n\nI trust you have done your job in determining which house has been working with Andrei?\n\nOnce they are named, I trust you will enact immediate justice.", objectives = "" }
WordHunterWoW_QuestEN[57893] = { title = "Neither Enemy nor Ally", description = "I hope you now see the importance of the role I play. \n\nMy parties serve a greater purpose. Keeping the influential and elite entertained helps quell uprisings. If their minds are consumed by trivial things, they don't have time to plot or plan. \n\nSometimes, battles are best fought before they begin. Giving you my medallion is an example of that. \n\nWe may not be allies, but we are not enemies, either.", objectives = "" }
WordHunterWoW_QuestEN[57895] = { title = "Elysian Hold", description = "One more step yet remains before your initiation is complete.\n\nYou must now enter Elysian Hold, entryway to the rest of the Spires of Ascension and the vantage point from which the ascended safeguard Bastion and our aspirants in training.\n\nOnce there, we shall ensure you are fully acquainted with the hold's offerings. Since you lack wings, I shall escort you there.", objectives = "" }
WordHunterWoW_QuestEN[57897] = { title = "Dangerous to Go Alone", description = "There is one last thing you must do before we can act to clean up Denathrius's chaos.\n\nYou must have a soulbind.\n\nAll kyrian undergo this sacred ritual--albeit typically many aeons before they stand before the Archon herself.\n\nSoulguide Daelia will guide you in this process. Seek her out in the chamber below.", objectives = "" }
WordHunterWoW_QuestEN[57898] = { title = "Soul Meets Body", description = "To soulbind with another is not an irrevocable bond. However, it is not to be entered into lightly.\n\nYou will experience one another's pasts. Your hopes, fears, dreams, your very memories--if any still linger. You will become kindred spirits in the truest sense.\n\nOnce complete, your connection will transcend physical space and make you stronger in more than mere brawn.", objectives = "" }
WordHunterWoW_QuestEN[57899] = { title = "More Work?", description = "Your world has a saying that \"you cannot be in two places at once.\"\n\nWithout a soulbind, that is true. Thankfully we have resolved that matter. Such physical limitations are a mortal construct.\n\nChristen our newest addition to the Hold in the ramparts above, then seek out Koros and you will see.", objectives = "" }
WordHunterWoW_QuestEN[57900] = { title = "Across the Shadowlands", description = "As kyrian we are responsible for ensuring that every last soul that enters the Shadowlands is sent to their appropriate eternity.\n\nHowever, our eternal charge does not end in Oribos.\n\nThere are countless matters in the Shadowlands that need attention--far more than any one of us can handle. That, my friend, is where I come in.\n\nConsider me your eyes in the field. Allow me to demonstrate with a simple task, so that you may both reap the benefits of my services.", objectives = "" }
WordHunterWoW_QuestEN[57901] = { title = "All That Remains", description = "Just as you must work with your soulbind in an eternal partnership to ensure peace in our realm, so must you work to restore the flow of anima in the sky above.\n\nCapheus, one of the great Mikanikos's students, has specialized in the craft of directing what anima we have to the temples that need it most.\n\nGiven the great drought of anima that plagues us if anyone could use assistance, it would be her.", objectives = "" }
WordHunterWoW_QuestEN[57903] = { title = "Power in the Sky", description = "This device you see here can be used to send anima to our temples and aid our people.\n\nAs each temple regains its flow of anima, it will begin to function once more. You may find these functions useful in your journeys, or you may even find new challenges that await you.\n\nOnce you have brought some anima to our sanctum, use the device to direct it to a temple, and see the results for yourself.", objectives = "" }
WordHunterWoW_QuestEN[57904] = { title = "Our Eternal Charge", description = "You have been fully inducted into our sacred covenant, Maw Walker, and may stand tall forevermore as a kyrian. There will be many challenges ahead of us--we shall face them together.\n\nFor now, return to Polemarch Adrestes and inform him that your training is complete. We are few in number as of late and I am sure he will have need of you. \n\nGo in service, {name}.", objectives = "" }
WordHunterWoW_QuestEN[57905] = { title = "A Unique Opportunity", description = "All the anima in the Shadowlands will not restore Elysian Hold to its full glory without willing souls to ensure its many capabilities function properly.\n\nSoulguide Daelia is one of our most veteran watchers. She has been tasked with bringing souls to these halls once more.\n\nYou should pay her a visit within the Sanctum of Binding to see if you might be of aid.", objectives = "" }
WordHunterWoW_QuestEN[57908] = { title = "The True Crucible Awaits", description = "I confess, {name}. I had little hope when you first arrived.\n\nKleia is convinced that your presence here is a sign of things finally improving in Bastion. I was... skeptical.\n\n<The Forgelite gestures to her forge.>\n\nWhat you have done for me will not soon be forgotten. There is a path beyond the Crucible. To walk it, you must overcome a trial. It will be difficult. Such a thing takes eons for most.\n\nYou are not most.\n\nKleia and Pelagos will tell you more. They await you near the sparring grounds.", objectives = "" }
WordHunterWoW_QuestEN[57909] = { title = "Assessing Your Stamina", description = "The trial ahead will test you on many levels. I, like Kleia, wish to assess your willingness to endure.\n\nLook around you. All the aspirants here train for the very trial you are to attempt. Some have been here, honing their skills, for centuries. Ages. Some grow quickly, some do not.\n\nYour task is to engage them in friendly, armed combat. Among the kyrian this is known as a combat meditation.\n\nHelp them find focus, and they shall help you do the same.\n\nReturn to me when you feel ready to continue.", objectives = "" }
WordHunterWoW_QuestEN[57912] = { title = "Baron of the Chosen", description = "Our forces at the Spearhead are under siege from Margrave Gharmal's vanguard. If Vyraz himself is leading the defense, then the situation must be dire.\n\nThe House of Constructs shapes flesh to forge bodies for its forces. They were once an indispensable ally, but have become a fearsome enemy.\n\nMargrave Krexus trusts your might. No doubt you will have need of it.", objectives = "" }
WordHunterWoW_QuestEN[57914] = { title = "Mark of Knowledge", description = "There is another matter for which I need your assistance. My researchers and interrogators have been tirelessly working on the second chamber. So far they don't have any leads.\n\nI need you to speak to them and see if they've made any progress. Tell them, if they have nothing to show, then they will soon find themselves at the end of my sword.\n\nGet me that mark, quartermaster!", objectives = "" }
WordHunterWoW_QuestEN[57915] = { title = "Search for Survivors", description = "The bugs came from everywhere... There wasn't any time to react.\n\nMany of my friends died where they stood, while others tried to fight with our meager tools.\n\nI'm a coward. I fled in the commotion instead of trying to help.\n\nNow, here I am, out of food and water and too scared to look for survivors.\n\nPlease, I beg you to help anyone you find left alive in Orsis...", objectives = "" }
WordHunterWoW_QuestEN[57917] = { title = "[DNT] Test - JAM", description = "", objectives = "" }
WordHunterWoW_QuestEN[57918] = { title = "The Absolution of Souls", description = "Do you not yet understand the purpose of Revendreth, Maw Walker?\n\nThe souls under our care teeter on the brink of permanent damnation. Even with perfect attention and careful processing, not every soul can escape the Maw and be elevated to a higher destiny.\n\nThat is true under the best of circumstances.\n\nCurrently, due to your installation of the Chamberlain at the Halls of Atonement, we're instead witnessing the worst of circumstances.\n\nWe must return to the Halls of Atonement and enforce order.", objectives = "" }
WordHunterWoW_QuestEN[57919] = { title = "An Abuse of Power", description = "The souls have suffered tremendously under the Lord Chamberlain.\n\nWe venthyr subjugate souls to our will so that we may lead each to the absolution it requires--willing or not.\n\nThe Lord Chamberlain, however, has been using our relics and rituals to abuse the souls under his authority. He binds the souls to their sinstones, perverting their very essence!\n\nUse these ritual chains on the abused soul and subjugate it to your will. We must attempt to absolve it.", objectives = "" }
WordHunterWoW_QuestEN[57920] = { title = "The Proper Souls", description = "We must save as many souls as we can from the fate we have just witnessed.\n\nSearch the halls for souls who have escaped the Lord Chamberlain's perverse rituals. Subjugate them and bring them to me inside the Halls of Atonement.\n\nTogether, we will make certain that each soul is appropriately processed and cared for.", objectives = "" }
WordHunterWoW_QuestEN[57921] = { title = "The Proper Tools", description = "There are very specific procedures that we must follow to best tend to the souls under our care. You and I will follow them exactly.\n\nI can mask your garish appearance, but you must acquire the necessary ritual tools on your own.\n\nRequisition them from the depraved venthyr serving the Lord Chamberlain nearby.", objectives = "" }
WordHunterWoW_QuestEN[57922] = { title = "The Proper Punishment", description = "Thankfully, I am not the only one who remembers the high calling of the Halls of Atonement and its servants.\n\nThese avowed ritualists have been working covertly to preserve the integrity of the halls.\n\nThey report that the Lord Chamberlain relies on a particularly gifted soulflayer to teach other ritualists how to corrupt the souls.\n\nGive him the reward he deserves.", objectives = "" }
WordHunterWoW_QuestEN[57923] = { title = "Ritual of Absolution", description = "The ritual of absolution is a sacred rite that forces souls to discard the burdens of their mortal lives.\n\nThe soul must be a willing participant if the ritual's effect will be meaningful and long-lasting. We often spend ages preparing a soul for a single absolution ritual.\n\nThe Lord Chamberlain has neglected his duty. These souls are overdue for absolution, practically bursting with anima.\n\nWe will perform the ritual ourselves, and hurry these souls along their journey.", objectives = "" }
WordHunterWoW_QuestEN[57924] = { title = "Ritual of Judgment", description = "After all rituals of absolution are complete, each soul must face its final judgment in Revendreth.\n\nThere are three potential verdicts:\nIf proven unworthy, it is condemned to the Maw for eternity.\n\nIf fully absolved of its sins, it is either elevated to a venthyr or returned to the Arbiter to be assigned its new destination.\n\nOur most sacred ritual, the judgment, determines this fate.\n\nOne such ritual is happening now. I will disguise you and we will participate to ensure a just verdict.", objectives = "" }
WordHunterWoW_QuestEN[57925] = { title = "Archivist Fane", description = "Well, our disguises are superfluous now. We will not be welcome after disrupting their depraved ritual.\n\nDespite what we've observed here, some steadfast venthyr do still remain within these halls. Those who have not forsaken our vocation, and carry on with our calling.\n\nArchivist Fane is one such as these. Aid his endeavors however you can. We will need his insight to loosen the Lord Chamberlain's grip over these halls.\n\nI must tend to Gresit. He has much to learn.", objectives = "" }
WordHunterWoW_QuestEN[57926] = { title = "The Sinstone Archive", description = "You said Inquisitor Traian oversaw the ritual?\n\n<Archivist Fane searches the massive archives in this chamber.>\n\nWe archivists maintain strict records of every soul that passes through these halls.\n\nOr at least we're supposed to. The sinstones of powerful venthyr tend to go \"missing.\"\n\n<Archivist Fane rolls his eyes.>\n\nI don't see his sinstone here. He might've stolen it, or someone could be hoarding it as blackmail.\n\nHelp me complete my archives, and I'll get you any sinstone you need.", objectives = "" }
WordHunterWoW_QuestEN[57927] = { title = "Rebuilding Temel", description = "Revendreth demands penance from all, and it would appear that even you are not exempt.\n\n<Cryptkeeper Kassir grins.>\n\nDo not fear, I have no intention of exacting revenge for the violence you inflicted upon me.\n\nBut I cannot offer you Temel either.\n\nThe Lord Chamberlain--who you so wisely chose to install as master of these halls--deemed Temel a threat to his control.\n\nHis thugs bashed Temel to bits and scattered the pieces among these crypts. It's not the first time I've had to rebuild him.", objectives = "" }
WordHunterWoW_QuestEN[57928] = { title = "Atonement Crypt Key", description = "<This key is marked with a sigil that matches the crypts in the Halls of Atonement. What is the Lord Chamberlain hiding away in there?>", objectives = "" }
WordHunterWoW_QuestEN[57929] = { title = "Hunting an Inquisitor", description = "You may have noticed that inquisitors are protected by the Lord Chamberlain's magic. A potent consequence of wielding the Master's medallion.\n\nBut now that we have access to Inquisitor Traian's sinstone from the archives, we have the power needed to break through those defenses.\n\nLocate the inquisitor, and order Temel to read out from his sinstone. Declaring the true name and sins of the inquisitor will shatter his defenses and make him vulnerable for a short window of time.\n\nBe ready to strike.", objectives = "" }
WordHunterWoW_QuestEN[57931] = { title = "Phalynx Malfunction", description = "As part of their training, I order my phalynx units to march the fields, keeping an eye on the wildlife and any goings-on.\n\nUnfortunately, last time they returned they were one fewer in number.\n\nPlease search the Golden Pasture and search for the missing unit, then return it here.", objectives = "" }
WordHunterWoW_QuestEN[57932] = { title = "Resource Drain", description = "Usually repairs easy. Anima everywhere!\n\nExcept drought means we can't just pull it from air. Other sources needed!\n\nTake this. Drain anima from cloudstriders. Not ideal, but desperate times.", objectives = "" }
WordHunterWoW_QuestEN[57933] = { title = "We Can Rebuild Him", description = "Gatamatos needs numerous repairs to meet functional standards.\n\nUpkeeping phalynx is part of the role. Lend a hand so we may finish the repairs thoroughly and quickly.", objectives = "" }
WordHunterWoW_QuestEN[57934] = { title = "Combat Drills", description = "Our phalynx units excel in combat. They are thoroughly trained in taking foes down by the legs, as well as hunting down beasts gone awry.\n\nI need you to take stock of Gatamatos's fighting routines. Take him into the cavern below and practice his combat against the wyrms there.", objectives = "" }
WordHunterWoW_QuestEN[57935] = { title = "Laser Location", description = "Phalynx have precise detection mechanisms that allow for excellent scouting.\n\nIn the cave below we have scattered gems that our units are trained to locate. Escort Gatamatos to run some drills and recalibrate his training.", objectives = "" }
WordHunterWoW_QuestEN[57936] = { title = "Superior Programming", description = "Phalynx listen to their orders. Never disobey!\n\nLarions are wild beasts. Can attack. Could eat a steward, probably!\n\nUntamed larion lives close. Has chased many stewards, very scary! Please take care of it.", objectives = "" }
WordHunterWoW_QuestEN[57937] = { title = "Tactical Formation", description = "The principal step of our training regiment for our phalynx is formational drills. They must recall standard kyrian battle formations, and how to flow from one to the next.\n\nFormational training is the final piece of information that Gatamatos is still missing. Please aid in retraining him.", objectives = "" }
WordHunterWoW_QuestEN[57947] = { title = "Spirits of the Glen", description = "Animals of the forest, mortal souls given form, frolic in the glen. Their anima, a boon to the weald, given freely as rain on the leaves.\n\nBut danger lurks in the shadows. A dark storm of malice and enmity tears at the trees. Creatures seeking shelter find only peril.\n\nRescue them.", objectives = "" }
WordHunterWoW_QuestEN[57948] = { title = "Nothing Left to Give", description = "Oh no, oh no!\n\nMy friends, they gave so much. So much of their anima, they lost their forms! We all take a form when we come here, you see. Something that suits us!\n\nBut we give our anima, we give! To help the groves. And we give so much... sometimes too much.\n\nI still have some anima. I still have my form! Get me to my friends! We can get THEIR forms back!", objectives = "" }
WordHunterWoW_QuestEN[57949] = { title = "They Need to Calm Down", description = "Spriggans! Nasty spriggans. They came to the grove. They messed it all up!\n\nThey took the anima from the soul webs! We were collecting it, yes. Collecting it for the Tall Tree and their grove. The spriggans have to pay!\n\nBeat them up! Then use this soulweb to take back the anima. We need it! They don't!", objectives = "" }
WordHunterWoW_QuestEN[57950] = { title = "Mizik the Haughty", description = "Bad spriggans! Bad! They take our anima. We lose our forms! And one is worst of all.\n\nMizik! He tells the others what to do. And he rides a gorm! Big, nasty gorm!\n\nGet him. Get him!", objectives = "" }
WordHunterWoW_QuestEN[57951] = { title = "Souls Come Home", description = "To the tree, to the tree! It is time for us to return to the grove.\n\nWe have our anima. We have our forms. The Tall Tree needs the anima. The Tall Tree will be happy!\n\nI will see you there!", objectives = "" }
WordHunterWoW_QuestEN[57952] = { title = "In Need of Gorm Gris", description = "Our neighboring grove at Glitterfall Basin has sent out a desperate plea for gorm gris.\n\nIt may have humble origins, but it is an important ingredient for our artisans and crafters. As this drought goes on, it has become increasingly difficult to collect.\n\nI would like to help them out, with the resources that we are able to spare.\n\nPlease, find Master Sha'lor out by the Tranquil Pools, where he keeps our little gormling population.\n\nAsk him for more gorm gris.", objectives = "" }
WordHunterWoW_QuestEN[57954] = { title = "Burn the Bodies", description = "The bugs seem to be indiscriminately laying eggs all over the nearby corpses.\n\nThey are using them as food to spawn more of those horrible things. Disgusting!\n\nWe can mourn the dead later, but if any more bugs are allowed to hatch we may not live long enough to do so.\n\nBurn the bodies and destroy those eggs!", objectives = "" }
WordHunterWoW_QuestEN[57955] = { title = "To Ankhaten Harbor", description = "I fear that I don't yet have the strength to ride out into the sands and face those monsters again.\n\nRide to the south and find Tracker Samara in the excavation camp formerly known as Schnottz's Landing.\n\nTell her to halt any caravans that plan to pass this way, lest others are ambushed and met with the same grisly fate.\n\nWe must get the word out across Uldum before our forces are further divided!", objectives = "" }
WordHunterWoW_QuestEN[57956] = { title = "Wastewander Hosts", description = "The bugs have been laying eggs in the corpses of our soldiers, it's absolutely terrifying!\n\nSome of them are rising from the ground as putrid, bloated, hideous monstrosities.\n\nWe have to stop them before they continue to bolster their ranks with our fallen.\n\nIt's not a pleasant task... but I have to ask you to help me destroy them. Completely.\n\nGrab some bombs behind me, if you'd like.", objectives = "" }
WordHunterWoW_QuestEN[57959] = { title = "Heroic Warfront: The Battle for Darkshore", description = "Darkshore belongs to the Horde! We must hold that ground to maintain our dominance over Kalimdor.\n\nPrepare yourselves. Battle awaits!", objectives = "" }
WordHunterWoW_QuestEN[57960] = { title = "Heroic Warfront: The Battle for Darkshore", description = "We will not tolerate further Horde aggression in our territories.\n\nThe night elves will not stand alone this day. Darkshore will be theirs once more.\n\nFor the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[57964] = { title = "Revenge Is Easy", description = "There's still a lot of us here, trying to survive in these ruins.\n\nThese constructs have been encroaching on us constantly. They steal what they can, and haul off any of us they capture to be recycled in their labs.\n\nThe solution here requires an extensive use of violence, by you!", objectives = "" }
WordHunterWoW_QuestEN[57966] = { title = "You Go First", description = "You've proven useful. So, I am going to require you to disarm the defenses of this hall. \n\nPlease take care not to die too quickly. I'd like to have the spear before the end of this eon.", objectives = "" }
WordHunterWoW_QuestEN[57967] = { title = "Rightful Resting Place", description = "You have truly proven yourself a hero in the eyes of those who are its absolute judge.\n\nI thank you for giving me the honor of holding it, even for this briefest moment. However, it is only proper that you be the one to enshrine the spear at it's rightful resting place.\n\nLet us meet at Elysian Hold where you can do the honors.", objectives = "" }
WordHunterWoW_QuestEN[57968] = { title = "The Wastewandering Dead", description = "Is there no end to these foul monsters!?\n\nI cannot abide the desecration of our dead, especially not as fodder for this disgusting insect army.\n\nDestroy as many as you can, preferably with fire!", objectives = "" }
WordHunterWoW_QuestEN[57969] = { title = "Tend the Wounded", description = "My friend, as you can see here, we are besieged by these terrible creatures.\n\nMany of our comrades have fallen prey to the monsters, but fortunately, we have enough warriors here to keep the threat at bay... for now.\n\nIf you are able to assist us, please, tend to our wounded and help clear a path for them to escape the ruins.", objectives = "" }
WordHunterWoW_QuestEN[57970] = { title = "Ruinator Xok'nixx", description = "Ar'kali and a group of our warriors are engaged with a most behemothic creature in the heart of the ruins.\n\nShe can hold her own against nearly any foe, but I fear it is only a matter of time before this monster is able to wear them down.\n\nAlthough the creature is occupied for now, if our warriors fall, the ruins will be lost to us.\n\nPlease, make haste, with your help they can surely fell this titanic foe.", objectives = "" }
WordHunterWoW_QuestEN[57971] = { title = "Ruins of Ammon", description = "These things seem to be everywhere and all at once!\n\nEither this was an organized attack, or there are far more of them than we can even comprehend.\n\nRegardless, this is bad for us... really, really bad.\n\n{name}, I need you to travel to the Ruins of Ammon and find out what the situation is like over there.\n\nIf they need help, please try to lend a hand!", objectives = "" }
WordHunterWoW_QuestEN[57976] = { title = "Lead By Example", description = "Margrave Krexus expects much of you, mortal. Show these soldiers how a true champion of the arena vanquishes their foes and claims victory!\n\nMeet these traitorous constructs head on. Leave none standing!", objectives = "" }
WordHunterWoW_QuestEN[57977] = { title = "A Temple in Need", description = "<Eridia peers down at you.>\n\nYour face is new to me.\n\n<Eridia frowns.>\n\nI regret that this shall be your introduction to our temple. As my disciple has informed you, we seek the aid of all available aspirants to tend to those in our care.\n\nDo not trouble yourself over the specifics of the work that is needed. Those devoted to this temple will guide you. Seek out the disciples within.\n\nYou may find me within the temple when you have given your aid.", objectives = "" }
WordHunterWoW_QuestEN[57978] = { title = "Forward and Back", description = "", objectives = "" }
WordHunterWoW_QuestEN[57979] = { title = "Offensive Behavior", description = "Fine work, {name}. We've advanced with minimal casualties. \n\nFrom this new forward position, we can strike directly at the enemy commander. The troops you rallied will join the attack. Together, we will bring this battle to a decisive end.\n\nLocate General Alver and sound the horn.", objectives = "" }
WordHunterWoW_QuestEN[57982] = { title = "Breaking Down Barriers", description = "As I suspected, Stitchflesh's assistants are carrying on his work. Whatever they're building, we need to destroy it.\n\nThey've secured the chamber with a soul barrier and several bile spewers. We must find a way through!\n\nThales said he may have a suggestion.", objectives = "" }
WordHunterWoW_QuestEN[57983] = { title = "Archon Save Us", description = "Most of the aspirants were slaughtered and dismembered on arrival. They were the lucky ones. \n\nThe lead surgeon decided that the only things worth taking from me... were my eyes. I was discarded afterward and left to my rot. Archon save me, the screaming...\n\nI think there are other survivors being held nearby. Can you aid me in freeing them?", objectives = "" }
WordHunterWoW_QuestEN[57984] = { title = "The Ones in Charge", description = "They have been collecting kyrian... and our corpses... for some dark purpose.\n\nWhatever they are planning, we must put a stop to it.\n\nI have overheard mention of three individuals who seem to be in charge. We need to find them and eliminate them.", objectives = "" }
WordHunterWoW_QuestEN[57985] = { title = "Give Them a Hand", description = "The corpses are brought to this pit for processing. Their flesh is liquified and congealed before being shaped into new constructs.\n\nWe can hinder their production by extracting the animates from the pool prematurely. Use this hook to do so.\n\nDo not let Baron Halis catch you. He has a reputation for cruelty, even within his own house.", objectives = "" }
WordHunterWoW_QuestEN[57986] = { title = "A Burden Worth Bearing", description = "Mevix may be here for blood, but what I want is to spare my fallen kin from a terrible fate.\n\nMost of my fellow kyrian were either slain in combat or shortly after arriving here. If their corpses were bound for this pit, then perhaps we can recover them before they are thrown into it.\n\nTake the stewards with you and gather the bodies of my brethren. I will not allow them to be made into monsters.", objectives = "" }
WordHunterWoW_QuestEN[57987] = { title = "A Deadly Distraction", description = "Vyraz's assault on the House of Constructs may have failed, but we can still make them bleed now that we're inside.\n\nSlaughter as many as you can. I will hunt down the masterminds behind these new production efforts.", objectives = "" }
WordHunterWoW_QuestEN[57989] = { title = "The Spear of Kalliope", description = "The Spear of Kalliope is finally in my grasp!\n\nWith it, I will lay waste to all the Forsworn's enemies. Now behold while I take my prize!", objectives = "" }
WordHunterWoW_QuestEN[57990] = { title = "Obelisk of the Sun", description = "I have one more thing I must ask of you, my friend. Completion of this task is critical to our survival here.\n\nOur comrade, Zahra, has taken it upon herself to climb the plateau just east of us to secure one of the old bombers left up there.\n\nSo far, our attempts to get word back to Arik have failed. \n\nHowever, if you can help her get one of those planes working, we might just have a chance.\n\nHopefully they can send aid before we are overrun...", objectives = "" }
WordHunterWoW_QuestEN[57993] = { title = "Two of Them, Two of Us", description = "A construct made entirely of kyrian flesh...\n\nThis betrays everything Maldraxxus stands for! We are meant to defend the Shadowlands and all within it, not slaughter and exploit them!\n\nCome, {name}! We end this now!", objectives = "" }
WordHunterWoW_QuestEN[57994] = { title = "In The Flesh", description = "The souls of the fallen kyrian... I can sense their pain and confusion. They yet exist within the construct!\n\nPlease, we must not destroy it. Doing so would consign the souls within it--the souls of my brethren--to oblivion. \n\nPerhaps... perhaps they can aid us in escaping to freedom. I will soothe the souls within the construct while you direct its actions.", objectives = "" }
WordHunterWoW_QuestEN[58007] = { title = "Eyes on the Problem", description = "Our enemies rally at our gates. We cannot rely on daring air strikes to hold them at bay.\n\nVashj has a plan to permanently bolster our defenses. With your help, it might actually succeed.\n\nDo what you can to assist her. She seems more... agreeable toward you than she is with me.", objectives = "" }
WordHunterWoW_QuestEN[58008] = { title = "All Gassed Up", description = "So, I was checkin' all these planes... and you are never gonna believe this, but none of them have any fuel in the tanks!\n\nSaw a few canisters scattered around nearby, surely some a' them have some gas left.\n\nWas gonna collect 'em myself, but these damned bugs came outta nowhere and started swarmin' the place.\n\nToo many here now to deal with on my own, think you'd be able to lend a hand?", objectives = "" }
WordHunterWoW_QuestEN[58009] = { title = "To the Moon", description = "Alright! It's time to high tail it outta here.\n\nWe gotta get back to camp and tell Arik what's been going on out here as soon as possible.\n\nHead for the bomber and let's fuel 'er up. \n\nI'll letcha have the gunner seat, but I'm drivin', so let's try to blow up a few bugs on the way back!", objectives = "" }
WordHunterWoW_QuestEN[58010] = { title = "More Bits, More Bits!", description = "We need more Aqir samples, {name}. As many as you can get your hands on!\n\nI've made some fascinating discoveries already, but there's so much more to learn.\n\nWith further study and a bit of good luck, perhaps we can slowly begin to uncover some of their weaknesses.", objectives = "" }
WordHunterWoW_QuestEN[58011] = { title = "Bug Bites", description = "Margrave Stradama eagerly awaits the completion of our latest potion!\n\nHowever, I seem to have misplaced my stockpile of venom sacs. How embarrassing! I have felt a touch out of sorts lately...\n\nWould you please do me a favor and fetch some more? We cannot continue our work without them!", objectives = "" }
WordHunterWoW_QuestEN[58016] = { title = "Spores Galore", description = "My brightest apprentice, you return to me at last!\n\nYou worried me--you see, I heard the loudest clatter while working on one of my experiments... Before I knew it, I was here, and you'd disappeared!\n\nWherever you went is no matter. You're back now, and we have much to do!\n\nCome, my apprentice--we must fetch our ingredients first.\n\nCan you smell the spores germinating around us? We should pull some up to use in our endeavors!", objectives = "" }
WordHunterWoW_QuestEN[58022] = { title = "Finish What He Started", description = "Finding Sha'lor is our main priority. But there is another opportunity.\n\nTake the Gormherd Branch that he dropped. I know he was tinkering with it so that it would work on wild gorm.\n\nUse it on the gorm in the burrows, and see if you can collect any of their gorm gris.\n\nDon't bother with the little ones; get the really potent stuff from the bigger gorm.\n\nPerhaps if we can collect enough, and find that silly sylvar, he will not rush horns-first into the burrows again.", objectives = "" }
WordHunterWoW_QuestEN[58023] = { title = "One Big Problem", description = "We must go after Master Sha'lor. Tirna Vaal needs him! And I... I...\n\nI will report to the droman. They must know that Sha'lor is in danger. Then, I will enter the burrows myself from the south and help you defeat it.\n\nFor now, see what you can find. I refuse to believe that he is gone.\n\nThat monster will know the fury of a vorkai.", objectives = "" }
WordHunterWoW_QuestEN[58024] = { title = "Burrows Away", description = "<The ground has been freshly dug, and there are signs of more tunnels all over the place.\n\nCollapsing a few burrows would go a long way toward keeping Tirna Vaal safe from gorm infestation.>", objectives = "" }
WordHunterWoW_QuestEN[58025] = { title = "Queen of the Underground", description = "You tracked the massive gorm here to her den, and we've found Master Sha'lor.\n\nPerhaps not entirely unscathed, but he lives. That is enough.\n\nOne last task remains. Let us end this.", objectives = "" }
WordHunterWoW_QuestEN[58026] = { title = "When a Gorm Eats a God", description = "There is nothing more we can do here. I will get Master Sha'lor safely back to Tirna Vaal.\n\nWhen you get there, report to the droman what we found here. \n\nIf the gorm have started to eat the dead wildseeds, and are absorbing the power of the spirits within, we are all in serious danger.", objectives = "" }
WordHunterWoW_QuestEN[58027] = { title = "Slime, Anyone?", description = "While I know we're both eager to complete our potion, I believe the best lesson I can share with you is patience.\n\nPatience and slimes, of course!\n\nWith the help of slimes, we'll have our laboratory back in working condition. It's just as I taught you: combine your ingredients in the cauldron. Mix until the viscosity is just right...\n\nOh, listen to me--acting as if you've never concocted your own sentient being!\n\nGo on, my apprentice! The slimes are calling!", objectives = "" }
WordHunterWoW_QuestEN[58031] = { title = "Applied Science", description = "<What appears to be an old journal sits on Marileth's table, now mangled and missing pages.\n\nThe entries that are legible seem to have been written by Marileth when he was still sane, before the fall of his house.\n\nPerhaps if you find the journal's missing pages, you will gain more insight into what befell the House of Plagues.>", objectives = "" }
WordHunterWoW_QuestEN[58036] = { title = "Hazardous Waste Collection", description = "Ah, slimes: the dearest of friends and infinitely useful! They will help us craft our potion.\n\nBut it seems our tools have been scattered around, doused in toxic refuse. Margrave Stradama would be so disappointed at my lack of respect for lab safety!\n\nYour slime can comb through the refuse, diluting the plague's harmful agents. Simply pull the cleaned equipment from the body of your slime!\n\nSlimes... what would we do without them?", objectives = "" }
WordHunterWoW_QuestEN[58037] = { title = "Part of the Pride", description = "Pelodis insists that phalynx are superior to all autonomous beings, taking orders without fail.\n\nBut where is the nuance? Where is the reward for your effort?\n\nLarions make fantastic companions, but you must build a relationship with them. Introduce yourself to my pride. You will see that each has a personality of their own.", objectives = "" }
WordHunterWoW_QuestEN[58038] = { title = "All Natural Chews", description = "A huge part of larion care is providing for them and keeping them happy.\n\nLarions need to keep their teeth sharp and healthy, and for that they need to chew. If you do not give them proper things to chew on, they can get destructive.\n\nOne of their favorite chew toys are the antlers from the cloudstriders in the nearby field. Please, collect some antlers for the pride to enjoy.", objectives = "" }
WordHunterWoW_QuestEN[58039] = { title = "Larion at Large", description = "Some larions are more particular about the people they bond with than others.\n\nLentios is my companion, the larion I trust most with my life. I love the others as well, but he is a part of my soul.\n\nOne of my pride, Andira, has posed a struggle for me to bond with. She ran off into the pastures once again, and I fear she's gotten into something she shouldn't have.\n\nWould you mind finding her and bringing her home?", objectives = "" }
WordHunterWoW_QuestEN[58040] = { title = "With Lance and Larion", description = "Say what you want about phalynx, but Larion will always have one major advantage.\n\nWings!\n\nA bonded larion will hunt alongside you whether you are on the ground or in the air. \n\nTake my javelin and Andira then go out into the fields to hunt the cloudfeathers there. You'll feel the boon of larion companionship firsthand!", objectives = "" }
WordHunterWoW_QuestEN[58041] = { title = "Providing for the Pack", description = "Even beings of the Shadowlands need to eat. They may not do so quite like your world, but it is similar enough.\n\nThe pride's favorite prey is the juvenile cloudfeathers found nearby. Prove to Andira that you are a contributing member of the pride by taking her out to hunt for their next meal.", objectives = "" }
WordHunterWoW_QuestEN[58042] = { title = "On Larion Wings", description = "As a flightless being, you will unfortunately never feel the joy of flying alongside your companion.\n\nHowever... you could still fly with Andira.\n\nIt seems you have earned Andira's trust more than I've seen her with anybody else. Would you like to try a flight course?\n\nTake wing with Andira, then fly through the rings. Don't stray off course or take too much time to get between rings or she will leave you behind!", objectives = "" }
WordHunterWoW_QuestEN[58045] = { title = "Plague is Thicker Than Water", description = "Come closer, my apprentice... I have a mission of dire import!\n\nA necromancer came to our house recently, sent by the lich Margrave Sin'dane! He seemed so polite, always eager to lend a hand in my lady's most volatile creations.\n\nBut I grew wise, my apprentice. The way he skulked around, prodding for our most sensitive experiments...\n\nHe was trying to steal our slimes! I know it!\n\nYou should admonish him quite harshly. Show that no harm will come to our friends!", objectives = "" }
WordHunterWoW_QuestEN[58060] = { title = "The Night Market", description = "<Dracho motions to keep your voice down.>\n\nI need some assistance, I promise you will be paid handsomely. \n\nAt the edge of The Banewood lies some ruins. These ruins are home to a marketplace run by some brokers. They won't let me back there. Let's just say that my goods were deemed to not be up to their authenticity metrics. \n\nBut you... you're a Maw Walker! Bring them this package and exchange it for some Surberries from Ardenweald. \n\nJust don't say I sent you.", objectives = "" }
WordHunterWoW_QuestEN[58062] = { title = "A Very Special Guest", description = "Listen. It is obvious you are doing this deal on Dracho's behalf. \n\nI believe Ta'xera, the boss around here, would be very interested in striking a deal with someone of your talents.\n\nShe resides in the manor at the top of the hill. I recommend you don't keep her waiting.", objectives = "" }
WordHunterWoW_QuestEN[58068] = { title = "...Even The Most Ridiculous Request!", description = "A fan of the competition, are you? Perhaps you would like to be more than a mere spectator?\n\nI will give you a small task... one that not only benefits me, but that also gives you a chance to meet some of the storied competitors here.\n\nAs you can see, our three remaining houses have sent champions to attend the Contest of Conquest. Talk with them and attend to what needs they might have.", objectives = "" }
WordHunterWoW_QuestEN[58086] = { title = "The Master of Lies", description = "Once more unto the fangs of death himself, sword drawn, peace with oblivion made. Let us meet death together and bring him low.\n\nBe sure you are prepared for a sustained assault. For once we reveal ourselves, there will be no stopping. \n\nWhen you are ready, direct the Focal Mirror at the gates of Castle Nathria. Let us descend upon our burning enemies with ferocity and swiftness of action.", objectives = "" }
WordHunterWoW_QuestEN[58087] = { title = "Destroying the Source", description = "Tidecaller Nezara is running the show. If we take her out, the remaining naga will break rank, but getting to her won't be easy. She's protected by a magical barrier that's drawing power from powercells nearby. \n\nIf we can destroy the source, we can destroy Nezara.", objectives = "" }
WordHunterWoW_QuestEN[58088] = { title = "Juicing Up", description = "I've conceived a task befitting of your \"talents\".\n\nHave you heard of the House of Plague? Crafters of toxins and potions. They suffered a tragic accident--a true, true shame.\n\nHerein lies the problem: I have long used the work of the plague devisers to bolster my arena performance. Without a potion of their creation, I'd find the fight unnecessarily taxing.\n\nThe brokers do have such potions, but they \"do not like my face.\" Could you obtain such a potion for me?", objectives = "" }
WordHunterWoW_QuestEN[58090] = { title = "Side Effects", description = "Scrapper Minoire's use of enhancers creates unpredictable betting implications. It is quite unhealthy... for our profits!\n\nFor a nominal fee, Au'larrynar can provide you with a \"special\" enhancer that Minoire will not be able to resist: a potion that turns the one who imbibes it into the ultimate combatant... and teaches them a lesson in restraint, as well.\n\nI cannot wait to see Minoire's next match in the arena!", objectives = "" }
WordHunterWoW_QuestEN[58092] = { title = "Halls of Atonement: Your Absolution", description = "The depravity outside of these halls is only a whisper of the true horrors being committed under the Lord Chamberlain's guidance inside the Halls of Atonement.\n\nIf you truly wish to curb this corruption, you must dethrone the imposter that you installed here.\n\nAtone for your own mistake. Kill the Lord Chamberlain, so that we may begin to restore permanent order to this place.", objectives = "" }
WordHunterWoW_QuestEN[58093] = { title = "Our Forgotten Purpose", description = "I have no quarrel with you, Maw Walker.\n\nThe Lord Chamberlain and his abhorrent followers have debased these halls with their perversions of the rituals. Abusing souls and destroying their potential for pathetic mockeries of power.\n\nThe Accuser would never have allowed this. I have heard rumors that you may still be in contact with her. If so, please inform her of the situation here.\n\nShe will bring these depraved dogs to heel.", objectives = "" }
WordHunterWoW_QuestEN[58095] = { title = "Theater of Pain: Help Wanted", description = "Oh, bother--the Lich champion has withdrawn from the contest.\n\nWell, then... It appears we have an opening! Would anyone like to enter in her stead?\n\nPerhaps to increase the odds for their house?\n\nAnyone?\n\nOh, {name}! So kind of you to volunteer. No better way to get experience than to just jump right in unprepared!\n\nRemember, we can't all be winners.", objectives = "" }
WordHunterWoW_QuestEN[58103] = { title = "Pride or Unit", description = "I hope that working with my phalynx has swayed you, {name}.\n\nLet us meet with Nemea. There you can decide whose way of life is superior, and which you would prefer to pursue.", objectives = "" }
WordHunterWoW_QuestEN[58104] = { title = "Show, Don't Tell", description = "As a new champion of the Court, you'll need to be properly introduced to the rest of the Night Fae. And that calls for something big. Bold. Memorable. A demonstration of who you are and where you've come from. Something with... flair.\n\nNormally, we spend ages crafting a masterpiece presentation. But we don't have time for that! We'll just have to improvise.\n\n<Moonberry winks.>\n\nCommune with me so I can pick up the highlights! I'll make sure it's a show to remember!", objectives = "" }
WordHunterWoW_QuestEN[58122] = { title = "For the Horde", description = "What an adventure, {class}!\n\nThere is so much to explore... so much to discover. These are such exciting times!\n\nWe'll show our allies in the Horde the value of having some clever Vulpera around.\n\nPlease meet with the ambassador at the Orgrimmar embassy. \n\nI'll meet you there, {name}!", objectives = "" }
WordHunterWoW_QuestEN[58124] = { title = "Stranger in a Strange Land", description = "Hi. I'm Ambassador Blackguard.\n\nI am honored to welcome you to Orgrimmar, {race}.\n\n<He smiles unconvincingly.>\n\nAs a lifetime of adventure unfolds before you, be assured that... uh...\n\nYou know what? I've been saying this same greeting all day. Enough's enough.\n\nTalk to Chromie on top of the hourglass, then talk to your emissary. Run along.", objectives = "" }
WordHunterWoW_QuestEN[58146] = { title = "For the Alliance", description = "As High Tinker, and leader of both Gnomes and Mechagnomes, I am proud to welcome you to the Alliance!\n\nA world of adventure awaits you beyond the walls of Mechagon City.\n\nWhen you are ready, step on the teleporter. Ambassador Moorgard will be awaiting your arrival at the Stormwind Embassy.\n\nThere will be many potential avenues of advancement available to you.\n\nChoose wisely, improve, and remember to share your data.", objectives = "" }
WordHunterWoW_QuestEN[58147] = { title = "Stranger in a Strange Land", description = "Welcome to Stormwind, {class}. I invite you to explore our fair city. Say, you look like someone who enjoys the night life. We have many popular taverns and a vibrant music scene! \n\nAh, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things!\n\nAfter that, an emissary of the Mechagnomes is waiting to welcome you to the city. Sounds like a busy day for you!\n\nHave a pleasant stay, {name}!", objectives = "" }
WordHunterWoW_QuestEN[58151] = { title = "Minions of N'Zoth", description = "The howling winds that surround us may some day be drowned out, masked by these increasingly dark, yet familiar whispers.\n\nSomething must be done.\n\nEnter the darkness, {name}, and strike down the enemy.", objectives = "" }
WordHunterWoW_QuestEN[58155] = { title = "A Hand in the Dark", description = "Imagine being trapped in a world you didn't know existed--a reality unbeknownst to even yourself.\n\nThoughts, fears, and dark desires cloud the mind, coupled with irresistible temptation.\n\nSo many are lost to the darkness, unable to resist these temptations, but not all.\n\nDo what you can to preserve those that fight against the darkness. We mustn't allow them to fall.", objectives = "" }
WordHunterWoW_QuestEN[58156] = { title = "Vanquishing the Darkness", description = "The darkness grows. The cycle continues.\n\nDo what you can to stay N'Zoth's efforts. If we do not stand against the corruption we may some day find ourselves drowning in darkness.", objectives = "" }
WordHunterWoW_QuestEN[58157] = { title = "Break a Leg", description = "The show is about to begin! You... that's what you're going to wear? Well, I suppose it works.\n\nFor your grand introduction, we will re-enact recent victories and events that took place on Azzinoth. Er, Azeroth. That's where you're from, right?\n\nThe Starlight Company has graciously volunteered to assist us in this production. We've recruited some special guests as well! \n\nDon't worry about the script. This is your story, after all!\n\nJust try not to get too much blood on stage. It's hard to clean.", objectives = "" }
WordHunterWoW_QuestEN[58158] = { title = "The Fourth Wall, er, War", description = "It's time for the next act of your theatrical introduction: the Grand Drama Of Azereth!\n\nAzeroth. Right. All these worlds are hard to tell apart.\n\nHelp set the stage, then come back here. You'll need to play a few other characters before you appear as yourself again.\n\nGet a move on! We have a lot to cover!", objectives = "" }
WordHunterWoW_QuestEN[58159] = { title = "What's My Motivation?", description = "Now for our finale! A thrilling performance of the most recent trials on Azathoth!\n\n<Featherlight checks his notes.>\n\nAzeroth. Whatever. It features an artificial god, a powerful magic ice princess, an infamous queen, and an eldritch abomination of unspeakable terror! Who doesn't love a good drama with a dash of existential horror?\n\nYou're back to playing yourself, so just... do whatever heroes are supposed to do!", objectives = "" }
WordHunterWoW_QuestEN[58160] = { title = "For Queen and Grove!", description = "A stunning performance... in more ways than one.\n\nSo much has transpired on Azeroth in my absence. But there was one dream I did not see portrayed onstage.\n\nI dreamt of Tyrande, engulfed in darkness, twisted by anger and a thirst for vengeance. I witnessed a forbidden ritual, the rise of a new Night Warrior, and a hunt that can end only in tragedy. That too must be real.\n\n<Ysera shakes her head.>\n\nThe Winter Queen awaits you in the Heart of the Forest. We had best be on our way.", objectives = "" }
WordHunterWoW_QuestEN[58161] = { title = "Forest Disappearances", description = "A moment of your time, friend?\n\nA short while ago a sylvar named Partik came seeking the aid of our grove. He said his village was under attack by the gorm and was in danger of crumbling away altogether. I told him we could not spare any soldiers, but their people were welcome to take refuge with us.\n\nHowever, it has been some time since he left and I have not seen or heard anyone from that region since.\n\nCan you go investigate? He came from the northeast.", objectives = "" }
WordHunterWoW_QuestEN[58162] = { title = "Mysterious Masks", description = "The village, my friends, gone. They are no more.\n\nI came back from the nearby grove to find them... like this. Even Lavrash, my best friend! He came at me with only violence in his heart.\n\nThey are all wearing these masks now, and they are not themselves anymore.\n\nPlease, deliver them from this fate. Bring me their masks and perhaps we can decipher this mystery.", objectives = "" }
WordHunterWoW_QuestEN[58163] = { title = "A Desperate Solution", description = "<A well-made, if well-worn, journal catches your eye.\n\nThumbing through the pages, it is clear that this journal once belonged to someone prominent from this group of night fae. The last few pages are torn out of the book.\n\nPerhaps if the rest of the pages were located then Partik could help decipher what happened here.>", objectives = "" }
WordHunterWoW_QuestEN[58164] = { title = "Cult of Personality", description = "Some of my people are still alive! We must rescue them!\n\nThe prisoners are kept in cages throughout the ridge, waiting for this horrible fate to befall them.\n\nPlease, set them free. We cannot let what happened to Lavrash happen to them!", objectives = "" }
WordHunterWoW_QuestEN[58165] = { title = "Cut the Roots", description = "It's just as I feared, friend. The entire village is turned, just like Lavrash.\n\nLewor would have transformed the other elders as soon as possible. They are all strong in their own right. Brave Fiona, clever Bitterfly....\n\nIt pains me to say this, but they must be destroyed. For the good of Ardenweald and the forest, slay our former leaders before they can infect the rest of the land!", objectives = "" }
WordHunterWoW_QuestEN[58166] = { title = "Unknown Assailants", description = "This must be the stone he found. I do not recognize the mark.\n\nYou should bring this to the nearby droman. They are wise and retain much of the knowledge of the forests and the realms beyond. They will know what to do.", objectives = "" }
WordHunterWoW_QuestEN[58167] = { title = "Preventative Measures", description = "Waves of darkness continue their assault on the shores of our world. I am afraid the waters at our feet may soon wash over us. Perhaps it is time for a different approach.\n\nMake your way into the twisted realm and seek out their dark portals. If we are able to slow their advance it might just buy us the time needed to expose a fatal weakness.", objectives = "" }
WordHunterWoW_QuestEN[58168] = { title = "A Dark, Glaring Reality", description = "Their eyes are upon us, {name}, watching every move from the shadows. It is no wonder our efforts thus far have felt... lacking.\n\nThe fault is by no means your own. We should have suspected this was the case long ago.\n\nIf we are to continue our efforts with meaningful expectations we must go undetected.\n\nOur old friend has offered an elixir to aide in exposing our enemy. While there may be a few... unknown side effects, the result provides the imbiber true sight in the darkness.", objectives = "" }
WordHunterWoW_QuestEN[58173] = { title = "What Are They Hiding?", description = "", objectives = "" }
WordHunterWoW_QuestEN[58174] = { title = "All An Aspirant Can Do", description = "I think we can agree that such a reply feels... somewhat hollow.\n\nI choose to take faith that we have done all we can. All of us. I do not know what comes next, but perhaps the path will reveal itself. In the meantime, Pelagos and I will return to Aspirant's Rest for a moment of respite.\n\nWe will meet you there, though there is no need to hurry.", objectives = "" }
WordHunterWoW_QuestEN[58175] = { title = "The Eternal Forge", description = "The Forgelite Prime has taken up the mantle of building our new Crest of Ascension.\n\nNo ordinary tools or materials will do. He will require Phaestus, Genesis of Aeons, Hammer of the First Forgelite. It sits at the shrine to the First Forgelite in the Eternal Forge.\n\nThe Forsworn have taken over this forge to create their own endless centurion army. You must meet Mikanikos at the forge, push back the Forsworn, and retrieve Phaestus for our own uses.", objectives = "" }
WordHunterWoW_QuestEN[58176] = { title = "Stewards of a Feather", description = "You! Maw Walker!\n\nThe forge was bustling. Many forgehands, on task!\n\nThen Forsworn came. Some followed their demands, turned to their side.\n\nBut not all! Yes, rescue forgehands so they can aid us. Work to be done!", objectives = "" }
WordHunterWoW_QuestEN[58177] = { title = "Refining Ego", description = "I will locate Phaestus. In the meantime, task for you!\n\nThe Forsworn use my forge to make their centurion army. Their vile intentions warp the metals we use!\n\nDestroy their centurions, take their parts. Smelt them down in the forge to purify the metals, then return to me.\n\nI need much metal for my plan.", objectives = "" }
WordHunterWoW_QuestEN[58178] = { title = "A Partner for Eternity", description = "Before returning to the Hold, one more thing to do.\n\nDefeat the Forsworn and their centurion army!\n\nThis goliath here can help with just that. My finest creation yet!\n\nI need an extra pair of hands. Yours will do.", objectives = "" }
WordHunterWoW_QuestEN[58179] = { title = "Instruments of Perfection", description = "Mikanikos is no ordinary steward. He is wise! Talented! The smartest of us all!\n\nAlso very particular!\n\nHe cannot work without his tools. The Forsworn scattered them around the forge!\n\nYou need to rebuild Crest? Retrieve his tools!", objectives = "" }
WordHunterWoW_QuestEN[58180] = { title = "Phaestus, Genesis of Aeons", description = "Sika reports the Forsworn are widespread. They not only took over production, but the rise as well!\n\nThey organize their armies from the cliffs, send word back to their leaders.\n\nThey've ransacked our shrine to the First Forgelite and took her hammer. My hammer!\n\nDefeat their commander, retrieve Phaestus. You must go now!", objectives = "" }
WordHunterWoW_QuestEN[58181] = { title = "Building the Base", description = "The Crest is almost complete.\n\nI give you the honor of the final touch.\n\nYou have done much. Please, take Phaestus and give the final blow!", objectives = "" }
WordHunterWoW_QuestEN[58182] = { title = "Dismantling the Opposition", description = "The Forsworn mobilize!\n\nWe cannot allow them to march.\n\nAttune to Bron, share your power with him.\n\nBetween the three of us, we shall destroy this new centurion army!", objectives = "" }
WordHunterWoW_QuestEN[58183] = { title = "Friend to the Forgelite", description = "With Phaestus in hand, we can start building Crest.\n\nLet us return to Elysian Hold. Triumphant!", objectives = "" }
WordHunterWoW_QuestEN[58184] = { title = "Antiquated Methodology", description = "You possess the correct mindset for retraining a phalynx. I believe you could find great success here.\n\nBefore you commit, I implore you to go across the hill and introduce yourself to my rival, Nemea. She believes that her unreasonable, free-willed larions are better partners than my perfect phalynx.\n\nExperience her lifestyle so that you may know how much greater my work is.", objectives = "" }
WordHunterWoW_QuestEN[58185] = { title = "Success Without Soul", description = "The larions seem to truly enjoy your company, Andira most of all.\n\nI hope you've come to understand and appreciate the nuance of working with a beast with free will.\n\nNow you must spend time with Pelodis, down the hill. His phalynx may be effective, but working with them only brings hollow satisfaction.\n\nI am sure working with the phalynx will only strengthen your appreciation of larions.", objectives = "" }
WordHunterWoW_QuestEN[58208] = { title = "Brace for Impact", description = "That's it for warming up. You and the other new recruits are a promising bunch, I'll tell you that much.\n\nHold on... what's that sound? I think something big is headed our way!", objectives = "" }
WordHunterWoW_QuestEN[58209] = { title = "Stand Your Ground", description = "I hope this rain isn't a bad omen... this is supposed to be a simple rescue mission.\n\nYou'll be sparring with me today. We have to make sure you can handle yourself once we make landfall.\n\nLet's see what you've got!", objectives = "" }
WordHunterWoW_QuestEN[58211] = { title = "Pumped Up", description = "When this necropolis collapsed, plenty of its parts got submerged in the riverbed flowing just outside. I hope you're really dedicated to fixing this place, because we're gonna dredge those parts back up!\n\nTake this pump. If you find any places bubbling in that sludge, that's a good sign parts will be there!\n\nJust be careful with whatever you pull up! You could face some resistance.", objectives = "" }
WordHunterWoW_QuestEN[58214] = { title = "Urgent Care", description = "Excellent timing, {name}.\n\nKelsey Steelspark has been sending communications to the capital cities looking for aid.\n\nMekkatorque's condition is quite dire and time is of the essence.\n\nHurry to Boralus Harbor, she will be watching for you.", objectives = "" }
WordHunterWoW_QuestEN[58229] = { title = "A Rallying Cry", description = "Our lands have been infested by the minions of the Old Gods. They strike at every front, even assailing the very minds of our soldiers.\n\nOur forces cannot handle this for long. We must strike a decisive blow to try to salvage some of their morale.\n\nFind the biggest, slimiest, tentacle-faced monstrosities that you can and bring them down. My men will rally to your example.", objectives = "" }
WordHunterWoW_QuestEN[58230] = { title = "Blind the Eyes", description = "Strange forces have been interfering with my visions of late. The ever-watching eyes pierce through the veil, shattering my clairvoyance.\n\nThe eyes of our enemy peer into our very souls and pierce our minds. We must rip them out, if we truly wish to be rid of the curse on this land.", objectives = "" }
WordHunterWoW_QuestEN[58231] = { title = "Wisdom From Madness", description = "In my visions I hear... voices...\n\nTheir words are nonsense, but over time patterns arise. I believe there is something important behind what these voices say, but I have yet to decipher a word.\n\nWe will need to learn from the source. Find any writings you can among the cultists who travel with these dark creatures. Their ramblings may be the key to understanding the message beneath this madness.", objectives = "" }
WordHunterWoW_QuestEN[58232] = { title = "Order Among Chaos", description = "It has been a long time since the tol'vir have squared off against the forces of an Old God, so our tactical knowledge of their forces is limited.\n\nHowever, one tenet of combat always holds true -- striking down those that issue the orders will weaken the foe much greater than the rank and file. \n\nI have observed that the larger faceless minions act as commanders of the Old Gods' forces. Silence them, and perhaps we can sow a different kind of chaos in their ranks.", objectives = "" }
WordHunterWoW_QuestEN[58233] = { title = "Twisted Corruptors", description = "While the fleshbeasts that accompany the invading forces appear to be no more than a nuisance, they carry within themselves a deep connection to the corrupting powers of the Old Gods. \n\nLike a pestilence, they spread the N'Zoth's corruption wherever they tread, slowly twisting the very land to their form.\n\nThey must be eradicated.", objectives = "" }
WordHunterWoW_QuestEN[58234] = { title = "Questionable Sourcing", description = "My clairvoyance provides a great strategic asset to the people of Ramkahen. However, the potency of my visions of late has proven taxing to my health.\n\nI have devised a tonic that may serve to dull the harm these visions cause, but it will require the coalesced essence of the Old Gods' corruption.\n\nIf you could retrieve some samples of this for me, it could prove invaluable in our efforts.", objectives = "" }
WordHunterWoW_QuestEN[58235] = { title = "Anchors of the Black Empire", description = "This invasion struck us without warning, with structures reminiscent of the Black Empire materializing out of nothing, pouring out the forces of the Old Gods. We have no idea how they came to be or where they came from.\n\nHowever, whenever a new structure appears, it is preceded by malefic obelisks. We believe these obelisks act as anchors to usher in more of the Old Gods' forces.\n\nIf we truly wish to stem the tide of this invasion, we must destroy the obelisks.", objectives = "" }
WordHunterWoW_QuestEN[58236] = { title = "Symbolic Destruction", description = "The cultists that follow this dark legion befoul our lands with symbols of the tyrants they follow. \n\nTheir mindless followers flock to these banners, worshipping them as unholy idols.\n\nBurn them down, and cleanse their taint from our lands.", objectives = "" }
WordHunterWoW_QuestEN[58237] = { title = "Cleansing Uldum", description = "Every moment that N'Zoth's forces remain in Uldum, his corruption seeps further into the land itself.\n\nEven if we were to drive back his minions, the damage he has done to Uldum may be irreversible. \n\nWe must seek out his corruption where it festers and eliminate it.", objectives = "" }
WordHunterWoW_QuestEN[58238] = { title = "Lost and Tormented", description = "Our citizens here in Ramkahen have managed to escape the brunt of N'Zoth's assault. \n\nOur brothers in the Lost City were not so fortunate. Those not immediately slain have been held captive only to be tortured by N'Zoth's minions.\n\nI know that you will be taking the fight to N'Zoth's forces. If you can free our allies as well, Ramkahen will be in your debt.", objectives = "" }
WordHunterWoW_QuestEN[58239] = { title = "Lessons in Brigandry", description = "The Wastewanders have spent many generations as brigands, whether on land or sea. Though we have decided to hang up that life for a chance at a more peaceful existence, we have not forgotten the lessons we've learned in those days.\n\nOne such lesson I feel is particularly relevant now -- when faced with a superior opponent, it often helps to use their weapons against them.\n\nFind their hidden caches and take whatever you can carry. You may just find something that can turn the tide of this battle.", objectives = "" }
WordHunterWoW_QuestEN[58260] = { title = "Queens And Future Kings", description = "A swarm of marrowbore queens have been laying eggs atop the ruins of our house. We may be able to use this to our advantage.\n\nWith Twigin's help, eliminate the queens and recover larvae from the eggs.\n\nI have a plan for the larvae that may allow us to use the marrowbore to our advantage.", objectives = "" }
WordHunterWoW_QuestEN[58264] = { title = "Wake Up, Get Up, Get Out There", description = "They need your help!\n\nNot all of the faeries have been turned yet. Some remain prisoner, but they have these masks on their faces....\n\nYou've got to help them! I'm not strong enough to pry off the masks, but you could! You could stop the guards from getting us too!", objectives = "" }
WordHunterWoW_QuestEN[58265] = { title = "Blooming Villains", description = "Something stinks, traveler. The air to the west is rotten with malice.\n\nShimmerbough has long been a peaceful way station along the Path of Rebirth. The faeries there delight in revelry and celebration. But now their glade has fallen silent.\n\nScouts bring reports of the strange masked night fae. I know little other than that they are a threat.\n\nFor the sake of Ardenweald, they must be eliminated. Slay any you encounter.", objectives = "" }
WordHunterWoW_QuestEN[58266] = { title = "Break It Down", description = "I've seen the ritual. It's... terrifying.\n\nBut the altars seem to be the key. If only I had my pyrotechnic powder, I could blast them to bits!\n\n<Primrose is silent for a moment, then takes a deep breath.>\n\nIf you could get the powder and guard me, we could blow up those altars.\n\nI stashed as much as I could in our dwellings. They don't seem to care any more.\n\nYou don't have wings, but a pinch of faerie dust should work for a short time.\n\nLet's do this before I change my mind!", objectives = "" }
WordHunterWoW_QuestEN[58267] = { title = "Beneath the Mask", description = "It's time to end this.\n\nWhen I first hid, I saw a dark shape on the northeast platform. I think that's their leader.\n\nNow that they can't perform any more rituals, we should be able to scare them off.\n\n<Primrose pauses for a moment.>\n\nI... I just wanted to say thank you. I never could have done this without your help. Now, let's drive out this enemy and retake the village!", objectives = "" }
WordHunterWoW_QuestEN[58268] = { title = "Take the High Ground", description = "The commander of the constructs, General Alver, is a master tactician. A frontal assault has no chance of victory against him. It will be a bloodbath.\n\nHis forces have flanked us and secured the high ground. From that position, he can rain destruction upon us unopposed.\n\nWe will take the ridge from him before that can happen.", objectives = "" }
WordHunterWoW_QuestEN[58272] = { title = "Words Have Power", description = "The Stoneborn Rebels have left behind recruitment pamphlets. Recovering these for the venthyr may earn some much needed favor.", objectives = "" }
WordHunterWoW_QuestEN[58273] = { title = "Servant of N'Zoth", description = "{class}...\n\nI have watched you... I have felt your bloodlust. \n\nBut you serve false prophets... the Horde is an illusion... I am a god!\n\nProve to me you are worthy of my gift... kill those who are to betray you...\n\nKill... the Horde!", objectives = "" }
WordHunterWoW_QuestEN[58274] = { title = "Servant of N'Zoth", description = "{class}...\n\nI have watched you... I have felt your bloodlust. \n\nBut you serve false prophets... the Alliance is an illusion... I am a god!\n\nProve to me you are worthy of my gift... kill those who are to betray you...\n\nKill... the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[58277] = { title = "Dark Deceivers", description = "The Old Gods have many faceless minions at their disposal, but none so deceiving as the ones they call k'thir.\n\nThough not nearly as imposing as their brethren, the k'thir manipulate in the shadows, bending the wills of men and even reality itself.\n\nWe must not allow their machinations to go unchecked.", objectives = "" }
WordHunterWoW_QuestEN[58279] = { title = "Quartermaster's Bounty", description = "To defeat the enemy, you will need to keep your equipment in peak condition. If you have been unable to acquire more powerful arms, I can requisition from the quartermaster on your behalf.", objectives = "" }
WordHunterWoW_QuestEN[58281] = { title = "Ancient Armaments", description = "Fighting a war on several fronts has taken its toll on our supplies. Our blacksmiths cannot repair and replace our soldiers' armor quickly enough, which is leaving us ill-equipped to face so many foes.\n\nThough the Amathet's armor is ancient, it is titan-forged and formidable. If we were able to salvage any, it could prove very useful to our defensive efforts.\n\nCan you help?", objectives = "" }
WordHunterWoW_QuestEN[58282] = { title = "Down From the Sky", description = "The archers of Ramkahen are highly skilled, but the bows of the Amathet have the advantage of range. This makes our incursions into their territory highly dangerous.\n\nYou have a knack for fighting behind enemy lines. If you could thin out their ranks, it could provide us an opportunity to push their lines back for once.\n\nWill you help?", objectives = "" }
WordHunterWoW_QuestEN[58283] = { title = "Blind Leading the Blind", description = "The Sun Priests are an ancient order for the tol'vir who have walked among all of the tribes. \n\nThose that follow the Amathet, however, have twisted our beliefs and weaponized them to justify their crusade against Ramkahen. Their soldiers follow them blindly, never questioning.\n\nThey must be stopped.", objectives = "" }
WordHunterWoW_QuestEN[58284] = { title = "Writs of the Sun King", description = "Very little is known about the Sun King that leads the Amathet. Our observations suggest that those closest to him are the \"Suntouched,\" a unique caste of solar magic practitioners.\n\nI would like very much to learn more about this Sun King but, unlike some members of the Explorers' League, I'm not willing to risk the lives of my researchers to do so. \n\nYou seem to be able to hold your own, though. If you happen upon any records about the Sun King, I'd gladly take them off your hands.", objectives = "" }
WordHunterWoW_QuestEN[58285] = { title = "Unearthed Artifacts", description = "Ever since the Amathet came out of their tombs, they've been busy unearthing titan relics from the surrounding areas. \n\nI'm not sure what they intend to do with them or if they're just hoarding it so we can't have them. Sufficed to say the Explorers' League would love to study some of what they found!\n\nOf course, we can't get anywhere close to them without the Amathet trying to stick an axe in us, but that's not a problem for you, is it? \n\nCare to help?", objectives = "" }
WordHunterWoW_QuestEN[58286] = { title = "Far From Home", description = "The Amathet's conquest of eastern Uldum was sudden, and we were unable to reach some of our farthest settlements in time. \n\nFortunately, many of the tol'vir who lived in the conquered territories were not killed, instead being put to work under the Amathet's whip. \n\nWe must take any opportunity we can to free them and return them to their homes.", objectives = "" }
WordHunterWoW_QuestEN[58287] = { title = "A Smashing Plan", description = "Reports from my scouts mention various idols and monuments that the Amathet use to channel their solar magic. \n\nI don't know exactly what they're up to, but we should take away any possible advantage they have. So, I want you to go over there, and break anything that looks remotely magical.\n\nJust don't tell the Explorers' League. I'll never hear the end of it.", objectives = "" }
WordHunterWoW_QuestEN[58288] = { title = "The Sun King's Chosen", description = "On the surface the Amathet appear to be unwavering, but all soldiers have their breaking point. We need to send a message to their forces that we are not to be trifled with.\n\nSeek out the strongest of their numbers and bring them down in front of their eyes. \n\nWe will show them the strength of Uldum!", objectives = "" }
WordHunterWoW_QuestEN[58289] = { title = "Guarded Secrets", description = "From what we know about the Amathet, they must've been locked away in their tombs for thousands of years. Just think of what we could learn from them!\n\nOf course, that would be a lot easier if they weren't trying to kill us. \n\nIf you happen upon any caches of Amathet relics in your travels, let me know. I'd love to see what sort of mysteries they contain!", objectives = "" }
WordHunterWoW_QuestEN[58290] = { title = "Champions of the Amathet", description = "The soldiers of Ramkahen are hearty and reliable. \n\nI would stand them up against any footman of the Amathet, but some of their higher-caste fighters are too much for even our toughest to handle.\n\nI don't think they'd be a problem for you, though. It would be a boon to our defense efforts if you could handle them while my soldiers engage the rank and file.", objectives = "" }
WordHunterWoW_QuestEN[58291] = { title = "Encroaching Poachers", description = "The Wastewanders used the pelts of the local hyenas to construct our armor. Unfortunately since the Amathet arrived, their hunters have overrun our normal hunting grounds.\n\nWe need those pelts, and will pay handsomely for them. Either take them from the hunters or skin the hyenas yourself, if you have the skill.", objectives = "" }
WordHunterWoW_QuestEN[58297] = { title = "Faceless Mask of the Daredevil", description = "The hunter never sought to lead yet sought a challenge in life at every turn. He directed his allies with a deft hand and never shied from diving in to the melee himself. The prowess he showed made him as well as my other minions much more deadly. Return this mask to the altar of the Daredevil to challenge your own resolve in battle as your foes attacks cut even more deep.", objectives = "" }
WordHunterWoW_QuestEN[58314] = { title = "Faceless Mask of the Burned Bridge", description = "The displaced warrior is always on uneasy footing, especially one who is removed from her home world. The void makes this unsteadiness a reality where one step can lead into the abyss or drain you to your core.", objectives = "" }
WordHunterWoW_QuestEN[58316] = { title = "Faceless Mask of the Dark Imagination", description = "These magi, twisting their magic to manipulate and conquer the world. Imagining greater power, they tread along the lines of the Void's domain. In these pursuits, this magi came to the realization that in the depths of one's imagination lie truly dark and terrible things.", objectives = "" }
WordHunterWoW_QuestEN[58317] = { title = "Faceless Mask of the Pained", description = "Trading in secrets, trading in lies, operating on the fringes are all the Spymaster knows. His lost passions, lost loves are all gone, crushed under his own duty and loyalty to the crown. Nothing is left, nothing but the pain. Pain is an apt tutor and tool and one in which the void knows intimately. Return my mask if you dare to feel the many forms pain can take.", objectives = "" }
WordHunterWoW_QuestEN[58318] = { title = "Faceless Mask of the Long Night", description = "The endurance needed to make it this far is extraordinary and the feat of a long experienced adventurer. Yet, the longest night is nigh and with it our ultimate conquest. Those that fight the coming of eternal twilight know only futility, for in the Longest Night they will be on the edge of sanity forever.", objectives = "" }
WordHunterWoW_QuestEN[58321] = { title = "Uncommon Core", description = "Our scouts have reported that the Amathet are constructing new titanic watchers. \n\nWe had long thought this art was lost to the sands of time. It would appear we were mistaken.\n\nI needn't tell you what a boon it would be to have the aid of watcher constructs in our battles for Uldum. We must unlock the secrets of their construction!\n\nThe power of a titanic watcher lies in its core. I ask that you bring one to me, so that our artificers might divine its construction.", objectives = "" }
WordHunterWoW_QuestEN[58325] = { title = "Watcher Emil", description = "Watcher Emil is my trusted overseer of the catacombs. Before I was thrown into the Maw, half of the mirror was entrusted to him.\n\nI had him stationed at the Catacombs of Regret. But I do not know where in the sprawl he is.\n\nThere is a guard station near the entrance to the catacombs. Start the search there. There is an officer who can help us, I--I can't remember who. That is, provided they survived this whole mess.\n\nYou must find Emil at once. We may not have much time.", objectives = "" }
WordHunterWoW_QuestEN[58326] = { title = "Combing the Catacombs", description = "When the anima drought began, our defenses began to fail. \n\nOur guards, weakened by the lack of anima, became overrun as the sinstones this land is built upon rose up around us. Not to mention the manifestations of the souls who can no longer be tended to are running wild.\n\nYou may be able to help us, mortal. Please, we can barely hold this position... and I don't know for how much longer.", objectives = "" }
WordHunterWoW_QuestEN[58327] = { title = "Snacks for Stonehead", description = "<Stonehead has amassed a wide variety of half-eaten oddities.\n\nHe'd certainly appreciate you bringing some new, creative snacks for him to try.>", objectives = "" }
WordHunterWoW_QuestEN[58328] = { title = "TBD", description = "Bribe Boulderfoot", objectives = "" }
WordHunterWoW_QuestEN[58337] = { title = "Break Out", description = "Our reinforcements never came, leaving us unable to tend to the souls here. They have begun to break out of their cells. Many of them are not ready for the next step in the process.\n\nTake these iron chains. They can be used to rein them under your control. \n\nOnce you have a soul bound, you can return them to any intact cage you can find.", objectives = "" }
WordHunterWoW_QuestEN[58338] = { title = "[NYI] Sinstone Mining", description = "", objectives = "" }
WordHunterWoW_QuestEN[58351] = { title = "The Hills Have Eyes", description = "The other houses have yet to launch a full scale assault, but do not mistake their cowardice for incompetence.\n\nAny tactician worth their weight in maldracite knows the value of espionage. I suspect that the agents of our foes skulk within our own ranks as we speak.\n\nTake one of my hounds. It will know our enemies by their scent. Once the pests have been discovered, exterminate them.", objectives = "" }
WordHunterWoW_QuestEN[58372] = { title = "Lead the Way", description = "We must move now. That won't be the last assassin we face.\n\nI can provide some cover of darkness, but mind that the spell is not infallible.\n\nEnough talking. The Curator needs us and my mirror shard to get to her as soon as possible.", objectives = "" }
WordHunterWoW_QuestEN[58373] = { title = "Ny'alotha: MOTHER's Guidance", description = "Ny'alotha does not obey the rules of space and time, and we may be able to use this to our advantage.\n\nMOTHER theorizes that if we obtain specific objects from N'Zoth's chosen, we can utilize them to bend space and expedite our passage here in the future. Though, it is doubtful they will relinquish these items willingly.", objectives = "" }
WordHunterWoW_QuestEN[58374] = { title = "Ny'alotha: MOTHER's Guidance", description = "Ny'alotha does not obey the rules of space and time, and we may be able to use this to our advantage.\n\nMOTHER theorizes that if we obtain specific objects from N'Zoth's chosen, we can utilize them to bend space and expedite our passage here in the future. Though, it is doubtful they will relinquish these items willingly.", objectives = "" }
WordHunterWoW_QuestEN[58375] = { title = "Ny'alotha: MOTHER's Guidance", description = "Ny'alotha does not obey the rules of space and time, and we may be able to use this to our advantage.\n\nMOTHER theorizes that if we obtain specific objects from N'Zoth's chosen, we can utilize them to bend space and expedite our passage here in the future. Though, it is doubtful they will relinquish these items willingly.", objectives = "" }
WordHunterWoW_QuestEN[58382] = { title = "Someone Worth Saving", description = "Are you familiar with Kael'thas Sunstrider? He was a powerful leader on your world for a time.\n\nThe immense anima of that lingering power attracted the Master's attention, to the eternal detriment of Kael'thas's soul.\n\n<The Accuser's lip curls in disgust.>\n\nEvery soul deserves a chance at redemption, {name}.\n\nIf you do not believe that, believe me when I say that this soul is immensely powerful and still at risk of self-destruction.\n\nRelease him so that we may walk his path of redemption together.", objectives = "" }
WordHunterWoW_QuestEN[58383] = { title = "The Many Sins of Kael'thas Sunstrider", description = "Kael'thas Sunstrider was on the verge of destruction when we rescued him from Castle Nathria.\n\nDenathrius had infused Kael'thas with unimaginable amounts of anima, each bit carrying with it the sins of others.\n\nIt made his soul strong, but unstable--confused and pushed to the edge of its own existence.\n\nTrust me when I tell you that Kael'thas Sunstrider has enough sins of his own.\n\nAssist me in identifying which of the many sins heaped on his soul are truly his burden to bear.", objectives = "" }
WordHunterWoW_QuestEN[58384] = { title = "Dredgers Left Behind", description = "When Prince Renathal fled Darkwall Tower, he was forced to leave many people and belongings behind.\n\nThe powerful relics and weapons were long ago carted off to the Master's lair. But the Prince's dredgers were forced to stay and serve the Master's traitorous lackeys here instead.\n\nYou will be a welcome sight to them--a sign that the Prince has not forgotten them.\n\nIf they are willing to fight, help them escape and I will ensure they are brought safely to Sinfall.", objectives = "" }
WordHunterWoW_QuestEN[58385] = { title = "Learning to Sacrifice", description = "Kael'thas remains unstable in his current state, bursting at the seams with anima.\n\nHe is also an arrogant, selfish moron.\n\nThankfully, I have a lesson that can address both concerns.\n\nTrue leaders sacrifice of themselves to empower those under their care.\n\nMany stoneborn and gargon, including the Prince's own pet, were left dormant in Darkwall by the Master's forces.\n\nOrder Kael'thas to forfeit portions of the anima trapped inside of him to reanimate those dormant stoneborn to aid us.", objectives = "" }
WordHunterWoW_QuestEN[58386] = { title = "Use My Strengths", description = "<Kael'thas looks around to make sure the Accuser is out of earshot.>\n\nThe Accuser is so obsessed with my negative traits that she has failed to see my strengths!\n\nEven in death, I am incredibly powerful. The Accuser herself said that Denathrius infused me with anima to make me strong.\n\nLet us use that strength for good while I have it!\n\nThis tower once belonged to the Prince of this realm, correct? Let us find his usurper and gain vengeance!\n\nVengeance is a virtue I have always appreciated.", objectives = "" }
WordHunterWoW_QuestEN[58387] = { title = "We Each Must Carry Our Own Sins", description = "The Master chained Kael'thas's sinstone to his soul via a dark, corruptive process that left Kael'thas scarred and overburdened.\n\nHe bears the weight of not only his own sins, but the sins of countless other souls on his back. That would be a crushing burden for even the most noble of souls--which Kael'thas is not.\n\nLet us hope your time with Kael'thas has prepared his soul for my ritual.\n\nI must break that cursed burden by removing the foreign sins from his soul, or else we'll lose him forever.", objectives = "" }
WordHunterWoW_QuestEN[58388] = { title = "Blackbale Betrayers", description = "When the Prince made his final stand at Darkwall Tower, he called for aid from the many noble houses here in the Chalice District.\n\nNone came.\n\nMost simply avoided the conflict, out of self-preservation. A shameful, but understandable choice.\n\nHowever, one house took action. Lord Blackbale replied with cruel mockery and sent his stoneborn to aid the Master's armies instead.\n\nPrince Renathal has not forgotten that betrayal.\n\nKael'thas seeks vengeance? Let him have some. Start with the stoneborn.", objectives = "" }
WordHunterWoW_QuestEN[58389] = { title = "Maldraxxian Weapons", description = "<The weapon you find seems unlike those wielded by most venthyr, yet the marks it bears are unmistakably familiar...\n\nIt would be wise to seek out more such weapons and bring them to the Accuser.>", objectives = "" }
WordHunterWoW_QuestEN[58391] = { title = "Reconnaissance... for my, uh, Recovery", description = "It appears I am at your mercy once more, {name}.\n\nFar be it from me to tell you the best way to absolve my sins as the Accuser insists we do.\n\nHowever...\n\nIn that note, the Tithelord arranged a meeting with his contact in Darkhaven. Do you know where that is?\n\nIf you do, we could investigate, gather more information, and present that information to the Accuser and Prince Renathal.\n\nI imagine that would be quite useful to them.\n\nAnd a very selfless act of assistance on my part, do you not agree?", objectives = "" }
WordHunterWoW_QuestEN[58392] = { title = "Death's End Destruction", description = "It appears we have discovered a common enemy to pursue, {name}.\n\nWherever that necromancer ran off to is no doubt filled with traitors, undead armies from another realm, and at least one lich...\n\nIt cannot be a sin to kill such as these. To demolish the camp of these invaders and betrayers must be a virtue.\n\nA virtue I crave. Let us pursue it with haste.", objectives = "" }
WordHunterWoW_QuestEN[58393] = { title = "Strategic Executions", description = "I confess that I do not comprehend the full array of potential consequences wrought by the Tithelord's anima-sharing arrangement.\n\nBut I am very aware of the dangers posed by a lich with access to power.\n\nI am also very aware that resolving this situation is important to the Accuser, which, given my current situation, makes it important to me.\n\nWe should eliminate the muscle behind the anima transfer logistics. Without that, the shipments will halt.", objectives = "" }
WordHunterWoW_QuestEN[58394] = { title = "Lady Ouix'Ara", description = "Can you feel it? The chill in your bones... the energy... power...\n\nShe's here. The lich.\n\nTake me to her. I must speak with her, in my own way.", objectives = "" }
WordHunterWoW_QuestEN[58395] = { title = "Enough Vengeance For One Day", description = "After the Sunwell's destruction and the near extermination of my people, I vowed to claim vengeance upon Arthas and Kel'Thuzad. But I needed power to see that happen, and to seize that power I...\n\n<Kael'thas grows quiet.>\n\nI... am ready to return to Sinfall. I must recover my strength for what lies ahead.\n\nAs the Accuser is so fond of reminding me, I have... much to ponder.\n\nLet us inform our allies of the enemy we have revealed.", objectives = "" }
WordHunterWoW_QuestEN[58396] = { title = "Interrogate Baddies", description = "TBD", objectives = "" }
WordHunterWoW_QuestEN[58397] = { title = "Steal Supplies", description = "TBD", objectives = "" }
WordHunterWoW_QuestEN[58400] = { title = "Break the Barrier", description = "TBD", objectives = "" }
WordHunterWoW_QuestEN[58401] = { title = "Ooze Kills", description = "TBD", objectives = "" }
WordHunterWoW_QuestEN[58402] = { title = "Destroy Siege Weapons", description = "TBD", objectives = "" }
WordHunterWoW_QuestEN[58403] = { title = "Supercharge Kael'thas", description = "TBD", objectives = "" }
WordHunterWoW_QuestEN[58404] = { title = "Kill Elites in Phase", description = "TBD", objectives = "" }
WordHunterWoW_QuestEN[58405] = { title = "Find KT's Phylactery", description = "TBD", objectives = "" }
WordHunterWoW_QuestEN[58406] = { title = "Mirror to Maldraxxus", description = "I've received word that Laurent's made substantial progress with his repairs. \n\nOnce the mirror has been restored, we can realize our efforts to recover the final medallion. \n\nHead to the ramparts and see if his work is near completion.", objectives = "" }
WordHunterWoW_QuestEN[58407] = { title = "The Medallion of Dominion", description = "Laurent speaks the truth. We must not delay. \n\nThis mirror is our entryway into the heart of Maldraxxus. \n\nTogether with Kael'thas, we will find Kel'Thuzad and rip the Medallion of Dominion from his undeserving grasp.", objectives = "" }
WordHunterWoW_QuestEN[58420] = { title = "A Foul Annoyance", description = "The Hozen are opportunistic and weak. It does not surprise me that some of their kind have thrown their lot in with the Old Gods.\n\nWe should take care of them before they become more than a nuisance.", objectives = "" }
WordHunterWoW_QuestEN[58421] = { title = "Special Access", description = "Mateo will have the other mirror shard we need to access the medallion. He is likely in my former manor in Archivam.\n\nIt is guarded by Nourman, a loyal dredger. Nourman is ever committed to his duties, regardless of the situation.\n\nMateo likely maintained the same rule to access the manor--possess the fangs of those granted access. If you collect the fangs of the commanders of his operation, Nourman will let you pass.", objectives = "" }
WordHunterWoW_QuestEN[58422] = { title = "Mark of the Conquerors", description = "The invading minions of N'Zoth lay claim to lands they are not entitled to. \n\nThe Vale will not be conquered while even one of the Rajani still draws breath.\n\nBurn down their banners as a reminder of this.", objectives = "" }
WordHunterWoW_QuestEN[58423] = { title = "The Strongest Among Them", description = "You have shown great strength in your conquests, but new enemies assail the Vale with each day.\n\nSeek out the strongest that our foes have sent forth, and bring them down for their allies to see.", objectives = "" }
WordHunterWoW_QuestEN[58424] = { title = "An Eye for an Amulet", description = "Archivam has been overrun by Denathrius's lackeys. \n\nWe must eliminate these intruders. From the look of things, they have resorted to tearing Archivam down to the core for any evidence of the Curator's medallion.\n\nGo, {name}. Stop them before it is too late.", objectives = "" }
WordHunterWoW_QuestEN[58426] = { title = "In the Shadow of our Failures", description = "I will personally tend to the absolution of Kael'thas Sunstrider. His current state and trauma requires nothing short of perfect intervention and instruction to correct.\n\nI would welcome your assistance in this. I sense a bond between Kael'thas and yourself. I think your presence may help inspire him down a better path.\n\nIf you're willing, meet us at Darkwall Tower.\n\nPrince Renathal suffered a great defeat there once. Perhaps a better fate will be found this time.", objectives = "" }
WordHunterWoW_QuestEN[58428] = { title = "Crypt Crashers", description = "There's one more thing I forgot to mention. Apologies, {name}.\n\nThe mirror, once complete, is inherently cursed by design. \n\nYou need to locate my Death Lotus Powder. It was in one of the crypts in Archivam... I cannot recall which one. \n\nI'm afraid you may have to brute force this one, {name}.", objectives = "" }
WordHunterWoW_QuestEN[58431] = { title = "Pool of Potions", description = "I shall teach you about the Pool of Potions. The potions we create here have a variety of beneficial effects.\n\nKill the slimes in the surrounding ruins and collect the Oozing Ingredient: Viscous Oil they may drop. Each slime can produce a great quantity of oil, so you'll only be able to carry one slime's worth at a time. \n\nDeliver this oil to the Pool of Potions and toss it in.", objectives = "" }
WordHunterWoW_QuestEN[58432] = { title = "Something Old, Something Used", description = "Want new luckydos? Chordy is best at finding luckydos!\n\nWant to go look around with Chordy?\n\n<Chordy looks at you pleadingly with his large eye.>", objectives = "" }
WordHunterWoW_QuestEN[58433] = { title = "Anima Attrition", description = "This is not some simple raid or protest. These stoneborn mean to steal the anima this convoy was carrying.\n\nThat anima was destined to be tithed to the Master. There is a drought on and we cannot let these vagabonds and miscreants steal our hard-earned anima.\n\nRecover the tithe if you can and I will see to your notoriety.", objectives = "" }
WordHunterWoW_QuestEN[58435] = { title = "Heritage of the Vulpera", description = "The Horde has come to truly value the Vulpera, thanks to your efforts. \n\nYou are the most... vulperan vulpera that I know!\n\nVisit me in the Vulpera Hideaway in Vol'dun. Kiro had me put together a small memento in appreciation of your efforts.", objectives = "" }
WordHunterWoW_QuestEN[58436] = { title = "Heritage of the Mechagnome", description = "{name}, we could not be more pleased with your progress. You represent us well with the Alliance.\n\nReturn to Mechagon City at your earliest convenience. Waren has created a gift for you.", objectives = "" }
WordHunterWoW_QuestEN[58440] = { title = "Mirror, Mirror...", description = "We have what we need to get you through, {name}.\n\nMy medallion lies on the other side of the mirror. Once through, my medallion will be there... somewhere. \n\nPlease be careful. My mind may be weakened, but I do remember working with the Accuser to protect the crypt's interior.\n\nI should be able to tell you everything about this place, but I am afraid that just is not the case anymore.", objectives = "" }
WordHunterWoW_QuestEN[58443] = { title = "Continued Care of Kael'thas", description = "Kael'thas is free from the twisted corruption of the Master, but he is not truly \"free\" yet.\n\nHe carries more than enough burdens from his own sins to condemn him to the Maw.\n\nWe must be vigilant in encouraging and forcing him to atone for his mistakes. If he cannot right the many wrongs of his mortal life, he will be doomed forever.\n\nYou are having a positive effect on him. Please, accompany us down to the Chalice District for his next lesson.", objectives = "" }
WordHunterWoW_QuestEN[58444] = { title = "Return to Sinfall", description = "{name}, we must get the medallion back to Sinfall as soon as possible. \n\nWe saw how fierce Mateo's forces were, just imagine what destruction Denathrius will bring if we linger around.\n\nI will return to Absolution Crypt in a moment. With all the work you've done, I can begin to resume my duties.\n\nMy first order of business will be to recruit a new sinkeeper. Oh how I dread interviews...", objectives = "" }
WordHunterWoW_QuestEN[58445] = { title = "Containing the Night", description = "It is fortunate you are here, {name}.\n\nThiernax believes he may know how to save Tyrande from the fate he himself suffered as the Night Warrior.\n\nLet us hear what he has to say.", objectives = "" }
WordHunterWoW_QuestEN[58446] = { title = "Tracker Tracking", description = "We will require the aid of an expert tracker if we are to find the other Night Warriors.\n\nThe Wild Hunt possesses legendary skills in such matters. No quarry can elude them.\n\nSpeak with Lord Herne. With one of his hunters at your side, your search will surely be successful.", objectives = "" }
WordHunterWoW_QuestEN[58447] = { title = "Monster Hunting", description = "Make ready, {class}. We hunt a worldeater.\n\nThey are the largest of devourers, massive beings who can drain anima from an entire region within a matter of moments. \n\nWith Ardenweald suffering from the drought, a worldeater's presence could prove disastrous.\n\nStill, we must not rush into battle without first understanding our prey. Tread the Elder Stand with me. Even creatures such as these leave spoor.\n\nKnowing our quarry will be what allows us to slay it.", objectives = "" }
WordHunterWoW_QuestEN[58449] = { title = "Acid Reflux", description = "We will need to be properly prepared before we can face Voras.\n\nThe digestive juices of Ardenweald's gorm dissipate the anima in their food. Ingesting them causes devourers no small discomfort.\n\nFor a beast of that size, we will need a lot of it to have any effect. There should be plenty of gorm in the hive to the east.\n\nLong ago, an artisan gave me a tool that he said would be useful against the gorm, should I ever need it. You may borrow it.", objectives = "" }
WordHunterWoW_QuestEN[58450] = { title = "Anima Instincts", description = "Voras is clearly content to roam the Elder Stand. We will need a way to lure it to us once we are ready to fight.\n\nDid you notice the wildseeds in the clearing where we spotted it? Voras must be feasting on the concentrated anima contained within them.\n\nThere should still be some expended wildseeds from before the drought in the Gormhive. Let us create bait too tempting for Voras to ignore.", objectives = "" }
WordHunterWoW_QuestEN[58451] = { title = "Voras, The Realm Eater", description = "We have everything we need, {name}. Now only the kill remains.\n\nWe set the lure, weaken the beast, and land the final blow.\n\nHunting is a battle of wills. Life or death hangs in the balance for all of us. It has always been this way, on Azeroth as in Ardenweald.\n\nLet the hunt begin.", objectives = "" }
WordHunterWoW_QuestEN[58452] = { title = "Tracking the Shadows", description = "The quarry has been slain, and my duties fulfilled. The tirnenn are more than capable of defending their home from the lesser devourers. Nature will take its course.\n\nI will report back to Lord Herne and meet you at the Heart of the Forest. There we shall see what I will be hunting next.", objectives = "" }
WordHunterWoW_QuestEN[58454] = { title = "Spoiling For A Fight", description = "Your contribution of anima has aided our operation here greatly. Several of our more famous competitors have come here lured by the flow of new anima.\n\nWould you like to test yourself versus the famous Sabriel? There could be much profit for everyone, if you were to defeat her.\n\nI can add her to the schedule, she will appear soon if you defeat the other challengers.", objectives = "" }
WordHunterWoW_QuestEN[58455] = { title = "Shadowy Showdown", description = "This is our time! We've found where these Shadowy Figures have been hiding, and it's time for us to take the fight to them and stop whatever their plans are. Their base of operations is in Blackrock Depths. It's all up to you.", objectives = "" }
WordHunterWoW_QuestEN[58456] = { title = "Shadowy Showdown", description = "This is our time! We've found where these Shadowy Figures have been hiding, and it's time for us to take the fight to them and stop whatever their plans are. Their base of operations is in Blackrock Depths. It's all up to you.", objectives = "" }
WordHunterWoW_QuestEN[58457] = { title = "Shadows of Blackrock", description = "We've finally tracked those pesky Shadowy Figures down, they should all be in there. They seem highly skilled, you're going to need to bring your best teams in there if you have any chance of winning.\n\nLet me know when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[58458] = { title = "Pet Battle Challenge: Blackrock Depths", description = "Those Shadowy Figures are up to no good again, are you sure you want to face them? If you really want to go back in there, I'm not going to stop you.", objectives = "" }
WordHunterWoW_QuestEN[58460] = { title = "Marshals of Madness", description = "The n'raqi have long served as the commanders and taskmasters of the Old Gods' forces. Their presence on the field of battle shows that this invasion is a coordinated effort rather than a random outbreak of corruption.\n\nLed by these faceless masters, the chaotic forces of the Old Gods transform into capable military.\n\nWe must make it a priority to fell these creatures. Only then might we take the upper hand against N'Zoth.", objectives = "" }
WordHunterWoW_QuestEN[58461] = { title = "Tomes of Ancient Madness", description = "In times like these, it becomes necessary for all of the denizens of the Vale to pitch in and do their part. Unfortunately, I have never been much of a fighter, so my usefulness in times of war is limited.\n\nHowever, I may be able to do some good. You see, we know very little about the invaders we face, and knowledge can be a very powerful weapon.\n\nI think I have seen tomes carried by some of the k'thir. If you could bring some to me, I may be able to glean something useful from their writings.", objectives = "" }
WordHunterWoW_QuestEN[58462] = { title = "Windows to the Soul", description = "Were it not enough for our enemy to apply deadly force against us, their minions also strike into the very heart of our defenders.\n\nI speak, of course, of the eyes. They peer into the souls of our warriors and produce their darkest fears against them.\n\nIf we have any hope to defeat this foe, they must be destroyed.", objectives = "" }
WordHunterWoW_QuestEN[58463] = { title = "Spawns of Madness", description = "To see the Vale of Eternal Blossoms recover from the Sha to its former beauty, only to see it tainted by the Old Gods once more, it makes the blood boil!\n\nWe must root out the Old God's corruption before it can take hold of this land again. I have seen the fleshbeasts that accompany N'Zoth's forces spreading his corruption where they tread.\n\nMake sure they tread no longer.", objectives = "" }
WordHunterWoW_QuestEN[58464] = { title = "Deephive Decimation", description = "A sect of the mantid swarm calling themselves the \"Deephive\" have taken hold of the Big Blossom mine. These mantid have fully given themselves up to the Old Gods' corruption, making them especially dangerous.\n\nWe cannot allow the Deephive to run amok in the Vale. Do what must be done.", objectives = "" }
WordHunterWoW_QuestEN[58465] = { title = "Corruption Manifest", description = "The corruption of the Old Gods is often so foul it manifests itself in physical form. \n\nWe have seen this with the Sha. This time is no different.\n\nCull this corruption wherever you see it spread. It must not be left to flourish.", objectives = "" }
WordHunterWoW_QuestEN[58466] = { title = "Torment From Beyond", description = "As if it were not bad enough that N'Zoth seeks to dominate those living in the Vale, my scouts report they now seek to dominate the dead!\n\nThe Shado-Pan have their hands full defending the living. Can we rely on you to put an end to this disgrace?", objectives = "" }
WordHunterWoW_QuestEN[58467] = { title = "Prisoners of Mind and Body", description = "N'Zoth's forces struck the Vale suddenly. By the time I and my Shado-Pan arrived, many of the Golden Lotus had already been taken captive by the Old God's forces.\n\nEven with our combined might, we have only been able to hold off the invaders from taking more of our people. Those already taken, however, are still within the clutches of the Old God.\n\nI know we have had our differences, {name}, but if you could aid us in their recovery, the Shado-Pan would be in your debt.", objectives = "" }
WordHunterWoW_QuestEN[58468] = { title = "A Growing Darkness", description = "Shado-Pan scouts have spotted evidence of a new mantid hatchery within the Big Blossom mine. It seems these Deephive mantid are looking to create new corrupted spawn to serve N'Zoth.\n\nIf these eggs were allowed to hatch, a new swarm empowered by the Old God could blacken the skies of the Vale and plunge Pandaria into darkness.\n\nWe will not allow that to happen, will we?", objectives = "" }
WordHunterWoW_QuestEN[58469] = { title = "Tears in the Vale", description = "As N'Zoth's influence spreads within the Vale, our very reality begins to break down. \n\nThe Old God's power has created tears in the fabric our world, acting as doorways for his minions to invade from his dark realm.\n\nAs long as these tears exist, we will never be free from N'Zoth's grasp. Close them, and stem the tide of his corruption!", objectives = "" }
WordHunterWoW_QuestEN[58470] = { title = "Corrupted Curiosities", description = "I understand that the Black Empire poses a grave threat to Pandaria, but we may also use this as an opportunity!\n\nThough we've faced them several times before, very little is known about the Old Gods or N'Zoth's mysterious realm of Ny'alotha. \n\nWhen studying ancient civilizations, we often rely on artifacts to unlock the deepest mysteries lost to time. I wonder if some such artifacts could be found among the Old God's forces?\n\nIt can't hurt to check, right?", objectives = "" }
WordHunterWoW_QuestEN[58471] = { title = "Aggressive Notation", description = "Even given the Sha's origins with the Old Gods, we in Pandaria still know very little of them.\n\nI would like to take this opportunity to add whatever information I can about them to the archives of the Lorewalkers. Of course, that becomes a bit problematic when they're trying to kill us.\n\nThat doesn't seem to be a problem for you, though. Could you do me a favor and jot down some notes about what you encounter out there?  It could help a great deal towards understanding what we're fighting.", objectives = "" }
WordHunterWoW_QuestEN[58472] = { title = "A Farewell to Arms", description = "The Maldraxxi toil away just behind us. I care not if you consider them allies or traitors, so long as you remove them from Revendreth.\n\nDestroy their encampment. Purge it from our soil, and ensure such an affront never occurs again.\n\nThe means are not important. All that matters is that these heretics remember the consequences of trifling with true power.", objectives = "" }
WordHunterWoW_QuestEN[58473] = { title = "Echoes of Tirna Noch", description = "It is clear that we need more anima than this grove can provide. I may know of a way we can acquire some.\n\nMany of the masked fae have been collecting anima for some unknown purpose. I propose we take it back from them.\n\nThe Wild Hunt has tracked them to Tirna Noch... my former grove.\n\nLong has it been since I walked beneath its boughs. Not since it was left to wither so that other groves might survive.\n\nI remember it well...", objectives = "" }
WordHunterWoW_QuestEN[58476] = { title = "Bringing the Thunder", description = "All of the mogu clans are formidable, to be sure, but it is the Zan-Tien that pose the most direct threat to the Golden Lotus. \n\nEven now, their numbers are amassing outside the Golden Pagoda. Many of our warriors are fresh-faced and inexperienced. They would not withstand a mogu assault for long.\n\nAn experienced {class} like you could serve to slow them down significantly. \n\nCare to help?", objectives = "" }
WordHunterWoW_QuestEN[58477] = { title = "Through Blood and Dirt and Bone", description = "The Dokani see themselves fit to wield the ancient magic of anima, but their golems and manifestations are but a fraction of anima's true power.\n\nLiberate them of their prized substance, so that the Rajani may put it to better use.", objectives = "" }
WordHunterWoW_QuestEN[58478] = { title = "No Stone Unbroken", description = "When the warring clans came into the Vale, the Baruk deigned themselves worthy to lay claim to the ancient grounds of Guo-Lai.\n\nThey are not.\n\nShow these usurpers their place, and you may earn a modicum of favor with the Rajani.", objectives = "" }
WordHunterWoW_QuestEN[58479] = { title = "Lightning Crashes", description = "The Zan-Tien like to claim mastery over the power of storms, yet they resort to machines to harness lightning from the sky.\n\nShow these pretenders that the true power of storm and thunder comes from within. Break their toys, and see how they fare without.", objectives = "" }
WordHunterWoW_QuestEN[58480] = { title = "Read the Roots", description = "When my grove withered, I answered the Queen's call and joined the Wild Hunt.\n\nNothing can be done for Tirna Noch. But it wounds me to see it crawling with foes of the forest.\n\nWe need a great deal of anima. The masked fae must be keeping a stockpile somewhere within the grove--we just need to find it.\n\nThey likely used soulwebs to collect and move the anima. If I examine them, I should be able to pick up the trail.", objectives = "" }
WordHunterWoW_QuestEN[58481] = { title = "Rituals of Blood", description = "Anji and I have fought in many battles, so we know how to handle a few mogu, but the blood magic used by these Dokani is just unsettling!\n\nAs if it weren't bad enough for them to kill everyone in their path, but to use their corpses to fuel their unholy rituals? I just can't stomach it!\n\nDo me a favor. If you ever come across any of these rituals, put a stop to them! Even our enemies don't deserve to be defiled with their dark magic.", objectives = "" }
